def _handle_blocks(v):
    """the display of a handle object: its class and main properties"""
    name = v._mclass.split(".")[-1]
    if name == "Figure":
        name = "Figure (%d)" % int(_scalar(v.props.get("Number", 1.0)))
    keys = list(v.props)[:12]
