files._matlab_data.py:
"""MATLAB's data analysis and signal functions, for lib/_matlab.py: filter,
conv2 and filter2, gradient and del2, detrend, cov and corrcoef, prctile and
quantile, and the moving-window statistics.  Each registers a built-in in
_matlab's table (_bs/_bi), the same way lib/_matlab.py's do.  An option these
do not implement is refused with an error, never ignored.
"""

import math as _math

import numpy as np

import _matlab as _m
from _matlab import _bs, _bi, _err, _istext, _text, _scalar


def _md(x):
    """x as a float64 or complex128 array in MATLAB's axis order (at least 2-D)"""
    return np.transpose(_m._farr(x))


def _out(M, cls="double"):
    """an array in MATLAB's axis order as a MATLAB value of class cls"""
    return _m._finish(_m._canon(_m._contig(np.transpose(M))), cls)


def _cls(*xs):
    return "single" if any(_m.class_(x) == "single" for x in xs) else "double"


def _first_dim(shape):
    for k, s in enumerate(shape):
        if s != 1:
            return k
    return 0


def _dim_value(d):
    if _m._numel(d) != 1 or not _m._isnumlike(d) or _m._arr(d).dtype.kind == "c" and _m._arr(d).reshape(-1)[0].imag != 0:
        raise _err("Dimension argument must be a positive integer scalar within indexing range.", "MATLAB:getdimarg:invalidDim")
    v = _scalar(d)
    if not _math.isfinite(v) or v != _math.floor(v) or v < 1:
        raise _err("Dimension argument must be a positive integer scalar within indexing range.", "MATLAB:getdimarg:invalidDim")
    return int(v) - 1


def _to_front(M, axis):
    """M with axis first and the others flattened: (L, R) and how to undo it"""
    while M.ndim <= axis:
        M = M.reshape(M.shape + (1,))
    W = np.moveaxis(M, axis, 0)
    rest = W.shape[1:]
    return np.array(W).reshape((W.shape[0], -1)), (axis, rest, M.ndim)


def _from_front(F, how):
    axis, rest, _ = how
    W = F.reshape((F.shape[0],) + tuple(rest))
    return np.moveaxis(W, 0, axis)


def _vec(x):
    return _m._farr(x).reshape(-1)


# ------------------------------------------------------------------ filter

@_bi("filter")
def filter_(nargout, b, a, x, zi=None, dim=None):
    """[y, zf] = filter(b, a, x, zi, dim): the rational transfer function
    b(z)/a(z), in the transposed direct form II, along the first
    non-singleton dimension (or dim)"""
    B, A = _vec(b), _vec(a)
    if not B.size or not A.size:
        raise _err("Filter coefficients must be vectors.")
    if A[0] == 0:
        raise _err("First denominator filter coefficient must be non-zero.")
    B, A = B / A[0], A / A[0]
    n = max(B.size, A.size)
    B = np.concatenate([B, np.zeros(n - B.size, dtype=B.dtype)])
    A = np.concatenate([A, np.zeros(n - A.size, dtype=A.dtype)])
    X = _md(x)
    axis = _first_dim(X.shape) if dim is None else _dim_value(dim)
    F, how = _to_front(X, axis)
    L, R = F.shape
    cplx = F.dtype.kind == "c" or B.dtype.kind == "c" or A.dtype.kind == "c"
    dt = np.complex128 if cplx else np.float64
    z = np.zeros((n - 1, R), dtype=dt)
    if zi is not None and _m._numel(zi):
        Z = _md(zi)
        if Z.size != (n - 1) * R:
            raise _err("Initial conditions must be a vector of length max(length(a),length(b))-1, or an array with the "
                       "leading dimension of size max(length(a),length(b))-1 and with remaining dimensions matching those of x.")
        z = np.array(Z.reshape((n - 1, R)) if Z.ndim == 2 and Z.shape[0] == n - 1 else Z.reshape(-1).reshape((n - 1, R)), dtype=dt)
        cplx = cplx or z.dtype.kind == "c"
    Y = np.zeros((L, R), dtype=dt)
    if n == 1:
        Y = B[0] * F
    elif not np.any(A[1:]) and not np.any(z) and nargout < 2:
        # (FIR: a sum of the shifted inputs)
        for j in range(min(n, L)):
            if B[j] != 0:
                Y[j:] += B[j] * F[:L - j]
    else:
        b1, a1 = B[1:].reshape((-1, 1)), A[1:].reshape((-1, 1))
        for k in range(L):
            xk = F[k]
            yk = B[0] * xk + z[0]
            Y[k] = yk
            z = np.concatenate([z[1:], np.zeros((1, R), dtype=dt)]) + b1 * xk - a1 * yk
    y = _out(_from_front(Y, how), _cls(b, a, x))
    if nargout < 2:
        return y
    zshape = (n - 1,) + tuple(how[1])
    return [y, _out(z.reshape(zshape) if len(zshape) > 1 else z.reshape((n - 1, 1)), _cls(b, a, x))]


# ------------------------------------------------------------------ conv2, filter2

def _conv2_full(A, K):
    """the full 2-D convolution of matrices A and K (MATLAB orientation)"""
    if K.size > A.size:
        A, K = K, A
    ma, na = A.shape
    mk, nk = K.shape
    dt = np.result_type(A.dtype, K.dtype)
    C = np.zeros((max(ma + mk - 1, 0), max(na + nk - 1, 0)), dtype=dt)
    if not A.size or not K.size:
        return C
    for p in range(mk):
        for q in range(nk):
            if K[p, q] != 0:
                C[p:p + ma, q:q + na] += K[p, q] * A
    return C


def _shape_arg(s, default="full"):
    if s is None:
        return default
    t = _text(s).lower() if _istext(s) else None
    if t not in ("full", "same", "valid"):
        raise _err("SHAPE must be 'full', 'same', or 'valid'.")
    return t


def _conv2_shape(C, ma, na, mb, nb, shape):
    if shape == "same":
        r0, c0 = mb // 2, nb // 2
        return C[r0:r0 + ma, c0:c0 + na]
    if shape == "valid":
        rows, cols = max(ma - mb + 1, 0), max(na - nb + 1, 0)
        return C[mb - 1:mb - 1 + rows, nb - 1:nb - 1 + cols] if rows and cols else np.zeros((rows, cols), dtype=C.dtype)
    return C


@_bs("conv2")
def conv2_(*args):
    """conv2(A, B[, shape]); conv2(u, v, A[, shape]): A's columns by u, then its rows by v"""
    args = list(args)
    shape = _shape_arg(args.pop()) if args and _istext(args[-1]) else "full"
    if len(args) == 3:
        u, v = _vec(args[0]), _vec(args[1])
        A = _m._mat(args[2])
        K = u.reshape((-1, 1)) * v.reshape((1, -1))
        cls = _cls(*args)
    elif len(args) == 2:
        A, K = _m._mat(args[0]), _m._mat(args[1])
        cls = _cls(*args)
    else:
        raise _err("Not enough input arguments.")
    C = _conv2_full(A, K)
    return _m._finish(_m._contig(_conv2_shape(C, A.shape[0], A.shape[1], K.shape[0], K.shape[1], shape).T), cls)


@_bs("filter2")
def filter2_(h, X, shape=None):
    """the 2-D correlation of X with h: conv2(X, rot90(h, 2), shape), 'same' by default"""
    s = _shape_arg(shape, "same")
    H = _m._mat(h)[::-1, ::-1]
    A = _m._mat(X)
    C = _conv2_full(A, np.array(H))
    return _m._finish(_m._contig(_conv2_shape(C, A.shape[0], A.shape[1], H.shape[0], H.shape[1], s).T), _cls(h, X))


# ------------------------------------------------------------------ gradient, del2

def _spacing(args, axes, shape):
    """each axis's coordinates, from gradient's and del2's spacing arguments:
    none (1), one for every axis, or one per axis (x's first: dimension 2)"""
    if len(args) not in (0, 1, len(axes)):
        raise _err("Invalid inputs: the number of spacing values must be 1 or the number of dimensions.")
    out = []
    for k, ax in enumerate(axes):
        n = shape[ax]
        h = args[0] if len(args) == 1 else (args[k] if args else 1.0)
        H = _vec(h).real if not _istext(h) else None
        if H is None:
            raise _err("Spacing values must be numeric.")
        if H.size == 1:
            out.append(np.arange(n, dtype=np.float64) * float(H[0]))
        elif H.size == n:
            out.append(np.asarray(H, dtype=np.float64))
        else:
            raise _err("The length of a spacing vector must match the size of F in its dimension.")
    return out


def _grad_axes(M):
    """the axes gradient and del2 differentiate, in their outputs' order:
    a vector's own; else the columns' (2), the rows' (1), then 3, 4, ..."""
    if M.ndim == 2 and (M.shape[0] == 1 or M.shape[1] == 1):
        return [1 if M.shape[0] == 1 else 0]
    return [1, 0] + list(range(2, M.ndim))


def _grad1(F, x):
    """the derivative along axis 0 at coordinates x: central differences inside, one-sided at the ends"""
    n = F.shape[0]
    G = np.zeros(F.shape, dtype=F.dtype)
    if n < 2:
        return G
    x = x.reshape((-1,) + (1,) * (F.ndim - 1))
    G[0] = (F[1] - F[0]) / (x[1] - x[0])
    G[-1] = (F[-1] - F[-2]) / (x[-1] - x[-2])
    if n > 2:
        G[1:-1] = (F[2:] - F[:-2]) / (x[2:] - x[:-2])
    return G


@_bi("gradient")
def gradient_(nargout, F, *h):
    M = _md(F)
    axes = _grad_axes(M)
    if nargout > len(axes):
        raise _err("Too many output arguments.")
    coords = _spacing(h, axes, M.shape)
    outs = []
    for ax, x in list(zip(axes, coords))[:max(nargout, 1)]:
        G = np.moveaxis(_grad1(np.moveaxis(M, ax, 0), x), 0, ax)
        outs.append(_out(G, _cls(F)))
    return outs if nargout > 1 else outs[0]


def _extrapolate(xe, xa, ga, xb, gb):
    """the line through (xa, ga) and (xb, gb), at xe"""
    return ga + (xe - xa) * (gb - ga) / (xb - xa)


def _del2_1(F, x):
    """del2's term along axis 0: half the second derivative, by centered
    differences at the interior points; at the two ends, as MATLAB documents,
    the interior's second differences extrapolated linearly (from the two
    nearest; with one interior point, its value; with none, 0, as Octave's)"""
    n = F.shape[0]
    G = np.zeros(F.shape, dtype=F.dtype)
    if n < 3:
        return G
    shp = (-1,) + (1,) * (F.ndim - 1)
    h = np.diff(x).reshape(shp)
    # (the three-point second derivative, halved: ((F+ - F)/h+ - (F - F-)/h-) / (h- + h+))
    G[1:-1] = ((F[2:] - F[1:-1]) / h[1:] - (F[1:-1] - F[:-2]) / h[:-1]) / (h[:-1] + h[1:])
    if n == 3:
        G[0] = G[-1] = G[1]
    else:
        G[0] = _extrapolate(x[0], x[1], G[1], x[2], G[2])
        G[-1] = _extrapolate(x[-1], x[-2], G[-2], x[-3], G[-3])
    return G


@_bs("del2")
def del2_(U, *h):
    """the discrete Laplacian over 2N (N the number of dimensions, at least 2):
    so (u_xx + u_yy)/4 for a matrix, u_xx/4 for a vector"""
    M = _md(U)
    axes = _grad_axes(M)
    coords = _spacing(h, axes, M.shape)
    L = np.zeros(M.shape, dtype=M.dtype)
    for ax, x in zip(axes, coords):
        L = L + np.moveaxis(_del2_1(np.moveaxis(M, ax, 0), x), 0, ax)
    return _out(L / max(M.ndim, 2), _cls(U))


# ------------------------------------------------------------------ detrend

@_bs("detrend")
def detrend_(x, *args):
    """x less its least-squares polynomial of degree n (1, 'linear', by
    default; 0, 'constant'), down each column (a vector along its length)"""
    deg = 1
    if args:
        a = args[0]
        if _istext(a):
            s = _text(a).lower()
            if s not in ("constant", "linear"):
                raise _err("detrend: the option '%s' is not supported in Sagebrush." % _text(a))
            deg = 0 if s == "constant" else 1
        else:
            v = _scalar(a)
            if v != _math.floor(v) or v < 0:
                raise _err("Polynomial degree must be a nonnegative integer.")
            deg = int(v)
    if len(args) > 1:
        raise _err("detrend: breakpoints and further options are not supported in Sagebrush.")
    M = _md(x)
    vec = M.ndim == 2 and M.shape[0] == 1
    F, how = _to_front(M, 1 if vec else 0)
    L = F.shape[0]
    if L == 0:
        return x
    c = (L - 1) / 2.0
    t = (np.arange(L, dtype=np.float64) - c) / max(c, 1.0)  # (in [-1, 1], for the conditioning)
    V = np.stack([t ** k for k in range(deg, -1, -1)], axis=1)
    R = F - V @ _m._qr_solve(V, F)
    return _out(_from_front(R, how), _cls(x))


# ------------------------------------------------------------------ cov, corrcoef

def _nanflag_ok(args, fname):
    """drop 'includenan' (the default); refuse what is not implemented"""
    rest = []
    for a in args:
        if _istext(a):
            s = _text(a).lower()
            if s == "includenan":
                continue
            raise _err("%s: the option '%s' is not supported in Sagebrush." % (fname, _text(a)))
        rest.append(a)
    return rest


def _variables(x, y=None):
    """observations by rows, variables by columns: a vector is one variable;
    with y, x(:) and y(:) are two"""
    if y is not None:
        X, Y = _vec(x), _vec(y)
        if X.size != Y.size:
            raise _err("All inputs must have the same number of elements.", "MATLAB:cov:XYlengthMismatch")
        return np.stack([X, Y], axis=1)
    M = _m._mat(x)
    if M.shape[0] == 1:
        M = M.reshape((-1, 1))
    return M


def _cov(X, w):
    """the covariance of the columns, as MATLAB documents it:
    C(i, j) = sum(conj(x_i - mean x_i) .* (x_j - mean x_j)) / (n - 1), or / n
    with w = 1 (and with one observation); each entry from its own two
    columns, so a NaN in one variable leaves the others' entries alone"""
    n, k = X.shape
    if n == 0:
        return np.full((k, k), _math.nan)
    Xc = X - np.sum(X, axis=0) / n
    den = n - 1 if (w == 0 and n > 1) else n
    C = np.zeros((k, k), dtype=Xc.dtype)
    for i in range(k):
        for j in range(k):
            C[i, j] = np.sum(np.conj(Xc[:, i]) * Xc[:, j]) / den
    return C


def _cov_args(x, args, fname):
    args = _nanflag_ok(args, fname)
    y, w = None, 0
    if args:
        a = args[0]
        if _m._numel(a) == 1 and _m._numel(x) != 1 and _scalar(a) in (0.0, 1.0) and len(args) == 1:
            w = int(_scalar(a))
        else:
            y = a
            if len(args) > 1:
                w = _m._int_arg(args[1], "weight")
    if w not in (0, 1):
        raise _err("W must be 0 or 1.")
    return y, w


@_bs("cov")
def cov_(x, *args):
    y, w = _cov_args(x, args, "cov")
    C = _cov(_variables(x, y), w)
    return _m._finish(_m._contig(C.T), _cls(x, *([y] if y is not None else [])))


@_bi("corrcoef")
def corrcoef_(nargout, x, *args):
    if nargout > 1:
        raise _err("corrcoef: the p-values and confidence bounds are not supported in Sagebrush.")
    args = list(args)
    if len(args) >= 2 and _istext(args[-2]) and _text(args[-2]).lower() == "rows":
        if _text(args[-1]).lower() != "all":
            raise _err("corrcoef: 'Rows', '%s' is not supported in Sagebrush." % _text(args[-1]))
        args = args[:-2]
    if any(_istext(a) for a in args):
        raise _err("corrcoef: the option '%s' is not supported in Sagebrush." % _text([a for a in args if _istext(a)][0]))
    if len(args) > 1:
        raise _err("Too many input arguments.")
    y = args[0] if args else None
    # (one observation, as MATLAB documents it: corrcoef(A) of a scalar is
    # NaN; of two scalars, 1, or NaN when they are equal)
    if _m._numel(x) == 1 and (y is None or _m._numel(y) == 1):
        if y is None:
            return _math.nan
        a, b = _vec(x)[0], _vec(y)[0]
        return 1.0 if a != b and a == a and b == b else _math.nan
    C = _cov(_variables(x, y), 0)
    # (as MATLAB documents: R(i, j) = C(i, j) / (sigma_i sigma_j), the
    # coefficients between -1 and 1, and the diagonal 1 by convention, also
    # for a constant variable; NaN for a variable with NaN, as Octave's)
    s = np.sqrt(np.real(np.diag(C)))
    with np.errstate(invalid="ignore", divide="ignore"):
        R = C / (s.reshape((-1, 1)) * s.reshape((1, -1)))
    m = np.abs(R)
    R = np.where(m > 1, R / np.where(m > 1, m, 1.0), R)
    ok = ~np.isnan(s)
    for i in range(R.shape[0]):
        R[i, i] = 1.0 if ok[i] else _math.nan
    return _m._finish(_m._contig(R.T), _cls(x, *([y] if y is not None else [])))


# ------------------------------------------------------------------ prctile, quantile

def _quantiles(S, p):
    """the p quantiles (0..1) of sorted values S, by MATLAB's method: S(i) is
    the (i - 0.5)/n quantile, linear between, the extremes beyond"""
    n = S.size
    if n == 0:
        return np.full(p.size, _math.nan)
    if n == 1:
        return np.full(p.size, S[0])
    t = n * p + 0.5  # (the 1-based position)
    lo = np.clip(np.floor(t).astype(np.int64), 1, n - 1)
    f = np.clip(t - lo, 0.0, 1.0)
    return S[lo - 1] + f * (S[lo] - S[lo - 1])


def _quantile_impl(x, p, rest, scale, fname):
    if _istext(p):
        raise _err("%s: the probabilities must be numeric." % fname)
    P = _vec(p).real / scale
    if fname == "quantile" and P.size == 1 and _scalar(p) > 1:
        N = _scalar(p)
        if N != _math.floor(N):
            raise _err("N must be a positive integer.")
        P = np.arange(1, int(N) + 1) / (N + 1)
    if np.any((P < 0) | (P > 1)) or np.any(np.isnan(P)):
        raise _err("P must be a scalar or a vector of %s between 0 and %s." % (("percent values", "100") if scale == 100 else ("probabilities", "1")))
    rest = list(rest)
    dim = None
    while rest:
        a = rest.pop(0)
        if _istext(a):
            s = _text(a).lower()
            if s == "method" and rest and _text(rest[0]).lower() == "exact":
                rest.pop(0)
                continue
            raise _err("%s: the option '%s' is not supported in Sagebrush." % (fname, _text(a)))
        dim = _dim_value(a)
    M = _md(x)
    if np.iscomplexobj(M):
        raise _err("%s: complex values are not supported." % fname)
    axis = _first_dim(M.shape) if dim is None else dim
    F, how = _to_front(M, axis)
    out = np.zeros((P.size, F.shape[1]))
    for c in range(F.shape[1]):
        col = F[:, c]
        S = np.sort(col[~np.isnan(col)])  # (NaN: missing)
        out[:, c] = _quantiles(S, P)
    d = _m._dims(x)
    if dim is None and len(d) == 2 and min(d) <= 1 and P.size > 1:
        # (a vector A, no dim: Q has p's orientation, as the page says, a vector "with the
        # same length as p"; only generated code follows A's)
        pd = _m._dims(p)
        Q = out[:, 0]
        return _out(Q.reshape((1, -1)) if pd[0] == 1 else Q.reshape((-1, 1)), _cls(x))
    return _out(_from_front(out, how), _cls(x))


@_bs("prctile")
def prctile_(x, p, *rest):
    return _quantile_impl(x, p, rest, 100.0, "prctile")


@_bs("quantile")
def quantile_(x, p, *rest):
    return _quantile_impl(x, p, rest, 1.0, "quantile")


# ------------------------------------------------------------------ moving statistics

def _window(k):
    K = _vec(k).real
    if K.size == 1:
        v = float(K[0])
        if v != _math.floor(v) or v < 1:
            raise _err("Window length must be a positive integer scalar (Sagebrush has no 'SamplePoints').")
        n = int(v)
        return (n // 2, n // 2 - 1) if n % 2 == 0 else ((n - 1) // 2, (n - 1) // 2)
    if K.size == 2:
        if np.any(K != np.floor(K)) or np.any(K < 0):
            raise _err("Window length must be a 2-element vector of nonnegative integers.")
        return int(K[0]), int(K[1])
    raise _err("Window length must be a finite, positive scalar or a 2-element vector of nonnegative values.")


def _mov_args(args, fname, takes_w):
    """(w, axis or None, omitnan, endpoints) from a moving statistic's options"""
    args = list(args)
    w, axis, omit, ends = 0, None, False, "shrink"
    if takes_w and args and not _istext(args[0]):
        if _m._numel(args[0]):
            w = _m._int_arg(args[0], "weight")
            if w not in (0, 1):
                raise _err("W must be 0 or 1.")
        args.pop(0)
    while args:
        a = args.pop(0)
        if _istext(a):
            s = _text(a).lower()
            if s in ("includenan", "omitnan"):
                omit = s == "omitnan"
            elif s == "endpoints":
                if not args:
                    raise _err("Endpoints needs a value.")
                e = args.pop(0)
                if _istext(e):
                    ends = _text(e).lower()
                    if ends not in ("shrink", "discard", "fill"):
                        raise _err("Endpoints must be 'shrink', 'discard', 'fill', or a numeric scalar.")
                else:
                    ends = _scalar(e)
            else:
                raise _err("%s: the option '%s' is not supported in Sagebrush." % (fname, _text(a)))
        else:
            axis = _dim_value(a)
    return w, axis, omit, ends


def _moving(A, kb, kf, stat, w, omit, ends):
    """stat over each window [i-kb, i+kf] down axis 0 of A (L-by-R)"""
    L, R = A.shape
    fill = ends == "fill" or not isinstance(ends, str)
    if fill:
        # (Endpoints "fill" or a value: the nonexisting elements are NaN or that value, as
        # movmean's page says, so they take part in the statistic, its count and its
        # variance's denominator; with "omitnan" the filled NaNs are left out. Each
        # window's positions outside the data read as the value, so the work is the
        # same as 'shrink''s, L times the window, with no padded copy)
        v = _math.nan if ends == "fill" else ends
        A = A.astype(np.result_type(A.dtype, np.float64, np.asarray(v).dtype))
    offs = range(-kb, kf + 1)

    def shifted(o):
        """A[i+o] at each i, with whether it is in range (with a fill, every position is:
        the fill value outside the data)"""
        S = np.full(A.shape, v, dtype=A.dtype) if fill else np.zeros(A.shape, dtype=A.dtype)
        ok = np.full(A.shape, fill, dtype=bool)
        lo, hi = max(0, -o), min(L, L - o)
        if hi > lo:
            S[lo:hi] = A[lo + o:hi + o]
            ok[lo:hi] = True
        return S, ok

    # (the values in each window, and whether one is NaN)
    cnt = np.zeros(A.shape)
    hasnan = np.zeros(A.shape, dtype=bool)
    for o in offs:
        S, ok = shifted(o)
        isn = ok & np.isnan(S)
        hasnan |= isn
        cnt += ok & ~isn
    if stat in ("sum", "mean", "prod", "var", "std"):
        acc = np.zeros(A.shape, dtype=A.dtype) if stat != "prod" else np.ones(A.shape, dtype=A.dtype)
        for o in offs:
            S, ok = shifted(o)
            use = ok & ~np.isnan(S)
            if stat == "prod":
                acc = acc * np.where(use, S, 1)
            else:
                acc = acc + np.where(use, S, 0)
        if stat in ("mean", "var", "std"):
            with np.errstate(invalid="ignore", divide="ignore"):
                mean = acc / cnt
            if stat == "mean":
                res = mean
            else:
                ss = np.zeros(A.shape)
                for o in offs:
                    S, ok = shifted(o)
                    use = ok & ~np.isnan(S)
                    ss = ss + np.where(use, np.abs(S - mean) ** 2, 0)
                den = np.where((w == 0) & (cnt > 1), cnt - 1, cnt)
                with np.errstate(invalid="ignore", divide="ignore"):
                    res = np.where(cnt == 1, 0.0, ss / den)
                    res = np.where(cnt == 0, _math.nan, res)
                if stat == "std":
                    res = np.sqrt(res)
        else:
            res = acc
    elif stat in ("max", "min"):
        big = np.inf if stat == "min" else -np.inf
        res = np.full(A.shape, big)
        for o in offs:
            S, ok = shifted(o)
            use = ok & ~np.isnan(S)
            res = np.where(use, np.minimum(res, S) if stat == "min" else np.maximum(res, S), res)
        res = np.where(cnt == 0, _math.nan, res)
    else:  # (median: each window's values sorted, the missing ones, NaN, last)
        W = np.full((len(offs),) + A.shape, np.inf)
        for t, o in enumerate(offs):
            S, ok = shifted(o)
            W[t] = np.where(ok & ~np.isnan(S), S, np.inf)
        W = np.sort(W, axis=0)
        m = cnt.astype(np.int64)
        lo = _m._take_along(W, np.maximum((m - 1) // 2, 0).reshape((1,) + A.shape), 0)[0]
        hi = _m._take_along(W, np.maximum(m // 2, 0).reshape((1,) + A.shape), 0)[0]
        with np.errstate(invalid="ignore"):
            res = np.where(m % 2 == 1, lo, lo + (hi - lo) / 2)
        res = np.where(m == 0, _math.nan, res)
    if not omit:
        res = np.where(hasnan, _math.nan, res)
    # (the windows wholly inside the data)
    i = np.arange(L)
    complete = (i - kb >= 0) & (i + kf <= L - 1)
    if ends == "discard":
        return res[np.nonzero(complete)[0]]
    return res


def _mov(stat, fname, takes_w=False):
    def f(nargout, x, k, *args):
        kb, kf = _window(k)
        w, axis, omit, ends = _mov_args(args, fname, takes_w)
        M = _md(x)
        if stat == "median" and np.iscomplexobj(M):
            raise _err("%s: complex values are not supported." % fname)
        if stat in ("max", "min") and np.iscomplexobj(M):
            raise _err("%s: complex values are not supported in Sagebrush." % fname)
        if axis is None:
            axis = _first_dim(M.shape)
        F, how = _to_front(M, axis)
        res = _moving(F, kb, kf, stat, w, omit, ends)
        return _out(_from_front(res, how), _cls(x))
    _bi(fname)(f)
    return f


movsum_ = _mov("sum", "movsum")
movmean_ = _mov("mean", "movmean")
movprod_ = _mov("prod", "movprod")
movmax_ = _mov("max", "movmax")
movmin_ = _mov("min", "movmin")
movmedian_ = _mov("median", "movmedian")
movvar_ = _mov("var", "movvar", True)
movstd_ = _mov("std", "movstd", True)

files._matlab_funfun.py:
"""MATLAB's function functions, for lib/_matlab.py: the optimization
options (optimset, optimget) and, as they are added, the solvers that take
them.  Each comes from MATLAB's documentation pages and the published
algorithms its docstring cites; where neither fixes a detail, the choice is
Sagebrush's own and says so.  Each registers a built-in in _matlab's table
(_bs/_bi), the same way lib/_matlab.py's do.
"""

import math as _math

import numpy as np

import _matlab as _m
from _matlab import _bs, _bi, _err, _istext, _text

# ------------------------------------------------------------------ optimset, optimget

# (the options the optimset page documents, in its order)
_OPTIONS = ["Display", "FunValCheck", "MaxFunEvals", "MaxIter", "OutputFcn", "PlotFcns", "TolFun", "TolX"]

# (each solver's defaults, as the optimset page gives them; a default that
# depends on the problem, such as fminsearch's 200 times the number of
# variables, stays empty, and the solver applies it)
_EPS = 2.220446049250313e-16
_DEFAULTS = {
    "fzero": {"Display": "notify", "FunValCheck": "off", "TolX": _EPS},
    "fminbnd": {"Display": "notify", "FunValCheck": "off", "MaxFunEvals": 500.0, "MaxIter": 500.0, "TolX": 1e-4},
    "fminsearch": {"Display": "notify", "FunValCheck": "off", "TolFun": 1e-4, "TolX": 1e-4},
    "lsqnonneg": {"Display": "notify"},
}


def _option_name(name, fname="optimset"):
    """an option's full name from enough leading characters, case ignored,
    as the optimset page allows"""
    low = name.lower()
    exact = [o for o in _OPTIONS if o.lower() == low]
    if exact:
        return exact[0]
    hits = [o for o in _OPTIONS if o.lower().startswith(low)]
    if len(hits) == 1 and low:
        return hits[0]
    if not hits:
        raise _err("%s: unrecognized parameter name '%s'." % (fname, name))
    raise _err("%s: ambiguous parameter name '%s' (%s)." % (fname, name, ", ".join(hits)))


def _check_value(name, v):
    """an option's value as the optimset page allows it (its listing:
    Display and FunValCheck one of their words, stored in lower case;
    MaxFunEvals and MaxIter positive integers; TolFun and TolX nonnegative
    real scalars; OutputFcn a function handle or a cell array of them), or
    [] for unset; PlotFcns, whose predefined plot functions Sagebrush does
    not have, is refused"""
    if v is None or _is_empty(v):
        return v
    if name in ("Display", "FunValCheck"):
        words = ("notify", "final", "off", "none", "iter") if name == "Display" else ("on", "off")
        if not _istext(v) or _text(v).lower() not in words:
            raise _err("optimset: %s must be %s." % (name, ", ".join("'%s'" % w for w in words[:-1]) + " or '%s'" % words[-1]))
        return _m.Char(_text(v).lower())
    if name in ("MaxFunEvals", "MaxIter", "TolFun", "TolX"):
        ok = not _istext(v) and _m._isnumlike(v) and type(v) is not _m.Sparse and _m._numel(v) == 1 \
            and not np.iscomplexobj(_m._arr(v))
        x = float(_m._scalar(v)) if ok else _math.nan
        if name in ("MaxFunEvals", "MaxIter"):
            if not (ok and x > 0 and x == _math.floor(x) and _math.isfinite(x)):
                raise _err("optimset: %s must be a positive integer." % name)
        elif not (ok and x >= 0):
            raise _err("optimset: %s must be a nonnegative real scalar." % name)
        return v
    if name == "OutputFcn":
        fs = v.a if type(v) is _m.Cell else [v]
        if not all(_m._iscallable(f) for f in fs):
            raise _err("optimset: OutputFcn must be a function handle or a cell array of function handles.")
        return v
    if name == "PlotFcns":
        raise _err("optimset: the PlotFcns option is not supported in Sagebrush.")
    return v


def _empty():
    return np.zeros((0, 0))


def _value(v):
    return _m.Char(v) if isinstance(v, str) else v


def _new_options():
    return {o: _empty() for o in _OPTIONS}


def _is_empty(v):
    return _m._isnumlike(v) and type(v) is not _m.Char and _m._numel(v) == 0


@_bi("optimset")
def optimset_(nargout, *args):
    """optimset as documented: optimset() is a structure of every option,
    all []; optimset(solver) (a name or handle of fzero, fminbnd,
    fminsearch or lsqnonneg) holds that solver's defaults; Name, Value pairs
    (enough leading characters, case ignored) set options, starting from an
    old structure if one is given; optimset(oldopts, newopts) takes
    newopts' nonempty values over oldopts'.  With neither arguments nor an
    output it lists the options and their values (in Sagebrush's own
    format)"""
    args = list(args)
    if not args:
        if nargout == 0:
            for o, vals in (("Display", "'notify' | 'final' | 'off' | 'none' | 'iter'"), ("FunValCheck", "'off' | 'on'"),
                            ("MaxFunEvals", "positive integer"), ("MaxIter", "positive integer"),
                            ("OutputFcn", "function | cell array of functions"), ("PlotFcns", "function | cell array of functions"),
                            ("TolFun", "nonnegative scalar"), ("TolX", "nonnegative scalar")):
                _m._write("%15s: %s\n" % (o, vals))
            return _m.NOVAL
        return _m._struct1(_new_options())
    opts = _new_options()
    if len(args) == 1 and (_istext(args[0]) or _m._iscallable(args[0])):
        name = _text(args[0]) if _istext(args[0]) else getattr(args[0], "name", None) or _text(_m._B["func2str"].f(1, args[0])).lstrip("@")
        if name not in _DEFAULTS:
            raise _err("optimset: no default options for '%s' (fzero, fminbnd, fminsearch and lsqnonneg have them)." % name)
        for k, v in _DEFAULTS[name].items():
            opts[k] = _value(v)
        return _m._struct1(opts)
    if args and type(args[0]) is _m.Struct:
        old = args.pop(0)
        if _m._numel(old) != 1:
            raise _err("optimset: an options structure must be a scalar structure.")
        for k, v in old.a[0].items():
            name = _option_name(k)
            opts[name] = _check_value(name, v)
        if args and type(args[0]) is _m.Struct:
            new = args.pop(0)
            if args or _m._numel(new) != 1:
                raise _err("optimset: optimset(oldopts, newopts) takes two options structures.")
            for k, v in new.a[0].items():
                if not _is_empty(v):
                    name = _option_name(k)
                    opts[name] = _check_value(name, v)
            return _m._struct1(opts)
    if len(args) % 2:
        raise _err("optimset: name-value arguments must come in pairs.")
    for k in range(0, len(args), 2):
        if not _istext(args[k]):
            raise _err("optimset: a parameter name must be text.")
        name = _option_name(_text(args[k]))
        opts[name] = _check_value(name, args[k + 1])
    return _m._struct1(opts)


@_bi("optimget")
def optimget_(nargout, options, name, *default):
    """optimget as documented: the value of the option with that name
    (enough leading characters, case ignored) in an options structure, or
    the given default when it is not set (absent or [])"""
    if type(options) is not _m.Struct or _m._numel(options) != 1:
        raise _err("optimget: the first input must be an options structure.")
    if not _istext(name):
        raise _err("optimget: the parameter name must be text.")
    if len(default) > 1:
        raise _err("Too many input arguments.")
    full = _option_name(_text(name), "optimget")
    d = options.a[0]
    v = next((d[k] for k in d if k.lower() == full.lower()), None)
    if v is None or _is_empty(v):
        return default[0] if default else _empty()
    return v


# ------------------------------------------------------------------ the solvers' common parts

def _opt(options, name, solver=None):
    """an option's value from an options structure, or the solver's
    default (as optimset gives it) when it is absent or [] (None with no
    solver)"""
    v = None
    if options is not None:
        d = options.a[0]
        v = next((d[k] for k in d if k.lower() == name.lower()), None)
    if v is None or _is_empty(v):
        v = _DEFAULTS[solver].get(name) if solver else None
    if v is not None and _istext(v):
        # (the option words in any case, also from a structure built by hand)
        v = _text(v).lower() if name in ("Display", "FunValCheck") else _text(v)
    return v


def _options_arg(options, solver):
    if options is None or _is_empty(options):
        return None
    if type(options) is not _m.Struct or _m._numel(options) != 1:
        raise _err("%s: options must be a scalar structure, typically made by optimset." % solver)
    return options


def _display(options, solver):
    v = _opt(options, "Display", solver)
    v = "off" if v == "none" else v
    if v not in ("off", "iter", "final", "notify"):
        raise _err("%s: Display must be 'notify', 'final', 'off', 'none' or 'iter'." % solver)
    return v


def _output_fcns(options, solver):
    """the OutputFcn option as a list of functions; PlotFcns, which would
    need MATLAB's predefined plot functions, is refused"""
    if _opt(options, "PlotFcns", solver) is not None:
        raise _err("%s: the PlotFcns option is not supported in Sagebrush." % solver)
    v = _opt(options, "OutputFcn", solver)
    if v is None:
        return []
    fs = v.a if type(v) is _m.Cell else [v]
    return [_m._fn_arg(f) for f in fs]


def _call_output(fcns, x, values, state):
    """call each output function as stop = outfun(x, optimValues, state);
    true if any asks to stop.  The start is two calls, 'init' and then
    'iter' for iteration 0, as the published history an fminsearch output
    function records shows"""
    stop = False
    for st in (("init", "iter") if state == "init" else (state,)):
        for f in fcns:
            r = _m._call(f, [x, _m._struct1(dict(values)), _m.Char(st)])
            stop = _m._logical_val(r) or stop
        if stop:
            break
    return stop


def _single_round(v):
    return float(np.float32(v))


def _same_round(v):
    return v


# ------------------------------------------------------------------ fzero

class _ZeroFun:
    """fun for fzero: a real scalar value of a real scalar x, counted; its
    precision is single once x0 or a value is single"""

    def __init__(self, f, single, check):
        self.f, self.single, self.check, self.count = f, single, check, 0

    def __call__(self, x):
        arg = _m._canon(np.array([[x]], dtype=np.float32)) if self.single else x
        r = _m._call(self.f, [arg])
        self.count += 1
        if not _m._isnumlike(r) or type(r) is _m.Char or _m._numel(r) != 1:
            raise _err("fzero: the function must return a numeric scalar.")
        if _m.class_(r) == "single":
            self.single = True
        a = _m._arr(r).reshape(-1)[0]
        if np.iscomplexobj(a) and a.imag != 0:
            if self.check:
                raise _err("fzero: the function returned a complex value at x = %g (FunValCheck is on)." % x)
            return complex(a)
        v = float(a.real) if np.iscomplexobj(a) else float(a)
        if self.check and not _math.isfinite(v):
            raise _err("fzero: the function returned %s at x = %g (FunValCheck is on)." % (_m._special(v), x))
        return _single_round(v) if self.single else v


def _changes_sign(u, v):
    return u == 0 or v == 0 or (u < 0) != (v < 0)


def _fzero_row(count, x, fx, proc):
    _m._write("%5.0f%16.6g%14.6g        %s\n" % (count, x, fx, proc))


def _fzero_search_row(count, a, fa, b, fb, proc):
    _m._write("%5.0f%16.6g%14.6g%14.6g%14.6g               %s\n" % (count, a, fa, b, fb, proc))


def _fzero_search(F, x0, show, outs):
    """Look outward from a scalar x0 for a sign change.  As fzero's
    published iterative displays show, step k tries a = x0 - dx*sqrt(2)^k
    and then b = x0 + dx*sqrt(2)^k, with dx = x0/50, and stops at the first
    value whose sign differs from the other end's.  For x0 = 0, where that
    rule gives no step, the search is on the scale of 0.1: dx = 0.1/50.
    That scale is GNU Octave's (observed: Octave's fzero tries the same
    multiples of x0 from any start, 0.99 x0, 1.025 x0, 0.95 x0, ..., and
    from x0 = 0 exactly those multiples of 0.1: 0.099, 0.1025, 0.095, ...).
    Ending the search (exitflag -6) when the next a or b would overflow is
    Sagebrush's own choice.  Returns
    (a, fa, b, fb, k, flag, x, fx) where flag is None when it found a sign
    change"""
    fx0 = F(x0)
    R = _single_round if F.single else _same_round
    if show:
        _m._write("Search for an interval around %g containing a sign change:\n" % x0)
        _m._write(" Func-count    a          f(a)             b          f(b)                    Procedure\n")
        if type(fx0) is complex:
            _m._write("%5.0f%16.6g%14s%14.6g%14s               initial interval\n" % (1, x0, "complex", x0, "complex"))
        else:
            _fzero_search_row(1, x0, fx0, x0, fx0, "initial interval")
    vals = {"funccount": 1.0, "fval": fx0, "iteration": 0.0, "procedure": _m.Char("initial interval")}
    if type(fx0) is complex:
        return None, None, None, None, 0, -4, x0, fx0
    if not _math.isfinite(fx0):
        return None, None, None, None, 0, -3, x0, fx0
    if outs and _call_output(outs, x0, vals, "init"):
        return None, None, None, None, 0, -1, x0, fx0
    a = b = x0
    fa = fb = fx0
    if fx0 == 0:
        return a, fa, b, fb, 0, None, x0, fx0
    dx = (x0 if x0 != 0 else 0.1) / 50
    k = 0
    while True:
        k += 1
        try:
            step = R(_math.ldexp(dx, k // 2) * (_math.sqrt(2) if k % 2 else 1.0))
        except OverflowError:
            # (math.ldexp raises, as CPython's, beyond the doubles: out of range, below)
            step = _math.inf
        na, nb = R(x0 - step), R(x0 + step)
        if not (_math.isfinite(na) and _math.isfinite(nb)):
            return a, fa, b, fb, k - 1, -6, None, None
        a = na
        fa = F(a)
        bad = type(fa) is complex or not _math.isfinite(fa)
        if bad or not _changes_sign(fa, fb):
            if not bad:
                b = nb
                fb = F(b)
                bad = type(fb) is complex or not _math.isfinite(fb)
        if show:
            if type(fa) is complex or type(fb) is complex:
                _m._write("%5.0f%16.6g%14s%14.6g%14s               search\n" % (F.count, a, _fmt_val(fa), b, _fmt_val(fb)))
            else:
                _fzero_search_row(F.count, a, fa, b, fb, "search")
        for x, fx in ((a, fa), (b, fb)):
            if type(fx) is complex:
                return a, fa, b, fb, k, -4, x, fx
            if not _math.isfinite(fx):
                return a, fa, b, fb, k, -3, x, fx
        vals = {"funccount": float(F.count), "fval": fb, "iteration": float(k), "procedure": _m.Char("search")}
        if outs and _call_output(outs, b, vals, "iter"):
            return a, fa, b, fb, k, -1, b, fb
        if _changes_sign(fa, fb):
            return a, fa, b, fb, k, None, None, None


def _fmt_val(v):
    return "complex" if type(v) is complex else "%.6g" % v


def _fzero_brent(F, a, fa, b, fb, tol, show, outs, it0):
    """Brent's zero-finder (R. P. Brent, Algorithms for Minimization without
    Derivatives, Prentice-Hall 1973, chapter 4, procedure zero; the Fortran
    zeroin of Forsythe, Malcolm and Moler, Computer Methods for Mathematical
    Computations, Prentice-Hall 1976, section 7.2): on [a, b], where f
    changes sign, keep b the best point and c the other end of the
    bracket, and take an inverse quadratic (or, with two points, secant)
    step when it falls well inside the bracket and shrinks fast enough, and
    bisection otherwise, until the bracket is within
    tol1 = 2*u*|b| + tol/2 (u the unit roundoff, 2^-53 or 2^-24 in single)
    or f(b) = 0.  Each step rounds in the working precision.  Returns
    (b, fb, iterations, stopped by an output function)"""
    R = _single_round if F.single else _same_round
    u = 2.0 ** -24 if F.single else 2.0 ** -53
    tol = R(tol)
    c, fc = a, fa
    d = e = R(b - a)
    proc = "initial"
    it = 0
    while True:
        if abs(fc) < abs(fb):
            a, b, c = b, c, b
            fa, fb, fc = fb, fc, fb
        if show:
            _fzero_row(F.count, b, fb, proc)
        if it and outs:
            vals = {"funccount": float(F.count), "fval": fb, "iteration": float(it0 + it), "procedure": _m.Char(proc)}
            if _call_output(outs, b, vals, "iter"):
                return b, fb, it, True
        tol1 = R(R(2 * u * abs(b)) + R(0.5 * tol))
        xm = R(0.5 * R(c - b))
        if abs(xm) <= tol1 or fb == 0:
            return b, fb, it, False
        proc = "bisection"
        if abs(e) >= tol1 and abs(fa) > abs(fb):
            s = R(fb / fa)
            if a == c:
                p = R(R(2 * xm) * s)
                q = R(1 - s)
            else:
                q = R(fa / fc)
                r = R(fb / fc)
                p = R(s * R(R(R(R(2 * xm) * q) * R(q - r)) - R(R(b - a) * R(r - 1))))
                q = R(R(R(q - 1) * R(r - 1)) * R(s - 1))
            if p > 0:
                q = -q
            else:
                p = -p
            if R(2 * p) < R(R(R(3 * xm) * q) - abs(R(tol1 * q))) and p < abs(R(R(0.5 * e) * q)):
                e = d
                d = R(p / q)
                proc = "interpolation"
        if proc == "bisection":
            d = e = xm
        a, fa = b, fb
        b = R(b + d) if abs(d) > tol1 else R(b + (tol1 if xm > 0 else -tol1))
        fb = F(b)
        it += 1
        if type(fb) is complex or fb != fb:
            raise _err("fzero: the function returned %s at x = %g, inside the interval; fzero cannot continue."
                       % ("a complex value" if type(fb) is complex else "NaN", b))
        if (fb > 0 and fc > 0) or (fb < 0 and fc < 0):
            c, fc = a, fa
            d = e = R(b - a)


@_bi("fzero")
def fzero_(nargout, *args):
    """fzero as its documentation page describes it: fzero(fun, x0),
    fzero(fun, x0, options) and fzero(problem), with outputs
    [x, fval, exitflag, output].  A two-element x0 must bracket a sign
    change (an error otherwise); from a scalar x0 it first searches outward
    for one (_fzero_search).  The zero itself is Brent's method
    (_fzero_brent), which the page cites.  The options are Display,
    FunValCheck, OutputFcn and TolX (default eps, or eps('single') when x0
    or fun(x0) is single, when the arithmetic is single too).

    Sagebrush's own choices, where the page fixes nothing: a NaN or
    complex value inside the bracket is an error rather than a guess;
    exitflag -5 is never given, since the page says what it means (a
    possible singular point) but not how it is detected, so a sign change
    at a pole ends like any other, x the sign change's place and fval its
    large value; output functions see
    the search's steps as iterations too; the messages other than 'Zero
    found in the interval [a, b]' are Sagebrush's own; and PlotFcns is
    refused"""
    if len(args) == 1 and type(args[0]) is _m.Struct:
        p = args[0]
        if _m._numel(p) != 1:
            raise _err("fzero: the problem must be a scalar structure.")
        d = p.a[0]
        for k in ("objective", "x0", "solver"):
            if k not in d:
                raise _err("fzero: the problem structure needs the field '%s'." % k)
        if not _istext(d["solver"]) or _text(d["solver"]) != "fzero":
            raise _err("fzero: the problem structure's solver must be 'fzero'.")
        fun, x0, options = d["objective"], d["x0"], d.get("options")
    elif len(args) in (2, 3):
        fun, x0 = args[0], args[1]
        options = args[2] if len(args) == 3 else None
    elif len(args) < 2:
        raise _err("Not enough input arguments.")
    else:
        raise _err("Too many input arguments.")
    if nargout > 4:
        raise _err("Too many output arguments.")
    options = _options_arg(options, "fzero")
    f = _m._fn_arg(fun)
    disp = _display(options, "fzero")
    outs = _output_fcns(options, "fzero")
    check = _opt(options, "FunValCheck", "fzero") == "on"
    if type(x0) is _m.Char or not _m._isnumlike(x0) or _m._numel(x0) not in (1, 2):
        raise _err("fzero: x0 must be a real scalar or a two-element real vector.")
    if _m.class_(x0) not in ("double", "single"):
        # (the page's x0 is single or double)
        raise _err("fzero: x0 must be of class double or single.")
    xa = _m._arr(x0).T.reshape(-1)
    if np.iscomplexobj(xa) and np.any(xa.imag != 0):
        raise _err("fzero: x0 must be real.")
    xs = [float(v.real) if np.iscomplexobj(xa) else float(v) for v in xa]
    F = _ZeroFun(f, _m.class_(x0) == "single", check)
    if F.single:
        xs = [_single_round(v) for v in xs]
    tolx = _opt(options, "TolX")
    show = disp == "iter"
    intervals, iters, flag, x, fx = 0, 0, None, None, None
    if len(xs) == 2:
        if not all(_math.isfinite(v) for v in xs):
            raise _err("fzero: the interval x0 must be finite.")
        a, b = xs
        fa = F(a)
        fb = F(b)
        for v, fv in ((a, fa), (b, fb)):
            if type(fv) is complex or not _math.isfinite(fv):
                raise _err("fzero: the function value at the interval end x = %g must be real and finite." % v)
        if not _changes_sign(fa, fb):
            raise _err("fzero: the function values at the interval endpoints must differ in sign.")
        if show:
            _m._write(" Func-count    x          f(x)             Procedure\n")
    else:
        if not _math.isfinite(xs[0]):
            raise _err("fzero: x0 must be finite.")
        a, fa, b, fb, intervals, flag, x, fx = _fzero_search(F, xs[0], show, outs)
        if flag is None and show:
            _m._write("\nSearch for a zero in the interval [%g, %g]:\n" % (a, b))
            _m._write(" Func-count    x          f(x)             Procedure\n")
    if tolx is None:
        tolx = 1.1920928955078125e-07 if F.single else _EPS
    a0, b0, fa0, fb0 = a, b, fa, fb
    if flag is None:
        if len(xs) == 2 and outs:
            best = (b, fb) if abs(fb) <= abs(fa) else (a, fa)
            vals = {"funccount": float(F.count), "fval": best[1], "iteration": 0.0, "procedure": _m.Char("initial")}
            if _call_output(outs, best[0], vals, "init"):
                flag, x, fx = -1, best[0], best[1]
        if flag is None:
            x, fx, iters, stopped = _fzero_brent(F, a, fa, b, fb, float(_m._scalar(tolx)), show, outs, intervals)
            flag = -1 if stopped else 1
    if flag == 1:
        msg = "Zero found in the interval [%g, %g]" % (a0, b0)
    elif flag == -1:
        msg = "fzero stopped: an output function asked it to stop."
    elif flag == -6:
        msg = "fzero found no sign change: the search interval around %g grew as far as [%g, %g]." % (xs[0], a0, b0)
    else:
        msg = ("fzero stopped searching for an interval containing a sign change: the function value at x = %g is %s."
               % (x, "complex" if flag == -4 else _m._special(fx)))
    if flag in (-3, -4, -6):
        x = fx = _math.nan
    if outs:
        vals = {"funccount": float(F.count), "fval": fx if type(fx) is not complex else _math.nan,
                "iteration": float(intervals + iters), "procedure": _m.Char("")}
        _call_output(outs, x, vals, "done")
    if disp == "iter" or disp == "final" or (disp == "notify" and flag != 1):
        _m._write(("\n" if show else "") + msg + "\n")

    def num(v):
        return _m._canon(np.array([[v]], dtype=np.float32)) if F.single else float(v)
    out = [num(x), num(fx), num(float(flag)),
           _m._struct1({"intervaliterations": float(intervals), "iterations": float(iters), "funcCount": float(F.count),
                        "algorithm": _m.Char("bisection, interpolation"), "message": _m.Char(msg)})]
    return out[0] if nargout <= 1 else out[:nargout]


# ------------------------------------------------------------------ fminbnd

def _problem(args, solver, fields, nargs):
    """the arguments of solver(fun, ..., options) or solver(problem), the
    problem structure holding the given fields and solver"""
    if len(args) == 1 and type(args[0]) is _m.Struct:
        p = args[0]
        if _m._numel(p) != 1:
            raise _err("%s: the problem must be a scalar structure." % solver)
        d = p.a[0]
        for k in fields + ["solver"]:
            if k not in d:
                raise _err("%s: the problem structure needs the field '%s'." % (solver, k))
        if not _istext(d["solver"]) or _text(d["solver"]) != solver:
            raise _err("%s: the problem structure's solver must be '%s'." % (solver, solver))
        return [d[k] for k in fields] + [d.get("options")]
    if len(args) < nargs:
        raise _err("Not enough input arguments.")
    if len(args) > nargs + 1:
        raise _err("Too many input arguments.")
    return list(args) + [None] * (nargs + 1 - len(args))


def _real_value(f, x, solver, check):
    """fun(x) for a minimizer: a real scalar (NaN allowed unless
    FunValCheck is on; a complex value is always an error)"""
    r = _m._call(f, [x])
    if not _m._isnumlike(r) or type(r) is _m.Char or _m._numel(r) != 1:
        raise _err("%s: the objective function must return a numeric scalar." % solver)
    a = _m._arr(r).reshape(-1)[0]
    if np.iscomplexobj(a):
        if a.imag != 0:
            raise _err("%s: the objective function returned a complex value; only real values can be minimized." % solver)
        a = a.real
    v = float(a)
    if check and v != v:
        raise _err("%s: the objective function returned NaN (FunValCheck is on)." % solver)
    return v


def _positive_count(options, name, solver):
    v = _opt(options, name, solver)
    v = float(_m._scalar(v)) if not isinstance(v, float) else v
    return v


@_bi("fminbnd")
def fminbnd_(nargout, *args):
    """fminbnd as its documentation page describes it: fminbnd(fun, x1, x2),
    fminbnd(fun, x1, x2, options) and fminbnd(problem), with outputs
    [x, fval, exitflag, output].  The method is the one the page cites:
    Brent's localmin (R. P. Brent, Algorithms for Minimization without
    Derivatives, 1973, chapter 5; the Fortran fmin of Forsythe, Malcolm and
    Moler, Computer Methods for Mathematical Computations, 1976, section
    8.2), golden section search with parabolic interpolation, which never
    evaluates fun at the ends of the interval.  Its tolerance is
    sqrt(eps)*|x| + TolX/3, the one whose bound
    2*(TolX + 3*abs(x)*sqrt(eps)) the page gives.  The options are Display,
    FunValCheck, MaxFunEvals and MaxIter (500 each), OutputFcn and TolX
    (1e-4).  As the published displays show, the first evaluation is not
    an iteration.

    Sagebrush's own choices, where the page fixes nothing: x1 > x2 returns
    NaN with exitflag -2 without evaluating fun; a complex value is an
    error even with FunValCheck off; the limits are checked after the
    convergence test, before each new evaluation; output functions are
    called after each evaluation (the first with state 'init', then
    'iter'); the
    messages other than the converged one are Sagebrush's own; and
    PlotFcns is refused"""
    fun, x1, x2, options = _problem(args, "fminbnd", ["objective", "x1", "x2"], 3)
    if nargout > 4:
        raise _err("Too many output arguments.")
    options = _options_arg(options, "fminbnd")
    f = _m._fn_arg(fun)
    disp = _display(options, "fminbnd")
    outs = _output_fcns(options, "fminbnd")
    check = _opt(options, "FunValCheck", "fminbnd") == "on"
    ends = []
    for v in (x1, x2):
        if type(v) is _m.Char or not _m._isnumlike(v) or _m._numel(v) != 1 or _m.class_(v) != "double":
            raise _err("fminbnd: the bounds x1 and x2 must be double scalars.")
        a = _m._arr(v).reshape(-1)[0]
        if np.iscomplexobj(a) and a.imag != 0:
            raise _err("fminbnd: the bounds x1 and x2 must be real.")
        e = float(a.real)
        if not _math.isfinite(e):
            raise _err("fminbnd: the bounds x1 and x2 must be finite.")
        ends.append(e)
    a, b = ends
    tolx = float(_m._scalar(_opt(options, "TolX", "fminbnd")))
    maxfun = _positive_count(options, "MaxFunEvals", "fminbnd")
    maxit = _positive_count(options, "MaxIter", "fminbnd")
    show = disp == "iter"
    count, it = 0, 0
    algorithm = "golden section search, parabolic interpolation"

    def result(x, fx, flag, msg):
        if outs and flag != -2:
            _call_output(outs, x, {"funccount": float(count), "fval": fx, "iteration": float(it),
                                   "procedure": _m.Char("")}, "done")
        if disp == "iter" or disp == "final" or (disp == "notify" and flag != 1):
            _m._write(("\n" if show else "") + msg + "\n")
        out = [x, fx, float(flag), _m._struct1({"iterations": float(it), "funcCount": float(count),
                                               "algorithm": _m.Char(algorithm), "message": _m.Char(msg)})]
        return out[0] if nargout <= 1 else out[:nargout]

    if a > b:
        return result(_math.nan, _math.nan, -2, "fminbnd stopped: the bounds are inconsistent (x1 > x2).")
    if show:
        _m._write(" Func-count     x          f(x)         Procedure\n")

    def row(x, fx, proc):
        if show:
            _m._write("%5.0f%15.6g%13.6g        %s\n" % (count, x, fx, proc))

    c = 0.5 * (3.0 - _math.sqrt(5.0))
    seps = _math.sqrt(_EPS)
    v = w = x = a + c * (b - a)
    d = e = 0.0
    fx = _real_value(f, x, "fminbnd", check)
    count = 1
    fv = fw = fx
    row(x, fx, "initial")
    if outs and _call_output(outs, x, {"funccount": 1.0, "fval": fx, "iteration": 0.0,
                                       "procedure": _m.Char("initial")}, "init"):
        return result(x, fx, -1, "fminbnd stopped: an output function asked it to stop.")
    while True:
        xm = 0.5 * (a + b)
        tol1 = seps * abs(x) + tolx / 3.0
        tol2 = 2.0 * tol1
        if abs(x - xm) <= tol2 - 0.5 * (b - a):
            return result(x, fx, 1, "Optimization terminated:\n the current x satisfies the termination criteria "
                                    "using OPTIONS.TolX of %e " % tolx)
        if count >= maxfun or it >= maxit:
            which = "MaxFunEvals" if count >= maxfun else "MaxIter"
            return result(x, fx, 0, "fminbnd stopped: it reached the %s limit of %d before meeting TolX."
                          % (which, maxfun if which == "MaxFunEvals" else maxit))
        golden = True
        if abs(e) > tol1:
            r = (x - w) * (fx - fv)
            q = (x - v) * (fx - fw)
            p = (x - v) * q - (x - w) * r
            q = 2.0 * (q - r)
            if q > 0.0:
                p = -p
            q = abs(q)
            r, e = e, d
            if abs(p) < abs(0.5 * q * r) and p > q * (a - x) and p < q * (b - x):
                d = p / q
                u = x + d
                if u - a < tol2 or b - u < tol2:
                    d = tol1 if xm >= x else -tol1
                golden = False
        if golden:
            e = (b - x) if x < xm else (a - x)
            d = c * e
        u = x + (d if abs(d) >= tol1 else (tol1 if d > 0 else -tol1))
        fu = _real_value(f, u, "fminbnd", check)
        count += 1
        it += 1
        row(u, fu, "golden" if golden else "parabolic")
        if fu <= fx:
            if u >= x:
                a = x
            else:
                b = x
            v, fv, w, fw, x, fx = w, fw, x, fx, u, fu
        else:
            if u < x:
                a = u
            else:
                b = u
            if fu <= fw or w == x:
                v, fv, w, fw = w, fw, u, fu
            elif fu <= fv or v == x or v == w:
                v, fv = u, fu
        if outs and _call_output(outs, x, {"funccount": float(count), "fval": fx, "iteration": float(it),
                                           "procedure": _m.Char("golden" if golden else "parabolic")}, "iter"):
            return result(x, fx, -1, "fminbnd stopped: an output function asked it to stop.")


# ------------------------------------------------------------------ fminsearch

@_bi("fminsearch")
def fminsearch_(nargout, *args):
    """fminsearch as its documentation page describes it:
    fminsearch(fun, x0), fminsearch(fun, x0, options) and
    fminsearch(problem), with outputs [x, fval, exitflag, output]; fun gets
    x in x0's shape.  The method is the Nelder-Mead simplex search of
    Lagarias, Reeds, Wright and Wright (SIAM J. Optim. 9, 1998, section 2,
    with its standard coefficients 1, 2, 1/2 and 1/2), in the form MATLAB's
    "fminsearch Algorithm" page spells out step by step: the initial
    simplex adds 5% to each component of x0 in turn (0.00025 for a zero
    one); each iteration reflects the worst point through the centroid m of
    the others, then expands, accepts the reflection, contracts outside or
    inside, or shrinks toward the best point, with that page's tests.  The
    points are kept sorted by value, a new point after any it ties with
    (Lagarias et al.'s rule).  As the published display shows, building the
    initial simplex is iteration 1.

    It stops when both tolerances hold, as the page says it must; the
    measures are Sagebrush's own: every vertex within TolX of the best in
    each component, and every value within TolFun of the best value.  The
    other options are Display, FunValCheck, MaxFunEvals and MaxIter (each
    200 times the number of variables by default) and OutputFcn; PlotFcns
    is refused.  Also Sagebrush's own: a complex value is an error even with
    FunValCheck off; output functions are called after each iteration
    (x0, iteration 0, with state 'init' and then 'iter'); and the messages
    other than the converged one"""
    fun, x0, options = _problem(args, "fminsearch", ["objective", "x0"], 2)
    if nargout > 4:
        raise _err("Too many output arguments.")
    options = _options_arg(options, "fminsearch")
    f = _m._fn_arg(fun)
    disp = _display(options, "fminsearch")
    outs = _output_fcns(options, "fminsearch")
    check = _opt(options, "FunValCheck", "fminsearch") == "on"
    if type(x0) is _m.Char or not _m._isnumlike(x0) or _m.class_(x0) != "double" or _m._numel(x0) == 0:
        raise _err("fminsearch: x0 must be a nonempty double array.")
    a0 = _m._arr(x0)
    if np.iscomplexobj(a0):
        if np.any(a0.imag != 0):
            raise _err("fminsearch: x0 must be real.")
        a0 = a0.real
    shape = a0.shape
    start = np.array(a0, dtype=float).reshape(-1)  # (x0(:): the storage is transposed, so C order is MATLAB's)
    n = start.size
    tolx = float(_m._scalar(_opt(options, "TolX", "fminsearch")))
    tolf = float(_m._scalar(_opt(options, "TolFun", "fminsearch")))
    mf, mi = _opt(options, "MaxFunEvals"), _opt(options, "MaxIter")
    maxfun = 200.0 * n if mf is None else float(_m._scalar(mf))
    maxit = 200.0 * n if mi is None else float(_m._scalar(mi))
    show = disp == "iter"
    algorithm = "Nelder-Mead simplex direct search"

    def shaped(v):
        return _m._box(np.array(v, dtype=float).reshape(shape))

    count = [0]

    def value(v):
        count[0] += 1
        return _real_value(f, shaped(v), "fminsearch", check)

    def row(it, fbest, proc):
        if show:
            _m._write("%6.0f%13.0f%17.6g         %s\n" % (it, count[0], fbest, proc))

    def output(state, it, x, fx, proc):
        return outs and _call_output(outs, shaped(x), {"funccount": float(count[0]), "fval": fx,
                                                         "iteration": float(it), "procedure": _m.Char(proc)}, state)

    def result(x, fx, it, flag, msg):
        if outs:
            output("done", it, x, fx, "")
        if disp == "iter" or disp == "final" or (disp == "notify" and flag != 1):
            _m._write(("\n" if show else "") + msg + "\n")
        out = [shaped(x), fx, float(flag), _m._struct1({"iterations": float(it), "funcCount": float(count[0]),
                                                        "algorithm": _m.Char(algorithm), "message": _m.Char(msg)})]
        return out[0] if nargout <= 1 else out[:nargout]

    stopped = "fminsearch stopped: an output function asked it to stop."
    if show:
        _m._write(" Iteration   Func-count         f(x)         Procedure\n")
    pts = [start.copy()]
    vals = [value(start)]
    row(0, vals[0], "")
    if output("init", 0, pts[0], vals[0], ""):
        return result(pts[0], vals[0], 0, -1, stopped)
    for i in range(n):
        y = start.copy()
        y[i] = 1.05 * y[i] if y[i] != 0 else 0.00025
        pts.append(y)
        vals.append(value(y))

    def order():
        idx = sorted(range(n + 1), key=lambda k: vals[k])
        pts[:] = [pts[k] for k in idx]
        vals[:] = [vals[k] for k in idx]

    order()
    it = 1
    row(it, vals[0], "initial simplex")
    if output("iter", it, pts[0], vals[0], "initial simplex"):
        return result(pts[0], vals[0], it, -1, stopped)
    while True:
        best = pts[0]
        if (max(float(np.max(np.abs(p - best))) for p in pts[1:]) <= tolx
                and max(abs(v - vals[0]) for v in vals[1:]) <= tolf):
            return result(best, vals[0], it, 1,
                          "Optimization terminated:\n the current x satisfies the termination criteria using OPTIONS.TolX of %e \n"
                          " and F(X) satisfies the convergence criteria using OPTIONS.TolFun of %e " % (tolx, tolf))
        if count[0] >= maxfun or it >= maxit:
            which, lim = ("MaxFunEvals", maxfun) if count[0] >= maxfun else ("MaxIter", maxit)
            return result(best, vals[0], it, 0,
                          "fminsearch stopped: it reached the %s limit of %d before meeting TolX and TolFun." % (which, lim))
        it += 1
        worst, fworst = pts[n], vals[n]
        m = np.sum(np.array(pts[:n]), axis=0) / n
        r = 2 * m - worst
        fr = value(r)
        if vals[0] <= fr < vals[n - 1]:
            new, fnew, proc = r, fr, "reflect"
        elif fr < vals[0]:
            s = m + 2 * (m - worst)
            fs = value(s)
            new, fnew, proc = (s, fs, "expand") if fs < fr else (r, fr, "reflect")
        else:
            new = None
            if fr < fworst:
                c = m + (r - m) / 2
                fc = value(c)
                if fc < fr:
                    new, fnew, proc = c, fc, "contract outside"
            else:
                cc = m + (worst - m) / 2
                fcc = value(cc)
                if fcc < fworst:
                    new, fnew, proc = cc, fcc, "contract inside"
            if new is None:
                proc = "shrink"
                for i in range(1, n + 1):
                    pts[i] = pts[0] + (pts[i] - pts[0]) / 2
                    vals[i] = value(pts[i])
        if new is not None:
            pts[n], vals[n] = new, fnew
        order()
        row(it, vals[0], proc)
        if output("iter", it, pts[0], vals[0], proc):
            return result(pts[0], vals[0], it, -1, stopped)


# ------------------------------------------------------------------ lsqnonneg

def _real_matrix(v, what):
    if type(v) is _m.Sparse:
        v = _m._B["full"].f(1, v)
    if type(v) is _m.Char or not _m._isnumlike(v) or _m.class_(v) != "double":
        raise _err("lsqnonneg: %s must be a real double matrix." % what)
    a = _m._mat(v)
    if a.dtype.kind == "c":
        if np.any(a.imag != 0):
            raise _err("lsqnonneg: %s must be real." % what)
        a = a.real
    return np.array(a, dtype=float)


@_bi("lsqnonneg")
def lsqnonneg_(nargout, *args):
    """lsqnonneg as its documentation page describes it: lsqnonneg(C, d),
    lsqnonneg(C, d, options) and lsqnonneg(problem), with outputs
    [x, resnorm, residual, exitflag, output, lambda]: the x >= 0 that
    minimizes norm(C*x - d), with resnorm = norm(d - C*x)^2, the residual
    d - C*x and the dual vector lambda = C'*(d - C*x).  The method is the
    one the page cites, Lawson and Hanson's NNLS active-set algorithm
    (Solving Least Squares Problems, Prentice-Hall 1974, chapter 23): move
    the variable of largest positive lambda into the passive set, solve
    the least-squares problem on that set (here by mldivide's QR), and
    while the solution has a nonpositive entry, step back toward the
    previous x as far as keeps it nonnegative and free the variables that
    reach 0.  It stops when no free variable has lambda above TolX
    (default 10*eps*norm(C,1)*length(C), as the page gives it).  The
    options are Display ('notify', 'final', 'off' or 'none') and TolX.

    TolX is the threshold for entering (lambda above it); a passive
    solution's entries are tested for positivity exactly, and the variable
    that limits the step back reaches 0 exactly, as in Lawson and Hanson's
    steps 6 to 11, so that a solution of any scale is kept (TolX, which
    scales with C, is a dual tolerance, not a size for x).

    Sagebrush's own choices, where the page fixes nothing: the limit behind exitflag 0 is MaxIter if set and
    otherwise Lawson and Hanson's 3 times the number of variables;
    iterations counts the least-squares solves; a sparse C is used as a
    full matrix; and the message for exitflag 0 is Sagebrush's own"""
    C, d, options = _problem(args, "lsqnonneg", ["C", "d"], 2)
    if nargout > 6:
        raise _err("Too many output arguments.")
    options = _options_arg(options, "lsqnonneg")
    disp = _display(options, "lsqnonneg")
    if disp == "iter":
        raise _err("lsqnonneg: Display 'iter' is not supported; use 'notify', 'final', 'off' or 'none'.")
    A = _real_matrix(C, "C")
    if type(d) is not _m.Sparse and _m._isnumlike(d) and _m._numel(d) and min(_m._arr(d).shape) != 1:
        raise _err("lsqnonneg: d must be a vector.")
    b = _real_matrix(d, "d").T.reshape((-1, 1))
    m, n = A.shape
    if b.shape[0] != m:
        raise _err("lsqnonneg: the length of d must equal the number of rows of C.")
    if not (np.all(np.isfinite(A)) and np.all(np.isfinite(b))):
        raise _err("lsqnonneg: C and d must be finite.")
    tol = _opt(options, "TolX")
    tol = 10 * _EPS * (float(np.max(np.sum(np.abs(A), axis=0))) if A.size else 0.0) * max(m, n) if tol is None \
        else float(_m._scalar(tol))
    mi = _opt(options, "MaxIter")
    maxit = 3.0 * n if mi is None else float(_m._scalar(mi))
    x = np.zeros((n, 1))
    passive = np.zeros(n, dtype=bool)
    it = 0
    flag = 1

    def dual(x):
        return (A.T @ (b - A @ x)).reshape(-1)

    def solve(P):
        z = np.zeros((n, 1))
        if np.any(P):
            z[P] = _m._qr_solve(A[:, P], b)
        return z

    w = dual(x)
    while np.any(~passive) and np.max(np.where(passive, -np.inf, w)) > tol:
        if it >= maxit:
            flag = 0
            break
        t = int(np.argmax(np.where(passive, -np.inf, w)))
        passive[t] = True
        z = solve(passive)
        it += 1
        # (Lawson and Hanson's steps 6 to 11: the passive solution's entries
        # are tested for positivity exactly, whatever the scale of C; the
        # step back stops where the first of them reaches 0, which leaves
        # with every other passive variable at 0 or below)
        while np.any(z[passive] <= 0):
            if it >= maxit:
                flag = 0
                break
            neg = passive & (z.reshape(-1) <= 0)
            xs, zs = x.reshape(-1)[neg], z.reshape(-1)[neg]
            gap = xs - zs
            ratios = np.where(gap > 0, xs / np.where(gap > 0, gap, 1.0), 0.0)
            k = int(np.argmin(ratios))
            x = x + float(ratios[k]) * (z - x)
            x[np.flatnonzero(neg)[k]] = 0.0
            passive &= ~(x.reshape(-1) <= 0)
            x[~passive] = 0.0
            z = solve(passive)
            it += 1
        if flag == 0:
            break
        x = z
        w = dual(x)
    residual = b - A @ x
    lam = dual(x).reshape((-1, 1))
    if flag == 1:
        msg = "Optimization terminated."
    else:
        msg = "lsqnonneg stopped: it reached the iteration limit of %d before finishing." % maxit
    if disp == "final" or (disp == "notify" and flag != 1):
        _m._write(msg + "\n")
    out = [_m._unmat(x), float(np.sum(residual ** 2)), _m._unmat(residual), float(flag),
           _m._struct1({"iterations": float(it), "algorithm": _m.Char("active-set"), "message": _m.Char(msg)}),
           _m._unmat(lam)]
    return out[0] if nargout <= 1 else out[:max(nargout, 1)]


# ------------------------------------------------------------------ quad

# quad's evaluation limit: GNU Octave's for its adaptive Simpson quadrature,
# quadv, observed with Octave 11.1 (it stops at exactly 10001 evaluations,
# whatever the integrand, warning "maximum iteration count reached")
_QUAD_MAX_EVALS = 10001


@_bi("quad")
def quad_(nargout, fun, *args):
    """quad as its documentation page describes it: quad(fun, a, b),
    quad(fun, a, b, tol), quad(fun, a, b, tol, trace) and
    [q, fcnEvals] = quad(...), recursive adaptive Simpson quadrature of a
    vectorized fun over finite a and b, with tol an absolute error
    tolerance on each subinterval (default 1e-6).  Each step is the one of
    Gander and Gautschi, "Adaptive quadrature -- revisited" (BIT 40, 2000),
    section 3, the reference the page gives: on [a, b], with f at a, the
    midpoint m and b already known, f at the two quarter points (two new
    values), Simpson's rule i1 on [a, b] and the composite one i2 on its
    halves, and i1 replaced by one Romberg step (16*i2 - i1)/15.  A
    subinterval is accepted, with that value, when |i1 - i2| <= tol (the
    page's absolute tolerance, in place of the paper's relative test), or
    when, as in the paper's criterion (2.7), it holds no machine number
    between its ends and m (with a warning that tol may not be met);
    otherwise its halves are integrated in turn.  There is no limit on the
    recursion depth, as the paper argues.

    At most 10001 evaluations, the limit of GNU Octave's adaptive Simpson
    quadrature (quadv: observed, it stops at exactly 10001 whatever the
    integrand): a subinterval whose step or halves would go beyond it is
    accepted with the value it has, with a warning that the tolerance may
    not be met; the count never goes beyond it.

    Sagebrush's own choices, where the page fixes nothing: a subinterval
    with an Inf or NaN value is not subdivided further, and the warning
    says the integrand is not finite; the
    trace's number format; and single precision: a single a, b or value
    gives a single result, computed in double"""
    if len(args) < 2:
        raise _err("Not enough input arguments.")
    if len(args) > 4:
        raise _err("Too many input arguments.")
    f = _m._fn_arg(fun)
    single = False
    ends = []
    for v in args[:2]:
        if type(v) is _m.Char or not _m._isnumlike(v) or _m._numel(v) != 1 or _m.class_(v) not in ("double", "single"):
            raise _err("quad: the limits a and b must be double or single scalars.")
        single = single or _m.class_(v) == "single"
        e = _m._arr(v).reshape(-1)[0]
        if np.iscomplexobj(e) and e.imag != 0:
            raise _err("quad: the limits a and b must be real.")
        e = float(e.real)
        if not _math.isfinite(e):
            raise _err("quad: the limits a and b must be finite.")
        ends.append(e)
    tol = 1e-6
    if len(args) > 2 and not _is_empty(args[2]):
        t = args[2]
        if type(t) is _m.Char or not _m._isnumlike(t) or _m._numel(t) != 1 or np.iscomplexobj(_m._arr(t)) \
                or not _m._scalar(t) >= 0:
            raise _err("quad: tol must be a nonnegative scalar.")
        tol = float(_m._scalar(t))
    trace = len(args) > 3 and not _is_empty(args[3]) and bool(_m._logical_val(args[3]))
    count = [0]
    cplx = [False]

    def values(xs):
        r = _m._call(f, [_m._box(np.array(xs, dtype=float).reshape((-1, 1)))])
        if not _m._isnumlike(r) or type(r) is _m.Char or _m._numel(r) != len(xs):
            raise _err("quad: the integrand must return a vector of the same length as its input "
                       "(use array operators such as .* and ./).")
        nonlocal single
        single = single or _m.class_(r) == "single"
        y = np.array(_m._arr(r)).reshape(-1)
        count[0] += len(xs)
        if np.iscomplexobj(y) and np.any(y.imag != 0):
            cplx[0] = True
            return [complex(v) for v in y]
        return [float(v.real) if np.iscomplexobj(y) else float(v) for v in y]

    a, b = ends
    fa, fm, fb = values([a, (a + b) / 2, b])
    warned = set()

    def warn(key, msg):
        if key not in warned:
            warned.add(key)
            _m.warning_(msg)

    # (the recursion as an explicit stack of intervals, each "new", or
    # waiting for its left or its right half; the halves' values are added
    # as the recursion would add them)
    stack = [{"lo": a, "hi": b, "f": (fa, fm, fb), "state": "new"}]
    result = None
    while stack:
        fr = stack[-1]
        lo, hi = fr["lo"], fr["hi"]
        flo, fmid, fhi = fr["f"]
        m = (lo + hi) / 2
        h = (hi - lo) / 4
        if count[0] + 2 > _QUAD_MAX_EVALS:
            # (no evaluations left for this interval's step: its Simpson
            # value from the three it has)
            i1 = h / 1.5 * (flo + 4 * fmid + fhi)
            finite = all(_math.isfinite(abs(v)) for v in (flo, fmid, fhi))
            met = tiny = False
            full = True
        else:
            fml, fmr = values([lo + h, hi - h])
            i1 = h / 1.5 * (flo + 4 * fmid + fhi)
            i2 = h / 3 * (flo + 4 * (fml + fmr) + 2 * fmid + fhi)
            i1 = (16 * i2 - i1) / 15
            finite = all(_math.isfinite(abs(v)) for v in (flo, fmid, fhi, fml, fmr))
            met = abs(i1 - i2) <= tol
            tiny = m <= min(lo, hi) or max(lo, hi) <= m
            # (no evaluations left for its halves' steps: this value)
            full = count[0] + 2 > _QUAD_MAX_EVALS
        if not (met or tiny or not finite or full):
            fr["state"] = "left"
            fr["mid"] = (fml, fmr)
            stack.append({"lo": lo, "hi": m, "f": (flo, fml, fmid), "state": "new"})
            continue
        if not finite:
            warn("finite", "quad: the integrand is Inf or NaN in the interval, so the result is not finite.")
        elif tiny and not met:
            warn("tiny", "quad: a subinterval holds no more machine numbers; the tolerance may not be met.")
        elif not met:
            warn("count", "quad: the limit of %d function evaluations was reached; the tolerance may not be met." % _QUAD_MAX_EVALS)
        if trace:
            _m._write("%10d %21.14g %21.14g %21.14g\n" % (count[0], lo, hi - lo, i1.real))
        q = i1
        stack.pop()
        # (deliver q to the waiting parents)
        while stack:
            parent = stack[-1]
            if parent["state"] == "left":
                parent["left"] = q
                parent["state"] = "right"
                pm = (parent["lo"] + parent["hi"]) / 2
                pf = parent["f"]
                stack.append({"lo": pm, "hi": parent["hi"], "f": (pf[1], parent["mid"][1], pf[2]), "state": "new"})
                break
            q = parent["left"] + q
            stack.pop()
        else:
            result = q
    q = result
    out = _m._canon(np.array([[q]], dtype=np.complex64 if cplx[0] else np.float32)) if single else q
    return out if nargout <= 1 else [out, float(count[0])][:nargout]


# ------------------------------------------------------------------ integral, quadgk

# (the Gauss-Kronrod (7, 15) pair on [-1, 1] that Shampine's paper uses,
# computed for Sagebrush from its definition: the 7 Gauss-Legendre nodes,
# the 8 Kronrod nodes as the zeros of the Stieltjes polynomial of degree 8
# for the weight P7, and the weights from exactness for polynomials of
# degree 22, all in 60-digit arithmetic, then rounded)
_GK_NODES = np.array([-0.9914553711208126, -0.9491079123427585, -0.8648644233597691, -0.7415311855993945,
                      -0.5860872354676911, -0.4058451513773972, -0.20778495500789848, 0.0, 0.20778495500789848,
                      0.4058451513773972, 0.5860872354676911, 0.7415311855993945, 0.8648644233597691,
                      0.9491079123427585, 0.9914553711208126])
_GK_KRONROD = np.array([0.022935322010529224, 0.06309209262997856, 0.10479001032225019, 0.14065325971552592,
                        0.1690047266392679, 0.19035057806478542, 0.20443294007529889, 0.20948214108472782,
                        0.20443294007529889, 0.19035057806478542, 0.1690047266392679, 0.14065325971552592,
                        0.10479001032225019, 0.06309209262997856, 0.022935322010529224])
_GK_GAUSS = np.zeros(15)
_GK_GAUSS[1::2] = [0.1294849661688697, 0.27970539148927664, 0.3818300505051189, 0.4179591836734694,
                   0.3818300505051189, 0.27970539148927664, 0.1294849661688697]


def _gk_core(F, breaks, xmap, atol, rtol, maxint, solver, nocount_warning, warn=None):
    """Shampine's vectorized global adaptive quadrature (L. F. Shampine,
    "Vectorized adaptive quadrature in MATLAB", J. Comput. Appl. Math. 211,
    2008, sections 3 to 6) of F over [breaks[0], breaks[-1]] in the
    transformed variable t: F(t) gives the integrand's values (times dt's
    factor) at a 1-D array of t, as an array of len(t) rows.  All active
    subintervals are sampled at once, 15 points each; each one's integral
    is the Kronrod value and its error estimate the difference from the
    Gauss value.  With tol = max(atol, rtol*|Q|), the computation ends when
    the summed estimates are at most tol; otherwise the subintervals whose
    estimates are at most tol times their share of the interval's length
    are accepted, and the rest bisected (section 3).  For an array-valued
    integrand all of this is component by component (each component's
    estimates against its own tol), as integral's page states its error
    test, abs(q - Q) <= max(AbsoluteTolerance, RelativeTolerance*abs(q)),
    for each element; the bound returned is the largest component's.  It stops, with a
    warning, when bisecting would make more than maxint subintervals
    (section 3), when a subinterval's ends in x are within 100*eps of each
    other relatively (section 6), or when a value is Inf or NaN after the
    first evaluation (an error on the first, section 6).  Returns (Q, E)"""
    warn = warn or _m.warning_
    A, B = breaks[0], breaks[-1]
    subs = list(zip(breaks[:-1], breaks[1:]))
    if len(subs) < 10:
        # (at least 10 subintervals at the start, section 5: each break
        # interval cut into equal pieces, which gives the paper's 150
        # samples for one interval)
        k = -(-10 // len(subs))
        subs = [(lo + (hi - lo) * j / k, lo + (hi - lo) * (j + 1) / k) for lo, hi in subs for j in range(k)]
    QOK, EOK = 0.0, 0.0
    first = True
    Q = E = None
    while True:
        lo = np.array([s[0] for s in subs])
        hi = np.array([s[1] for s in subs])
        mid = (lo + hi) / 2
        hh = (hi - lo) / 2
        t = (mid[:, None] + hh[:, None] * _GK_NODES[None, :]).reshape(-1)
        y = F(t)
        if not np.all(np.isfinite(y)):
            if first:
                raise _err("%s: the integrand is Inf or NaN at the first points tried; no approximation of the integral "
                           "is possible." % solver)
            warn("%s: the integrand is Inf or NaN at some points; the last approximation is returned. "
                        "Approximate bound on error is %.1e." % (solver, E))
            return Q, E
        first = False
        y = y.reshape((len(subs), 15) + y.shape[1:])
        Qs = np.tensordot(y, _GK_KRONROD, axes=([1], [0])) * (hh if y.ndim == 2 else hh[:, None])
        Gs = np.tensordot(y, _GK_GAUSS, axes=([1], [0])) * (hh if y.ndim == 2 else hh[:, None])
        # (an array-valued integrand's error estimates are its components',
        # each held to its own tolerance, max(atol, rtol*|Q_k|), as the
        # page's abs(q - Q) <= max(AbsoluteTolerance, RelativeTolerance*abs(q))
        # says for each element: a large component does not hide a small one's)
        Es = np.abs(Qs - Gs)
        Q = QOK + np.sum(Qs, axis=0)
        Ec = EOK + np.sum(Es, axis=0)
        E = float(np.max(Ec))
        tol = np.maximum(atol, rtol * np.abs(Q))
        if np.all(Ec <= tol):
            return Q, E
        share = ((2 / (B - A)) * hh).reshape((-1,) + (1,) * (Es.ndim - 1))
        ok = np.all((Es <= share * tol).reshape((len(subs), -1)), axis=1)
        if np.any(ok):
            # (only when there are some: Sagebrush's numpy sums an empty array
            # along an axis to NaN)
            QOK = QOK + np.sum(Qs[ok], axis=0)
            EOK = EOK + np.sum(Es[ok], axis=0)
        subs = [s for s, k in zip(subs, ok) if not k]
        if not subs:
            return Q, E
        if 2 * len(subs) > maxint:
            if nocount_warning:
                warn("%s: Reached the limit on the maximum number of intervals in use. Approximate bound on error "
                            "is %.1e. The tolerances were not met." % (solver, E))
            else:
                warn("Reached the limit on the maximum number of intervals in use. Approximate bound on error "
                            "is %.1e." % E)
            return Q, E
        subs = [p for lo_, hi_ in subs for p in ((lo_, (lo_ + hi_) / 2), ((lo_ + hi_) / 2, hi_))]
        ends = np.array([s[0] for s in subs] + [subs[-1][1]])
        with np.errstate(divide="ignore", invalid="ignore"):
            xs = xmap(ends)
        # (an infinite end of the interval, x at t = 1, is not a short subinterval)
        fin = np.isfinite(xs[:-1]) & np.isfinite(xs[1:])
        dx = np.abs(np.diff(xs))[fin]
        scale = np.maximum(np.abs(xs[:-1]), np.abs(xs[1:]))[fin]
        if np.any(dx <= 100 * _EPS * scale):
            warn("%s: a subinterval became too short for the precision of the arithmetic. Approximate bound on "
                        "error is %.1e. The tolerances may not be met." % (solver, E))
            return Q, E


def _gk_path(a, b, ways):
    """the integration path from a to b through the waypoints, as
    (breaks in t, x(t), dx/dt(t), sign): the changes of variable of
    Shampine's section 4.2 for a real interval (finite: Davis and
    Rabinowitz's x = (b-a)/4 t (3 - t^2) + (b+a)/2 on [-1, 1]; [a, Inf):
    x = a + (t/(1-t))^2 on [0, 1); (-Inf, b] the same reflected), and for
    (-Inf, Inf) Sagebrush's own x = t/(1-t^2) on [-1, 1].  Waypoints become
    breaks by inverting the map (Newton's method from alpha/3 for the
    finite one, as section 5 says).  A complex path, Sagebrush's own way,
    is piecewise linear through the waypoints in a parameter s, one unit
    per segment, with the finite map applied to s"""
    pts = [a] + list(ways) + [b]
    if any(isinstance(p, complex) for p in pts):
        if not all(_math.isfinite(abs(p)) for p in pts):
            raise _err("Contour integration requires all limits and waypoints to be finite.")
        P = np.array(pts, dtype=complex)
        nseg = len(pts) - 1

        def lin(s):
            k = np.clip(np.floor(s).astype(int), 0, nseg - 1)
            return P[k] + (P[k + 1] - P[k]) * (s - k), P[k + 1] - P[k]
        X = lambda t: lin(0.25 * nseg * t * (3 - t * t) + 0.5 * nseg)[0]
        D = lambda t: lin(0.25 * nseg * t * (3 - t * t) + 0.5 * nseg)[1] * (0.75 * nseg * (1 - t * t))
        breaks = [-1.0] + [_cubic_inverse(4 * (j - 0.5 * nseg) / nseg) for j in range(1, nseg)] + [1.0]
        return breaks, X, D, 1.0
    a, b = float(a), float(b)
    sign = 1.0
    if a > b:
        a, b, sign = b, a, -1.0
        ways = list(reversed(ways))
    ways = sorted(float(w) for w in ways)
    if any(not (a < w < b) for w in ways):
        raise _err("Waypoints must lie strictly between the limits of integration.")
    if _math.isfinite(a) and _math.isfinite(b):
        X = lambda t: 0.25 * (b - a) * t * (3 - t * t) + 0.5 * (b + a)
        D = lambda t: 0.75 * (b - a) * (1 - t * t)
        breaks = [-1.0] + [_cubic_inverse(4 * (w - 0.5 * (b + a)) / (b - a)) for w in ways] + [1.0]
    elif _math.isfinite(a):
        X = lambda t: a + (t / (1 - t)) ** 2
        D = lambda t: 2 * t / (1 - t) ** 3
        breaks = [0.0] + [_math.sqrt(w - a) / (1 + _math.sqrt(w - a)) for w in ways] + [1.0]
    elif _math.isfinite(b):
        X = lambda t: b - (t / (1 - t)) ** 2
        D = lambda t: 2 * t / (1 - t) ** 3
        breaks = [0.0] + sorted(_math.sqrt(b - w) / (1 + _math.sqrt(b - w)) for w in ways) + [1.0]
    else:
        X = lambda t: t / (1 - t * t)
        D = lambda t: (1 + t * t) / (1 - t * t) ** 2
        breaks = [-1.0] + [2 * w / (1 + _math.sqrt(1 + 4 * w * w)) for w in ways] + [1.0]
    return breaks, X, D, sign


def _cubic_inverse(alpha):
    """the t in (-1, 1) with t^3 - 3t + alpha = 0, |alpha| < 2: Newton's
    method from alpha/3, which converges monotonically (Shampine, section 5)"""
    t = alpha / 3.0
    for _ in range(100):
        nt = t - (t ** 3 - 3 * t + alpha) / (3 * t * t - 3)
        if nt == t:
            break
        t = nt
    return t


def _scalar_limit(v, solver):
    if type(v) is _m.Char or not _m._isnumlike(v) or _m._numel(v) != 1 or _m.class_(v) not in ("double", "single"):
        raise _err("%s: the limits must be double or single scalars." % solver)
    e = _m._arr(v).reshape(-1)[0]
    if np.iscomplexobj(e) and e.imag != 0:
        return complex(e)
    e = float(e.real)
    if e != e:
        raise _err("%s: the limits must not be NaN." % solver)
    return e


def _integrate(nargout, solver, fun, a, b, opts):
    f = _m._fn_arg(fun)
    single = _m.class_(a) == "single" or _m.class_(b) == "single"
    A0, B0 = _scalar_limit(a, solver), _scalar_limit(b, solver)
    names = {"abstol": "AbsTol", "reltol": "RelTol", "waypoints": "Waypoints"}
    if solver == "integral":
        names.update({"absolutetolerance": "AbsTol", "relativetolerance": "RelTol", "arrayvalued": "ArrayValued",
                      "vectorized": "Vectorized"})
    else:
        names["maxintervalcount"] = "MaxIntervalCount"
    if len(opts) % 2:
        raise _err("%s: name-value arguments must come in pairs." % solver)
    o = {}
    for k in range(0, len(opts), 2):
        if not _istext(opts[k]) or _text(opts[k]).lower() not in names:
            raise _err("%s: unknown option%s." % (solver, " '%s'" % _text(opts[k]) if _istext(opts[k]) else ""))
        o[names[_text(opts[k]).lower()]] = opts[k + 1]

    def num(name, default):
        if name not in o:
            return default
        v = o[name]
        if type(v) is _m.Char or not _m._isnumlike(v) or _m._numel(v) != 1 or np.iscomplexobj(_m._arr(v)) \
                or not _m._scalar(v) >= 0:
            raise _err("%s: %s must be a nonnegative real scalar." % (solver, name))
        return float(_m._scalar(v))
    sgl = single and solver == "quadgk"
    atol = num("AbsTol", 1e-5 if sgl else 1e-10)
    rtol = num("RelTol", 1e-4 if sgl else 1e-6)
    if rtol > 0:
        rtol = max(rtol, 100 * (1.1920928955078125e-07 if single else _EPS))
    maxint = num("MaxIntervalCount", 650.0)
    arrayvalued = "ArrayValued" in o and bool(_m._logical_val(o["ArrayValued"]))
    vectorized = not ("Vectorized" in o and not bool(_m._logical_val(o["Vectorized"])))
    ways = []
    if "Waypoints" in o:
        w = o["Waypoints"]
        if type(w) is _m.Char or not _m._isnumlike(w):
            raise _err("%s: Waypoints must be a vector of numbers." % solver)
        wa = _m._arr(w).reshape(-1)
        ways = [complex(v) if np.iscomplexobj(wa) and v.imag != 0 else float(v.real) for v in wa]
        if any(isinstance(v, float) and not _math.isfinite(v) for v in ways):
            raise _err("%s: Waypoints must be finite." % solver)
    if A0 == B0 and not any(isinstance(v, complex) for v in ways):
        q, e = 0.0, 0.0
        shape = None
        if arrayvalued:
            r = _m._call(f, [A0 if not isinstance(A0, complex) else complex(A0)])
            shape = _m._arr(r).shape
            q = np.zeros(shape)
        return _finish_integral(nargout, q, e, single, shape)
    breaks, X, D, sign = _gk_path(A0, B0, ways)
    shape = [None]

    def F(t):
        x = X(t)
        if arrayvalued or not vectorized:
            vals = []
            for xv in x:
                r = _m._call(f, [complex(xv) if np.iscomplexobj(x) else float(xv)])
                if not _m._isnumlike(r) or type(r) is _m.Char:
                    raise _err("%s: the integrand must return numbers." % solver)
                ra = np.array(_m._arr(r))
                if shape[0] is None:
                    shape[0] = ra.shape
                    if not arrayvalued and _m._numel(r) != 1:
                        raise _err("%s: with Vectorized false, the integrand must return a scalar; set ArrayValued for "
                                   "array values." % solver)
                elif ra.shape != shape[0]:
                    raise _err("%s: the integrand's output must have the same size at every point." % solver)
                vals.append(ra.reshape(-1))
            y = np.array(vals)
            if not arrayvalued:
                y = y.reshape(-1)
        else:
            xin = _m._box(np.array(x).reshape((-1, 1)))
            r = _m._call(f, [xin])
            if not _m._isnumlike(r) or type(r) is _m.Char or _m._numel(r) != len(x):
                raise _err("%s: the integrand must return an array the size of its input; use array operators "
                           "(.*, ./, .^) or set ArrayValued." % solver)
            y = np.array(_m._arr(r)).reshape(-1)
        nonlocal single
        if (arrayvalued or not vectorized) is False and _m.class_(r) == "single":
            single = True
        d = D(t)
        return y * (d if y.ndim == 1 else d[:, None])
    Q, E = _gk_core(F, breaks, lambda t: X(np.asarray(t, dtype=float)), atol, rtol, maxint, solver, solver == "integral")
    Q = Q * sign
    return _finish_integral(nargout, Q, E, single, shape[0] if arrayvalued else None)


def _finish_integral(nargout, Q, E, single, shape):
    Q = np.asarray(Q)
    if shape is not None:
        Q = Q.reshape(shape)
        out = _m._canon(Q.astype(np.complex64 if Q.dtype.kind == "c" else np.float32)) if single else _m._box(np.array(Q))
    else:
        q = complex(Q) if Q.dtype.kind == "c" else float(Q)
        if isinstance(q, complex) and q.imag == 0:
            q = q.real
        out = _m._canon(np.array([[q]], dtype=np.complex64 if isinstance(q, complex) else np.float32)) if single else q
    return out if nargout <= 1 else [out, float(E)][:nargout]


@_bi("integral")
def integral_(nargout, fun=None, a=None, b=None, *opts):
    """integral as its documentation page describes it: integral(fun, xmin,
    xmax) and the name-value options AbsoluteTolerance (AbsTol, default
    1e-10), RelativeTolerance (RelTol, 1e-6), ArrayValued, Vectorized and
    Waypoints; infinite limits, and complex limits or waypoints for a
    straight-line contour.  The method is the one the page cites,
    Shampine's vectorized adaptive Gauss-Kronrod quadrature (_gk_core,
    _gk_path), with up to 650 subintervals.  Sagebrush's own choices: the
    map for (-Inf, Inf) and the parametrization of a complex path
    (_gk_path), the infinity norm for an array-valued integrand's error, a
    result for xmin > xmax as minus the integral from xmax to xmin, and the
    wording of the warnings"""
    if b is None:
        raise _err("Not enough input arguments.")
    if nargout > 1:
        raise _err("Too many output arguments.")
    return _integrate(nargout, "integral", fun, a, b, list(opts))


@_bi("quadgk")
def quadgk_(nargout, fun=None, a=None, b=None, *opts):
    """quadgk as its documentation page describes it: [q, errbnd] =
    quadgk(fun, a, b, Name, Value) with AbsTol (1e-10, or 1e-5 for
    single), RelTol (1e-6, or 1e-4), Waypoints and MaxIntervalCount (650);
    RelTol at least 100*eps of the class unless it is 0.  The same method
    as integral (Shampine 2008, the page's reference), whose own choices
    apply here too; the warning on reaching MaxIntervalCount begins as the
    page's published one"""
    if b is None:
        raise _err("Not enough input arguments.")
    if nargout > 2:
        raise _err("Too many output arguments.")
    return _integrate(nargout, "quadgk", fun, a, b, list(opts))


# ------------------------------------------------------------------ integral2, integral3

def _quad1(g, a, b, atol, rtol, solver, warn):
    """the integral of g (a function of a numpy array of points) from a to b
    by integral's method (_gk_path, _gk_core)"""
    if a == b:
        return 0.0
    breaks, X, D, sign = _gk_path(a, b, [])

    def F(t):
        return np.asarray(g(X(t)), dtype=float).reshape(-1) * D(t)
    Q, _ = _gk_core(F, breaks, lambda t: X(np.asarray(t, dtype=float)), atol, rtol, 650.0, solver, True, warn)
    return float(Q) * sign


def _multi(nargout, solver, fun, lims, opts):
    """integral2 and integral3 by the iterated method their pages describe:
    integral over x of the integral over y (of the integral over z), each
    by integral's method, the inner limits functions of the outer
    variables or numbers"""
    f = _m._fn_arg(fun)
    names = {"abstol": "AbsTol", "absolutetolerance": "AbsTol", "reltol": "RelTol", "relativetolerance": "RelTol",
             "method": "Method", "vectorized": "Vectorized", "waypoints": "Waypoints"}
    if len(opts) % 2:
        raise _err("%s: name-value arguments must come in pairs." % solver)
    o = {}
    for k in range(0, len(opts), 2):
        if not _istext(opts[k]) or _text(opts[k]).lower() not in names:
            raise _err("%s: unknown option%s." % (solver, " '%s'" % _text(opts[k]) if _istext(opts[k]) else ""))
        o[names[_text(opts[k]).lower()]] = opts[k + 1]

    def num(name, default):
        if name not in o:
            return default
        v = o[name]
        if type(v) is _m.Char or not _m._isnumlike(v) or _m._numel(v) != 1 or np.iscomplexobj(_m._arr(v)) \
                or not _m._scalar(v) >= 0:
            raise _err("%s: %s must be a nonnegative real scalar." % (solver, name))
        return float(_m._scalar(v))
    atol, rtol = num("AbsTol", 1e-10), num("RelTol", 1e-6)
    if rtol > 0:
        rtol = max(rtol, 100 * _EPS)
    if "Method" in o and not _istext(o["Method"]):
        raise _err("%s: Method must be \"auto\", \"tiled\" or \"iterated\"." % solver)
    method = _text(o["Method"]).lower() if "Method" in o else "auto"
    if method not in ("auto", "tiled", "iterated"):
        raise _err("%s: Method must be \"auto\", \"tiled\" or \"iterated\"." % solver)
    if method == "tiled":
        raise _err("%s: the \"tiled\" method is not supported in Sagebrush; use \"iterated\" (which \"auto\" uses)." % solver)
    if "Waypoints" in o:
        raise _err("%s: Waypoints are not supported in Sagebrush." % solver)
    vectorized = not ("Vectorized" in o and not bool(_m._logical_val(o["Vectorized"])))
    single = False
    lim = []
    for v in lims:
        if _m._iscallable(v) or _istext(v):
            lim.append(_m._fn_arg(v))
        else:
            if type(v) is _m.Char or not _m._isnumlike(v) or _m._numel(v) != 1 or np.iscomplexobj(_m._arr(v)):
                raise _err("%s: the limits must be real scalars or function handles." % solver)
            single = single or _m.class_(v) == "single"
            x = float(_m._scalar(v))
            if x != x:
                raise _err("%s: the limits must not be NaN." % solver)
            lim.append(x)
    for v in lim[:2]:
        if callable(getattr(v, "call", None)):
            raise _err("%s: xmin and xmax must be real scalars." % solver)
    failed = []

    def warn(msg):
        failed.append(msg)

    def real(y):
        # (complex values, of the integrand or a limit function, are refused,
        # before anything is stored as real numbers)
        if np.iscomplexobj(y):
            if np.any(np.imag(y) != 0):
                raise _err("%s: complex integrands and limits are not supported in Sagebrush." % solver)
            y = np.real(y)
        return np.array(y, dtype=float)

    def call(fn, args):
        """fn at arrays of points: vectorized, or one point at a time"""
        n = args[0].size
        if vectorized:
            r = _m._call(fn, [_m._box(np.array(a, dtype=float).reshape((-1, 1))) for a in args])
            y = np.array(_m._arr(r)).reshape(-1) if _m._isnumlike(r) and type(r) is not _m.Char else None
            if y is not None:
                y = real(y)
            if y is None or y.size != n:
                raise _err("%s: the integrand and limit functions must return arrays the size of their inputs; use "
                           "array operators (.*, ./, .^) or set Vectorized to false." % solver)
            return y
        out = np.empty(n)
        for i in range(n):
            r = _m._call(fn, [float(a[i]) for a in args])
            if not _m._isnumlike(r) or type(r) is _m.Char or _m._numel(r) != 1:
                raise _err("%s: with Vectorized false, the integrand and limit functions must return scalars." % solver)
            out[i] = real(np.array(_m._arr(r)).reshape(-1))[0]
        return out

    def limit(v, args):
        return call(v, args) if not isinstance(v, float) else np.full(args[0].size, v)
    if len(lim) == 4:
        def outer(xs):
            lo, hi = limit(lim[2], [xs]), limit(lim[3], [xs])
            return np.array([_quad1(lambda ys, x=x: call(f, [np.full(ys.size, x), ys]), lo[i], hi[i], atol, rtol,
                                    solver, warn) for i, x in enumerate(xs)])
    else:
        def outer(xs):
            lo, hi = limit(lim[2], [xs]), limit(lim[3], [xs])
            vals = []
            for i, x in enumerate(xs):
                def middle(ys, x=x):
                    xv = np.full(ys.size, x)
                    zl, zu = limit(lim[4], [xv, ys]), limit(lim[5], [xv, ys])
                    return np.array([_quad1(lambda zs, y=y: call(f, [np.full(zs.size, x), np.full(zs.size, y), zs]),
                                            zl[j], zu[j], atol, rtol, solver, warn) for j, y in enumerate(ys)])
                vals.append(_quad1(middle, lo[i], hi[i], atol, rtol, solver, warn))
            return np.array(vals)
    q = _quad1(outer, lim[0], lim[1], atol, rtol, solver, warn)
    if failed:
        _m.warning_("%s: %s" % (solver, failed[-1].split(": ", 1)[-1] if failed[-1].startswith(solver) else failed[-1]))
    if single:
        return _m._canon(np.array([[q]], dtype=np.float32))
    return q


@_bi("integral2")
def integral2_(nargout, fun=None, xmin=None, xmax=None, ymin=None, ymax=None, *opts):
    """integral2 as its documentation page describes it: the integral of
    fun(x, y) over xmin <= x <= xmax, ymin(x) <= y <= ymax(x) (limits
    numbers, possibly infinite, or functions of x), with AbsoluteTolerance
    (AbsTol, 1e-10), RelativeTolerance (RelTol, 1e-6), Method and
    Vectorized.  The method is the page's "iterated" one: integral over x
    of integral over y, each by integral's (Shampine 2008).  Sagebrush's
    own choices: "auto" is "iterated" (the "tiled" method, Shampine's 2-D
    program, which its page cites, is not available here, and is refused),
    the inner integrals use the same tolerances, and their warnings are
    reported once; Waypoints are refused"""
    if ymax is None:
        raise _err("Not enough input arguments.")
    if nargout > 1:
        raise _err("Too many output arguments.")
    return _multi(nargout, "integral2", fun, [xmin, xmax, ymin, ymax], list(opts))


@_bi("integral3")
def integral3_(nargout, fun=None, xmin=None, xmax=None, ymin=None, ymax=None, zmin=None, zmax=None, *opts):
    """integral3 as its documentation page describes it: the integral of
    fun(x, y, z) over xmin <= x <= xmax, ymin(x) <= y <= ymax(x),
    zmin(x, y) <= z <= zmax(x, y), with the options and the iterated method
    of integral2 (and its own choices)"""
    if zmax is None:
        raise _err("Not enough input arguments.")
    if nargout > 1:
        raise _err("Too many output arguments.")
    return _multi(nargout, "integral3", fun, [xmin, xmax, ymin, ymax, zmin, zmax], list(opts))

files._matlab_more.py:
"""More of MATLAB's built-ins, for lib/_matlab.py: split, join and replace, the
conversions between numbers and binary or hexadecimal text (dec2bin,
dec2hex, bin2dec, hex2dec), sub2ind and ind2sub, and mat2cell, as their
documentation pages describe them.  Where a page leaves a case open,
these give an error rather than a guess (design/matlab.md).
"""

import math as _math

import numpy as np

import _matlab as _m
from _matlab import _bi, _err, Cell, Char, Str, StrArr

_WSPACE = " \t\n\r\f\v"  # (isspace's characters)


# ------------------------------------------------------------------ text: split and replace


def _texts(v, name, what="str"):
    """v's elements as Python strings, its dimensions, and whether it is a
    string (or string array): a character vector, string, string array or
    cell array of character vectors"""
    t = type(v)
    if t is Char:
        d = _m._dims(v)
        if len(d) > 2 or (d[0] > 1 and _m._numel(v) > 0):
            raise _err("%s: %s must be a character vector, not a character matrix." % (name, what))
        return [v.text()], (1, 1), False
    if t is Str:
        if v.s is None:
            raise _err("%s: %s must not be a missing string." % (name, what))
        return [v.s], (1, 1), True
    if t is StrArr:
        if any(s is None for s in v.a):
            raise _err("%s: %s must not contain missing strings." % (name, what))
        return list(v.a), v.shape, True
    if t is Cell:
        out = []
        for e in v.a:
            if type(e) is not Char:
                raise _err("%s: %s must be text: a cell array's elements must be character vectors." % (name, what))
            out.append(_texts(e, name, what)[0][0])
        return out, v.shape, False
    raise _err("%s: %s must be a string array, character vector or cell array of character vectors, not %s." % (name, what, _m.class_(v)))


def _as(strings, dims, isstr):
    """Python strings, column-major, as a string array or a cell array of
    character vectors, without trailing singleton dimensions (as Cell's are)"""
    dims = _m._canon_dims(dims)
    if isstr:
        return _m._strarr(list(strings), dims) if _m._prod(dims) != 1 else Str(strings[0])
    return Cell([Char(s) for s in strings], dims)


def _linear(sub, dims):
    k, stride = 0, 1
    for s, d in zip(sub, dims):
        k += s * stride
        stride *= d
    return k


def _subs(k, dims):
    out = []
    for d in dims:
        out.append(k % d)
        k //= d
    return out


@_bi("split")
def split_(nargout, *args):
    """newStr = split(str), split(str, delimiter), split(str, delimiter, dim):
    str divided at the delimiters (whitespace characters when there is none),
    which the pieces do not include; [newStr, match] = split(...) also
    returns the delimiters found.

    With several delimiters the leftmost match is taken, and of those that
    begin at the same character the first listed.  Consecutive delimiters
    give empty pieces.  The pieces go along the first trailing dimension of
    str of size 1, or along dim.  With the default delimiter, Sagebrush
    refuses text that begins or ends with whitespace or has adjacent
    whitespace characters (MATLAB's documentation does not say what split
    makes of them): give the delimiter."""
    if not 1 <= len(args) <= 3:
        raise _err("Not enough input arguments." if not args else "Too many input arguments.")
    if nargout > 2:
        raise _err("Too many output arguments.", "MATLAB:TooManyOutputs")
    texts, dims, isstr = _texts(args[0], "split")
    if len(args) >= 2:
        delims, _, _ = _texts(args[1], "split", "delimiter")
        if any(d == "" for d in delims):
            raise _err("split: a delimiter must not be empty.")
        if not delims:
            raise _err("split: delimiter must not be empty.")
    else:
        delims = list(_WSPACE)
        for t in texts:
            if t and (t[0] in _WSPACE or t[-1] in _WSPACE or any(a in _WSPACE and b in _WSPACE for a, b in zip(t, t[1:]))):
                raise _err("split: Sagebrush splits at whitespace only where it separates text, one whitespace character at a time; "
                           "for text that begins or ends with whitespace, or has adjacent whitespace characters, give the delimiter.")
    pieces, matches = [], []
    for t in texts:
        p, mt = [], []
        start = i = 0
        while i < len(t):
            for d in delims:
                if t.startswith(d, i):
                    p.append(t[start:i])
                    mt.append(d)
                    i += len(d)
                    start = i
                    break
            else:
                i += 1
        p.append(t[start:])
        pieces.append(p)
        matches.append(mt)
    n = len(pieces[0]) if pieces else 1
    if any(len(p) != n for p in pieces):
        raise _err("split: every element of str must split into the same number of pieces; split them one at a time.")
    dims = list(dims)
    nonsingle = [k for k, d in enumerate(dims) if d != 1]
    transpose = False
    if len(args) == 3:
        dim = _m._int_arg(args[2], "dimension")
        if dim < 1:
            raise _err("split: dim must be a positive integer.")
        dim -= 1
        if dim < len(dims) and dims[dim] != 1:
            # (the documented case: an M-by-1 array's pieces along the rows, an N-by-M result)
            if dim == 0 and len(dims) == 2 and dims[1] == 1:
                transpose = True
                dims = [1, dims[0]]
            else:
                raise _err("split: str has more than one element along dimension %d, so the pieces cannot go along it." % (dim + 1))
    else:
        dim = nonsingle[-1] + 1 if nonsingle else 0
    while len(dims) <= dim:
        dims.append(1)

    def place(lists, count):
        od = list(dims)
        od[dim] = count
        out = [None] * _m._prod(od)
        for k, lst in enumerate(lists):
            sub = _subs(k, dims)
            for j, s in enumerate(lst):
                sub[dim] = j
                out[_linear(sub, od)] = s
        return _as(out, od, isstr)
    r = place(pieces, n)
    return r if nargout < 2 else [r, place(matches, n - 1)]


@_bi("replace")
def replace_(nargout, *args):
    """newStr = replace(str, old, new): every occurrence of old in str
    replaced by new, scanning from the left; occurrences do not overlap.
    old can list several substrings, new one or as many as old.  Where two
    of them begin at the same character the first listed is replaced if it
    is also the longest; otherwise Sagebrush gives an error, as MATLAB's
    documentation does not say which wins."""
    if len(args) != 3:
        raise _err("Not enough input arguments." if len(args) < 3 else "Too many input arguments.")
    texts, dims, _ = _texts(args[0], "replace")
    olds, odims, _ = _texts(args[1], "replace", "old")
    news, ndims, _ = _texts(args[2], "replace", "new")
    if any(o == "" for o in olds):
        raise _err("replace: old must not be empty text.")
    if len(news) != 1 and (len(news) != len(olds) or tuple(ndims) != tuple(odims)):
        raise _err("replace: new must be one piece of text or the same size as old.")
    if len(news) == 1:
        news = news * len(olds)

    def one(t):
        out = []
        i = 0
        while i < len(t):
            hits = [k for k, o in enumerate(olds) if t.startswith(o, i)]
            if not hits:
                out.append(t[i])
                i += 1
                continue
            k = hits[0]
            if any(len(olds[h]) > len(olds[k]) for h in hits):
                raise _err("replace: '%s' and '%s' both begin at character %d; Sagebrush does not choose between them." % (olds[k], olds[max(hits, key=lambda h: len(olds[h]))], i + 1))
            out.append(news[k])
            i += len(olds[k])
        return "".join(out)
    v = args[0]
    res = [one(t) for t in texts]
    if type(v) is Char:
        return Char(res[0])
    if type(v) is Str:
        return Str(res[0])
    return _as(res, dims, type(v) is StrArr)


@_bi("join")
def join_(nargout, *args):
    """newStr = join(str), join(str, delimiter), join(str, dim),
    join(str, delimiter, dim): the text of a string array or cell array of
    character vectors joined along dim (by default the last dimension whose
    size is not 1), with a space or the delimiter between the elements; the
    result has str's type and size 1 along dim.  An array of delimiters has
    one fewer element than str along dim, and along each other dimension
    either str's size or 1.  Delimiters are literal text."""
    if not 1 <= len(args) <= 3:
        raise _err("Not enough input arguments." if not args else "Too many input arguments.")
    v = args[0]
    if type(v) not in (Str, StrArr, Cell):
        raise _err("join: str must be a string array or a cell array of character vectors, not %s." % _m.class_(v))
    texts, dims, isstr = _texts(v, "join")
    rest = list(args[1:])
    dim = None
    if rest and _m._isnumlike(rest[-1]) and type(rest[-1]) is not Char:
        dim = _m._int_arg(rest.pop(), "dimension")
        if dim < 1:
            raise _err("join: dim must be a positive integer.")
        dim -= 1
    if len(rest) > 1:
        raise _err("join: the arguments are str, then a delimiter, then dim.")
    S = list(dims)
    if dim is None:
        nonsingle = [k for k, d in enumerate(S) if d != 1]
        dim = nonsingle[-1] if nonsingle else 0
    while len(S) <= dim:
        S.append(1)
    n = S[dim]
    if n == 0:
        raise _err("join: str has no elements along dimension %d; Sagebrush does not join nothing (the page leaves the result open)." % (dim + 1))
    if rest:
        delims, ddims, _ = _texts(rest[0], "join", "delimiter")
        D = list(ddims)
    else:
        delims, D = [" "], [1, 1]
    while len(D) < len(S):
        D.append(1)
    if len(D) > len(S) and any(d != 1 for d in D[len(S):]):
        raise _err("join: delimiter has more dimensions than str.")
    D = D[:len(S)]
    single = len(delims) == 1
    if not single:
        bad = D[dim] != n - 1 or any(D[k] not in (1, S[k]) for k in range(len(S)) if k != dim)
        if bad:
            raise _err("join: delimiter must have %d element%s along dimension %d (one fewer than str), and along each other dimension str's size or 1." % (n - 1, "" if n == 2 else "s", dim + 1))
    O = list(S)
    O[dim] = 1
    out = []
    for k in range(_m._prod(O)):
        sub = _subs(k, O)
        parts = []
        for j in range(n):
            if j:
                if single:
                    parts.append(delims[0])
                else:
                    ds = [0 if D[q] == 1 else sub[q] for q in range(len(S))]
                    ds[dim] = j - 1
                    parts.append(delims[_linear(ds, D)])
            sub[dim] = j
            parts.append(texts[_linear(sub, S)])
            sub[dim] = 0
        out.append("".join(parts))
    return _as(out, O, isstr)


# ------------------------------------------------------------------ numbers as binary and hexadecimal text


def _base_text(name, args, radix):
    if not 1 <= len(args) <= 2:
        raise _err("Not enough input arguments." if not args else "Too many input arguments.")
    D = args[0]
    cls = _m.class_(D)
    if not (_m._isnumlike(D) and type(D) is not _m.Sparse) or cls in ("cell", "struct", "string"):
        raise _err("%s: D must be a numeric, logical or char array, not %s." % (name, cls))
    mind = 0
    if len(args) == 2:
        x = _m._real_scalar(args[1], "minDigits")
        if not (x >= 0 and x == _math.floor(x) and _math.isfinite(x)):
            raise _err("%s: minDigits must be a nonnegative integer." % name)
        mind = int(x)
    A = _m._arr(D)
    if A.dtype.kind == "c":
        raise _err("%s: D must be real." % name)
    if A.size == 0:
        raise _err("%s: Sagebrush does not convert an empty array (MATLAB's documentation leaves the result open)." % name)
    vals = []
    for x in A.reshape(-1):  # (column-major: one row per element)
        if A.dtype.kind in "iu":
            v = int(x)
            if v < 0:
                raise _err("%s: Sagebrush does not convert negative values of an integer class (MATLAB's documentation leaves their width open); convert them to double first." % name)
        else:
            x = float(x)
            if not _math.isfinite(x):
                raise _err("%s: D must contain finite values." % name)
            if radix == 16 and x != _math.floor(x):
                raise _err("dec2hex: D must contain integers: %s has a fractional part." % _m._num2str_g(x))
            v = int(_math.floor(x))  # (dec2bin: the integer at most x)
        if not -(1 << 63) <= v < (1 << 64):
            raise _err("%s: D's values must be at least intmin('int64') and less than 2^64." % name)
        vals.append(v)
    lo = min(vals)
    pad = "0"
    if lo < 0:
        # (two's complement in the narrowest of 8, 16, 32 and 64 bits that holds every value)
        hi = max(vals)
        for w in (8, 16, 32, 64):
            if -(1 << (w - 1)) <= lo and hi < (1 << (w - 1)):
                break
        else:
            raise _err("%s: with negative values, D's values must fit in a signed 64-bit integer." % name)
        vals = [v + (1 << w) if v < 0 else v for v in vals]
        bits = w
    else:
        bits = 0
    digits = [format(v, "b" if radix == 2 else "X") for v in vals]
    per = 1 if radix == 2 else 4
    width = max(max(len(s) for s in digits), mind, bits // per)
    rows = []
    for s, v0 in zip(digits, vals):
        neg = bits and v0 >= (1 << (bits - 1))
        rows.append(("1" if radix == 2 else "F") * (width - len(s)) + s if neg else s.rjust(width, pad))
    return _m._rows_char(rows)


@_bi("dec2bin")
def dec2bin_(nargout, *args):
    """binStr = dec2bin(D), dec2bin(D, minDigits): the binary digits of the
    integers in D, one row per element, at least minDigits of them.
    Fractions are rounded down; negative numbers are two's complement in
    the narrowest of 8, 16, 32 and 64 bits that holds every element, and
    are padded with ones."""
    return _base_text("dec2bin", args, 2)


@_bi("dec2hex")
def dec2hex_(nargout, *args):
    """hexStr = dec2hex(D), dec2hex(D, minDigits): the hexadecimal digits
    (0-9, A-F) of the integers in D, one row per element, at least
    minDigits of them.  D must hold integers; negative numbers are two's
    complement in the narrowest of 8, 16, 32 and 64 bits that holds every
    element, and are padded with F."""
    return _base_text("dec2hex", args, 16)


_SUFFIX = {"u8": ("uint", 8), "u16": ("uint", 16), "u32": ("uint", 32), "u64": ("uint", 64),
           "s8": ("int", 8), "s16": ("int", 16), "s32": ("int", 32), "s64": ("int", 64)}


def _parse_base(name, t, radix):
    s = t.strip(" ")
    prefix = "0b" if radix == 2 else "0x"
    ok = "01" if radix == 2 else "0123456789abcdefABCDEF"
    kind = None
    if s[:2].lower() == prefix:
        s = s[2:]
        for suf in sorted(_SUFFIX, key=len, reverse=True):
            if s.endswith(suf) and len(s) > len(suf):
                kind = _SUFFIX[suf]
                s = s[:-len(suf)]
                break
    if not s or any(c not in ok for c in s):
        raise _err("%s: '%s' is not %s text." % (name, t, "binary" if radix == 2 else "hexadecimal"))
    if radix == 2 and len(s) > 53:
        raise _err("bin2dec: '%s' has more than 53 binary digits." % t)
    v = int(s, radix)
    if kind:
        sign, w = kind
        if v >= (1 << w):
            raise _err("%s: '%s' does not fit in its %s%d suffix's %d bits." % (name, t, sign, w, w))
        if sign == "int" and v >= (1 << (w - 1)):
            v -= 1 << w
    return v


def _from_base(name, args, radix):
    if len(args) != 1:
        raise _err("Not enough input arguments." if not args else "Too many input arguments.")
    v = args[0]
    t = type(v)
    if t is Char:
        d = _m._dims(v)
        if len(d) > 2:
            raise _err("%s: the text must be a character vector or matrix." % name)
        if _m._numel(v) == 0:
            raise _err("%s: Sagebrush does not convert empty text (MATLAB's documentation leaves the result open)." % name)
        texts, shape = v.rows(), (d[0], 1)
    elif t is Cell:
        texts = []
        for e in v.a:
            if type(e) is not Char or _m._dims(e)[0] > 1 and _m._numel(e) > 0:
                raise _err("%s: a cell array's elements must be character vectors." % name)
            texts.append(e.text())
        shape = (len(texts), 1)
    elif t is Str or t is StrArr:
        texts = [v.s] if t is Str else list(v.a)
        if any(s is None for s in texts):
            raise _err("%s: the text must not contain missing strings." % name)
        shape = (1, 1) if t is Str else v.shape
    else:
        raise _err("%s: the text must be a character array, cell array of character vectors or string array, not %s." % (name, _m.class_(v)))
    vals = [_parse_base(name, s, radix) for s in texts]
    if any(abs(x) >= 2 ** 53 for x in vals):
        _m.warning_("%s: a value of at least flintmax (2^53) might not be represented exactly as a double." % name)
    return _m._box(np.array([float(x) for x in vals], dtype=float).reshape(_m._stored(shape)))


@_bi("bin2dec")
def bin2dec_(nargout, *args):
    """D = bin2dec(binStr): the binary integers that binStr's text
    represents, as doubles: one per row of a character matrix or element
    of a cell array (a column), or per element of a string array (its
    shape).  The text may have the prefix 0b and a type suffix of binary
    literals (0b11111111s8 is -1); at most 53 digits.  Spaces around the
    digits are ignored; any other character is an error."""
    return _from_base("bin2dec", args, 2)


@_bi("hex2dec")
def hex2dec_(nargout, *args):
    """D = hex2dec(hexStr): the hexadecimal integers (0-9 and A-F or a-f)
    that hexStr's text represents, as doubles: one per row of a character
    matrix or element of a cell array (a column), or per element of a
    string array (its shape).  The text may have the prefix 0x and a type
    suffix of hexadecimal literals (0xFFs8 is -1).  Spaces around the
    digits are ignored; any other character is an error.  A value of at
    least flintmax gives a warning: it might not be exact."""
    return _from_base("hex2dec", args, 16)


# ------------------------------------------------------------------ subscripts and linear indices


def _size_vec(name, sz):
    a = _m._farr(sz, name) if _m._isnumlike(sz) and type(sz) is not Char else None
    if a is None or a.dtype.kind == "c" or a.size == 0 or min(_m._dims(sz)) != 1 and a.size != 1 or len(_m._dims(sz)) > 2:
        raise _err("%s: sz must be a vector of positive integers." % name)
    d = [float(x) for x in a.reshape(-1)]
    if any(not (x >= 1 and x == _math.floor(x) and _math.isfinite(x)) for x in d):
        raise _err("%s: sz must be a vector of positive integers." % name)
    return [int(x) for x in d]


def _int_array(name, v, what):
    if not _m._isnumlike(v) or type(v) is Char or type(v) is _m.Sparse:
        raise _err("%s: %s must be numeric, not %s." % (name, what, _m.class_(v)))
    a = _m._arr(v)
    if a.dtype.kind == "c":
        raise _err("%s: %s must be real." % (name, what))
    f = a.astype(float) if a.dtype.kind != "f" else a
    if f.size and (not np.all(np.isfinite(f)) or np.any(f != np.floor(f)) or np.any(f < 1)):
        raise _err("%s: %s must be positive integers." % (name, what))
    return a, _m._dims(v)


_EXACT = 2 ** 53  # (every integer up to it is a double)


def _exact(name, vals):
    """Python integers as doubles, refused unless each is one exactly"""
    out = np.array([float(v) for v in vals], dtype=float)
    for v, f in zip(vals, out.reshape(-1)):
        if int(f) != v:
            raise _err("%s: the result %d is not exactly a double (above 2^53); Sagebrush does not round it." % (name, v))
    return out


@_bi("sub2ind")
def sub2ind_(nargout, *args):
    """ind = sub2ind(sz, I1, ..., In): the linear indices of the elements
    at subscripts I1, ..., In of an array of size sz: one subscript for
    each element of sz (trailing ones may be added).  The subscripts are
    arrays of the same size, or scalars, which expand.  The arithmetic is
    exact; an index above 2^53 that is not exactly a double is an error."""
    if len(args) < 2:
        raise _err("Not enough input arguments.")
    d = _size_vec("sub2ind", args[0])
    subs = [_int_array("sub2ind", v, "the subscripts") for v in args[1:]]
    n = len(subs)
    if n < len(d):
        raise _err("sub2ind: give one subscript for each of sz's %d dimensions." % len(d))
    d = d + [1] * (n - len(d))
    shapes = {dims for a, dims in subs if a.size != 1}
    if len(shapes) > 1:
        raise _err("sub2ind: the subscripts must be the same size, or scalars.")
    shape = shapes.pop() if shapes else (1, 1)
    count = _m._prod(shape)
    for k, ((a, _), dk) in enumerate(zip(subs, d)):
        if a.size and float(np.max(a)) > dk:
            raise _err("sub2ind: subscript %d is out of range: at most %d." % (k + 1, dk))
    if _m._prod(d) <= _EXACT:
        # (every partial sum is an integer of at most prod(sz): exact in doubles)
        ind = np.zeros(count)
        stride = 1
        for (a, _), dk in zip(subs, d):
            ind = ind + (a.reshape(-1).astype(float) - 1) * stride
            stride *= dk
        return _m._box((ind + 1).reshape(_m._stored(shape)))
    # (larger arrays: in integers, then refused if a result is not a double exactly)
    cols = [[int(x) for x in a.reshape(-1)] for a, _ in subs]
    out = []
    for i in range(count):
        v, stride = 0, 1
        for col, dk in zip(cols, d):
            v += (col[i if len(col) > 1 else 0] - 1) * stride
            stride *= dk
        out.append(v + 1)
    return _m._box(_exact("sub2ind", out).reshape(_m._stored(shape)))


@_bi("ind2sub")
def ind2sub_(nargout, *args):
    """[I1, ..., In] = ind2sub(sz, ind): the subscripts of the elements at
    linear indices ind of an array of size sz, each the size of ind.  With
    fewer outputs than sz has elements, the last output counts along the
    remaining dimensions taken together; the last subscript is not bounded,
    the array growing along its last dimension as indexing would.  sz has
    two or more elements (a scalar is an error since R2024b: [n 1] for a
    column).  The arithmetic is exact; a subscript above 2^53 that is not
    exactly a double is an error."""
    if len(args) != 2:
        raise _err("Not enough input arguments." if len(args) < 2 else "Too many input arguments.")
    d = _size_vec("ind2sub", args[0])
    if len(d) < 2:
        # (R2024b: "a scalar input for sz results in an error")
        raise _err("ind2sub: sz must be a vector of positive integers with two or more elements; for a column of n elements, give [n 1].")
    a, shape = _int_array("ind2sub", args[1], "ind")
    k = max(1, nargout)
    if k < len(d):
        d = d[:k - 1] + [_m._prod(d[k - 1:])]
    d = d + [1] * (k - len(d))
    if not a.size or float(np.max(a)) + max(d) < 2.0 ** 52:
        # (then r // d and r mod d of doubles are exact: r/d rounds to no integer above it)
        r = a.reshape(-1).astype(float) - 1
        outs = []
        for j in range(k - 1):
            outs.append(np.mod(r, d[j]) + 1)
            r = np.floor(r / d[j])
        outs.append(r + 1)
    else:
        # (in integers, then refused if a subscript is not a double exactly)
        rs = [int(x) - 1 for x in a.reshape(-1)]
        cols = []
        for j in range(k - 1):
            cols.append([x % d[j] + 1 for x in rs])
            rs = [x // d[j] for x in rs]
        cols.append([x + 1 for x in rs])
        outs = [_exact("ind2sub", c) for c in cols]
    outs = [_m._box(o.reshape(_m._stored(shape))) for o in outs]
    return outs[0] if k == 1 else outs


# ------------------------------------------------------------------ mat2cell


@_bi("mat2cell")
def mat2cell_(nargout, *args):
    """C = mat2cell(A, dim1Dist, ..., dimNDist): A divided into the cells of
    C, dimKDist giving the sizes of the pieces along dimension K, which
    must add up to A's size there.  Dimensions without a distribution are
    not divided: C = mat2cell(A, rowDist) is a column of cells."""
    if len(args) < 2:
        raise _err("Not enough input arguments.")
    A = args[0]
    if _m._iscallable(A):
        raise _err("mat2cell: A must be an array, not a function handle.")
    D = list(_m._dims(A))
    dists = []
    for k, v in enumerate(args[1:]):
        if not _m._isnumlike(v) or type(v) is Char or type(v) is _m.Sparse:
            raise _err("mat2cell: the distributions must be numeric vectors.")
        a = _m._farr(v, "mat2cell")
        f = [float(x) for x in a.reshape(-1)] if a.dtype.kind != "c" else None
        if f is None or a.size and min(_m._dims(v)) != 1 or any(not (x >= 0 and x == _math.floor(x)) for x in f):
            raise _err("mat2cell: the distribution for dimension %d must be a vector of nonnegative integers." % (k + 1))
        dists.append([int(x) for x in f])
    nd = max(len(D), len(dists))
    D = D + [1] * (nd - len(D))
    dists = dists + [[D[k]] for k in range(len(dists), nd)]
    for k in range(nd):
        if sum(dists[k]) != D[k]:
            raise _err("mat2cell: the distribution for dimension %d adds up to %d, not to A's size there, %d." % (k + 1, sum(dists[k]), D[k]))
    starts = [np.concatenate([[0], np.cumsum(dk)[:-1]]).astype(int) if dk else [] for dk in dists]
    cdims = [len(dk) for dk in dists]
    out = []
    for c in range(_m._prod(cdims)):
        sub = _subs(c, cdims)
        idx = []
        for k in range(nd):
            s, n = int(starts[k][sub[k]]), dists[k][sub[k]]
            idx.append(np.arange(s + 1, s + n + 1, dtype=float).reshape((n, 1)) if n != 1 else float(s + 1))
        out.append(_m.index(A, idx))
    return Cell(out, cdims)

files._matlab_numeric.py:
"""More of MATLAB's numerical functions, for lib/_matlab.py: special
matrices and matrix functions.  Each registers a built-in in _matlab's table
(_bs/_bi), the same way lib/_matlab.py's do.
"""

import math as _math

import numpy as np

import _matlab as _m
from _matlab import _bs, _bi, _err, _mat, _unmat, _box, _arr, _scalar, _istext, _text, Char


def _n_arg(n, what="n"):
    v = _m._real_scalar(n, what)
    if v != _math.floor(v):
        raise _err("Input must be a nonnegative integer.")
    return max(0, int(v))


def _class_arg(args, default="double"):
    """a trailing class name ('double' or 'single')"""
    if args and _istext(args[-1]):
        c = _text(args[-1])
        if c not in ("double", "single"):
            raise _err("Class must be 'double' or 'single'.")
        return list(args[:-1]), c
    return list(args), default


def _as_class(M, cls):
    r = _unmat(M)
    if cls == "single":
        return _m._canon(_arr(r).astype(np.float32))
    return r


# ------------------------------------------------------------------ special matrices

@_bs("hilb")
def hilb_(n, *args):
    _, cls = _class_arg(args)
    n = _n_arg(n)
    i = np.arange(1, n + 1, dtype=np.float64)
    return _as_class(1.0 / (i.reshape((-1, 1)) + i.reshape((1, -1)) - 1.0), cls)


@_bs("invhilb")
def invhilb_(n, *args):
    """the exact inverse of hilb(n), entry by entry from the closed form
    (H_n^-1)_ij = (-1)^(i+j) (i+j-1) C(n+i-1, n-j) C(n+j-1, n-i) C(i+j-2, i-1)^2
    (Choi, "Tricks or treats with the Hilbert matrix", Amer. Math. Monthly
    90, 1983), in exact integers, then rounded once to double"""
    _, cls = _class_arg(args)
    n = _n_arg(n)
    H = np.zeros((n, n))
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            v = (i + j - 1) * _math.comb(n + i - 1, n - j) * _math.comb(n + j - 1, n - i) * _math.comb(i + j - 2, i - 1) ** 2
            H[i - 1, j - 1] = H[j - 1, i - 1] = float(-v if (i + j) % 2 else v)
    return _as_class(H, cls)


@_bs("pascal")
def pascal_(n, k=0.0, *args):
    """pascal(n): binomial coefficients, P(i,j) = (i+j-2 choose j-1); pascal(n,1): the
    lower triangular Cholesky factor, with alternating column signs; pascal(n,2):
    a transposed and permuted version of it (a cube root of the identity)"""
    if _istext(k):
        args = (k,) + args
        k = 0.0
    _, cls = _class_arg(args)
    n = _n_arg(n)
    k = _m._int_arg(k)
    if k not in (0, 1, 2):
        raise _err("K must be 0, 1, or 2.")
    L = np.zeros((n, n))
    for i in range(n):
        for j in range(i + 1):
            L[i, j] = (-1) ** j * _math.comb(i, j)
    if k == 0:
        P = np.array([[float(_math.comb(i + j, j)) for j in range(n)] for i in range(n)])
    elif k == 1:
        P = L
    else:
        P = np.rot90(L, 3) if n else L
        P = np.array(P)
        if n % 2 == 0:
            P = -P
    return _as_class(P, cls)


@_bs("vander")
def vander_(v, n=None):
    c = _arr(v).reshape(-1).astype(np.complex128 if _arr(v).dtype.kind == "c" else np.float64)
    m = c.size if n is None else _n_arg(n)
    V = np.ones((c.size, m), dtype=c.dtype)
    for j in range(m - 2, -1, -1):
        V[:, j] = V[:, j + 1] * c
    return _unmat(V)


@_bs("toeplitz")
def toeplitz_(c, r=None):
    """toeplitz(c, r): c down the first column, r along the first row (c(1)
    winning, with a warning, when they differ); toeplitz(r): symmetric, or
    Hermitian for complex r"""
    if r is None:
        rr = _arr(c).reshape(-1)
        cc = np.conj(rr) if rr.dtype.kind == "c" else rr
        cc = np.array(cc)
        if cc.size:
            cc[0] = rr[0]
    else:
        cc = _arr(c).reshape(-1)
        rr = _arr(r).reshape(-1)
        if cc.size and rr.size and rr[0] != cc[0]:
            _m.warning_("First element of input column does not match first element of input row. \n         Column wins diagonal conflict.")
    m, n = cc.size, rr.size
    cplx = cc.dtype.kind == "c" or rr.dtype.kind == "c"
    T = np.zeros((m, n), dtype=np.complex128 if cplx else np.float64)
    for i in range(m):
        for j in range(n):
            T[i, j] = cc[i - j] if i >= j else rr[j - i]
    return _unmat(T)


@_bs("hankel")
def hankel_(c, r=None):
    """hankel(c): c in the first column, zeros below the anti-diagonal;
    hankel(c, r): c in the first column, r in the last row (c(end) wins)"""
    cc = _arr(c).reshape(-1)
    m = cc.size
    if r is None:
        rr = np.zeros(m, dtype=cc.dtype)
    else:
        rr = _arr(r).reshape(-1)
        if m and rr.size and rr[0] != cc[-1]:
            _m.warning_("Last element of input column does not match first element of input row. \n         Column wins anti-diagonal conflict.")
    n = rr.size
    cplx = cc.dtype.kind == "c" or rr.dtype.kind == "c"
    H = np.zeros((m, n), dtype=np.complex128 if cplx else np.float64)
    for i in range(m):
        for j in range(n):
            k = i + j
            H[i, j] = cc[k] if k < m else rr[k - m + 1]
    return _unmat(H)


@_bs("rosser")
def rosser_(*args):
    _, cls = _class_arg(args)
    R = np.array([[611, 196, -192, 407, -8, -52, -49, 29], [196, 899, 113, -192, -71, -43, -8, -44],
                  [-192, 113, 899, 196, 61, 49, 8, 52], [407, -192, 196, 611, 8, 44, 59, -23],
                  [-8, -71, 61, 8, 411, -599, 208, 208], [-52, -43, 49, 44, -599, 411, 208, 208],
                  [-49, -8, 8, 59, 208, 208, 99, -911], [29, -44, 52, -23, 208, 208, -911, 99]], dtype=np.float64)
    return _as_class(R, cls)


@_bs("wilkinson")
def wilkinson_(n, *args):
    _, cls = _class_arg(args)
    n = _n_arg(n)
    m = (n - 1) / 2.0
    W = np.diag(np.abs(np.arange(n) - m)) if n else np.zeros((0, 0))
    W = np.array(W, dtype=np.float64)
    for i in range(n - 1):
        W[i, i + 1] = W[i + 1, i] = 1.0
    return _as_class(W, cls)


# ------------------------------------------------------------------ matrix functions

def _square(M, name):
    if M.ndim != 2 or M.shape[0] != M.shape[1]:
        raise _err("Input matrix must be square.")


def _cdiv_right(A, V):
    """A / V for complex matrices: (V^T \\ A^T)^T, through the LU that takes complex values"""
    X = _m._lu_solve_through(np.array(V.T), np.array(A.T))
    return np.array(X.T)


def _fun_of_matrix(x, f, name):
    """f(A) through the eigendecomposition: V f(D) V^-1 (V orthonormal for a
    symmetric or Hermitian A); real when the result is"""
    A = _mat(x)
    _square(A, name)
    n = A.shape[0]
    if n == 0:
        return _unmat(A)
    cplx = A.dtype.kind == "c"
    herm = np.array_equal(A, np.conj(A.T))
    if herm and not cplx:
        w, V = np.linalg.eigh(A)
        F = (V * f(w.astype(np.complex128)).reshape((1, -1))) @ V.T
    else:
        w, V = np.linalg._eig(A)
        w = np.asarray(w).astype(np.complex128)
        V = np.asarray(V).astype(np.complex128)
        F = _cdiv_right(V * f(w).reshape((1, -1)), V)
    F = np.asarray(F)
    if not np.any(np.imag(F)):
        F = np.real(F)
    elif not cplx and np.max(np.abs(np.imag(F))) <= 10 * n * 2.220446049250313e-16 * max(1.0, float(np.max(np.abs(F)))):
        F = np.real(F)
    return _box(np.array(F.T))


def _inv(M):
    n = M.shape[0]
    return _m._lu_solve_through(np.array(M, dtype=np.complex128), np.eye(n, dtype=np.complex128))


def _norm1(M):
    return float(np.max(np.sum(np.abs(M), axis=0))) if M.size else 0.0


def _well_diagonalizable(A):
    """whether A's eigenvectors are a well-conditioned basis (else f(A) by them is inaccurate)"""
    if np.array_equal(A, np.conj(A.T)):
        return True
    w, V = np.linalg._eig(A)
    V = np.asarray(V).astype(np.complex128)
    with np.errstate(all="ignore"):
        Vi = _inv(V)
    c = _norm1(V) * _norm1(Vi)
    return np.isfinite(c) and c < 1e8


def _sqrtm_triu(T):
    """the principal square root of an upper triangular T (the recurrence of Schur's method)"""
    n = T.shape[0]
    R = np.zeros((n, n), dtype=np.complex128)
    for i in range(n):
        R[i, i] = np.sqrt(complex(T[i, i]))
    for d in range(1, n):
        for i in range(n - d):
            j = i + d
            s_ = T[i, j] - np.dot(R[i, i + 1:j], R[i + 1:j, j])
            den = R[i, i] + R[j, j]
            R[i, j] = s_ / den if den != 0 else (0.0 if s_ == 0 else np.inf)
    return R


def _sqrtm_db(A):
    """the principal square root by the Denman-Beavers iteration (any A without eigenvalues on the closed negative axis)"""
    n = A.shape[0]
    Y = np.array(A, dtype=np.complex128)
    Z = np.eye(n, dtype=np.complex128)
    for _ in range(100):
        Yi, Zi = _inv(Y), _inv(Z)
        Y2 = (Y + Zi) / 2
        Z = (Z + Yi) / 2
        done = _norm1(Y2 - Y) <= 1e-15 * _norm1(Y2)
        Y = Y2
        if done:
            break
    return Y


def _sqrtm(A):
    if np.allclose(A, np.triu(A), rtol=0, atol=0):
        return _sqrtm_triu(A)
    if _well_diagonalizable(A):
        return None
    return _sqrtm_db(A)


def _real_if(F, cplx, n):
    F = np.asarray(F)
    if not np.any(np.imag(F)):
        return np.real(F)
    if not cplx and np.max(np.abs(np.imag(F))) <= 10 * n * 2.220446049250313e-16 * max(1.0, float(np.max(np.abs(F)))):
        return np.real(F)
    return F


@_bs("sqrtm")
def sqrtm_(x):
    A = _mat(x)
    _square(A, "sqrtm")
    if A.shape[0]:
        R = _sqrtm(A)
        if R is not None:
            return _box(np.array(_real_if(R, A.dtype.kind == "c", A.shape[0]).T))
    return _fun_of_matrix(x, np.sqrt, "sqrtm")


@_bs("logm")
def logm_(x):
    """log(A): by eigenvectors when they are a good basis, else by inverse
    scaling and squaring (square roots until near I, then log(I + E)'s series)"""
    A = _mat(x)
    _square(A, "logm")
    n = A.shape[0]
    if n == 0 or _well_diagonalizable(A):
        return _fun_of_matrix(x, np.log, "logm")
    X = np.array(A, dtype=np.complex128)
    k = 0
    I = np.eye(n, dtype=np.complex128)
    while _norm1(X - I) > 0.25 and k < 60:
        # (numpy.linalg's eig here is real only: no eigenvectors of the complex roots)
        X = _sqrtm_triu(X) if np.allclose(X, np.triu(X), rtol=0, atol=0) else _sqrtm_db(X)
        k += 1
    E = X - I
    L = np.zeros((n, n), dtype=np.complex128)
    P = I.copy()
    for j in range(1, 60):
        P = P @ E
        term = P / j * (1 if j % 2 else -1)
        L = L + term
        if _norm1(term) <= 1e-17 * max(_norm1(L), 1e-300):
            break
    L = L * (2.0 ** k)
    return _box(np.array(_real_if(L, A.dtype.kind == "c", n).T))


def _expm(M):
    return _mat(_m.expm_(_unmat(np.array(M, dtype=np.complex128))))


def _by_expm(name, A):
    """the functions with a closed form in exp(A) and exp(+-iA)"""
    if name == "exp":
        return _expm(A)
    if name in ("cos", "sin"):
        P, Q = _expm(1j * A), _expm(-1j * A)
        return (P + Q) / 2 if name == "cos" else (P - Q) / 2j
    P, Q = _expm(A), _expm(-A)
    return (P + Q) / 2 if name == "cosh" else (P - Q) / 2


@_bs("funm")
def funm_(x, f):
    """f(A): by A's eigenvectors when they are a well-conditioned basis.  Else
    (a defective or nearly defective A, whose f(A) needs f's derivatives) only
    for the functions with a matrix algorithm of their own, as named handles:
    exp, cos, sin, cosh, sinh (by expm), log (logm) and sqrt (sqrtm)"""
    A = _mat(x)
    _square(A, "funm")
    if A.shape[0] == 0 or _well_diagonalizable(A):
        def g(w):
            r = _m._call(f, [_box(np.array(w.reshape((1, -1))))])
            return _arr(r).reshape(-1).astype(np.complex128)
        return _fun_of_matrix(x, g, "funm")
    name = None
    if type(f) is _m.Handle:
        # (the function the handle calls, resolved as a call resolves it: a
        # local function named exp is not the built-in exp)
        if f.target is None:
            f.target = _m.fn(f.name)
        if f.target is _m._B.get(f.name):
            name = f.name
    if name in ("exp", "cos", "sin", "cosh", "sinh"):
        F = _by_expm(name, A)
        if A.dtype.kind != "c":
            F = np.real(F)  # (f real on the real line, so f(A) is real)
        return _box(np.array(np.asarray(F).T))
    if name == "log":
        return logm_(x)
    if name == "sqrt":
        return sqrtm_(x)
    raise _err("funm: this matrix is defective or nearly so (its eigenvectors are an ill-conditioned basis), "
               "and Sagebrush has no Schur-Parlett method for it: only the built-in @exp, @cos, @sin, @cosh, @sinh, @log and @sqrt are supported here.")


@_bs("orth")
def orth_(x):
    """an orthonormal basis of the range: the left singular vectors of the nonzero singular values"""
    A = _mat(x)
    if A.size == 0:
        return _unmat(np.zeros((A.shape[0], 0)))
    U, s, _ = np.linalg.svd(A, full_matrices=False)
    tol = max(A.shape) * float(s[0]) * 2.220446049250313e-16 if s.size else 0.0
    r = int(np.sum(s > tol))
    return _unmat(U[:, :r])


@_bs("rcond")
def rcond_(x):
    """the 1-norm reciprocal condition number, estimated (Higham's estimator,
    as _matlab._rcond_estimate): MATLAB documents rcond as an estimate"""
    A = _mat(x)
    _square(A, "rcond")
    n = A.shape[0]
    if n == 0:
        return _math.inf
    if not np.all(np.isfinite(A)):
        return _math.nan
    return _m._rcond_estimate(A)


_LINSOLVE_OPTS = ("LT", "UT", "UHESS", "SYM", "POSDEF", "RECT", "TRANSA")


@_bs("linsolve")
def linsolve_(a, b, opts=None):
    """A \\ B, or with opts: TRANSA solves A' X = B; LT and UT use only the
    lower or upper triangle (as LAPACK's triangular solve, which reads no
    other part); RECT, and UHESS, SYM and POSDEF when A has that property
    (they choose an algorithm, not the equation)"""
    if type(a) is _m.Sparse or type(b) is _m.Sparse:
        raise _err("Sparse inputs are not supported.", "MATLAB:linsolve:SparseInput")
    if opts is None:
        return _m.mldivide(a, b)
    if type(opts) is not _m.Struct:
        raise _err("Third argument must be a struct.", "MATLAB:linsolve:opts")
    d = opts.a[0] if opts.a else {}
    flags = {}
    for k in d:
        if k not in _LINSOLVE_OPTS:
            raise _err("Invalid field name '%s' in options structure." % k, "MATLAB:linsolve:InvalidFieldName")
        flags[k] = bool(_scalar(d[k]))
    A = _mat(a)
    if flags.get("LT") and flags.get("UT"):
        raise _err("Invalid option combination: LT and UT cannot both be true.", "MATLAB:linsolve:CombinationOfFieldsNotCurrentlySupported")
    if (flags.get("LT") or flags.get("UT") or flags.get("UHESS") or flags.get("SYM") or flags.get("POSDEF")) and A.shape[0] != A.shape[1]:
        raise _err("Matrix must be square for the options given.", "MATLAB:linsolve:SquareMatrixRequired")
    if flags.get("LT"):
        A = np.tril(A)
    elif flags.get("UT"):
        A = np.triu(A)
    else:
        for k, ok in (("UHESS", lambda M: np.array_equal(M, np.triu(M, -1))),
                      ("SYM", lambda M: np.array_equal(M, np.conj(M.T))),
                      ("POSDEF", lambda M: np.array_equal(M, np.conj(M.T)))):
            if flags.get(k) and not ok(A):
                raise _err("linsolve: the matrix is not %s, which Sagebrush's linsolve does not assume." %
                           {"UHESS": "upper Hessenberg", "SYM": "symmetric (Hermitian)", "POSDEF": "Hermitian"}[k],
                           "MATLAB:linsolve:unsupported")
    if flags.get("TRANSA"):
        A = np.conj(A.T)
    return _m.mldivide(_unmat(A), b)


# ------------------------------------------------------------------ polynomials

def _poly_row(p):
    a = _arr(p).reshape(-1)
    return a.astype(np.complex128) if a.dtype.kind == "c" else a.astype(np.float64)


def _trim(c):
    """leading zeros dropped (one element kept)"""
    k = 0
    while k < c.size - 1 and c[k] == 0:
        k += 1
    return c[k:]


def _row_value(c):
    return _box(np.array(c.reshape((-1, 1))))


def _deriv(c):
    n = c.size
    if n <= 1:
        return np.zeros(1, dtype=c.dtype)
    return c[:-1] * np.arange(n - 1, 0, -1)


@_bi("polyder")
def polyder_(nargout, a, b=None):
    """polyder(p); polyder(a, b): the derivative of a*b; [q, d] = polyder(b, a): of b/a"""
    A = _poly_row(a)
    if b is None:
        return _row_value(_trim(_deriv(A)))
    B = _poly_row(b)
    if nargout < 2:
        # (the product a*b: a' b + a b')
        return _row_value(_trim(_add_poly(np.convolve(_deriv(A), B), np.convolve(A, _deriv(B)))))
    # (the quotient a/b: (a' b - a b') / b^2)
    num = _add_poly(np.convolve(_deriv(A), B), -np.convolve(A, _deriv(B)))
    den = np.convolve(B, B)
    return [_row_value(_trim(num)), _row_value(_trim(den))]


def _add_poly(p, q):
    n = max(p.size, q.size)
    r = np.zeros(n, dtype=np.result_type(p.dtype, q.dtype))
    r[n - p.size:] += p
    r[n - q.size:] += q
    return r


@_bs("polyint")
def polyint_(p, k=0.0):
    c = _poly_row(p)
    n = c.size
    r = np.zeros(n + 1, dtype=c.dtype)
    r[:n] = c / np.arange(n, 0, -1)
    r[n] = _scalar(k) if not (isinstance(k, complex)) else k
    return _row_value(r)


@_bs("polyvalm")
def polyvalm_(p, X):
    c = _poly_row(p)
    M = _mat(X)
    if M.ndim != 2 or M.shape[0] != M.shape[1]:
        raise _err("Input X must be a square matrix.")
    n = M.shape[0]
    Y = np.zeros((n, n), dtype=np.result_type(c.dtype, M.dtype))
    for a in c:
        Y = Y @ M + a * np.eye(n)
    return _unmat(Y)


# ------------------------------------------------------------------ piecewise polynomials

def _pp(breaks, coefs, pieces, order, dim):
    return _m._struct1({"form": Char("pp"), "breaks": _box(np.array(np.asarray(breaks, dtype=np.float64).reshape((-1, 1)))),
                        "coefs": _unmat(np.asarray(coefs)), "pieces": float(pieces), "order": float(order), "dim": float(dim)})


def _pp_parts(pp):
    if type(pp) is not _m.Struct or "coefs" not in pp.fields:
        raise _err("Input must be a piecewise polynomial structure.")
    d = pp.a[0]
    br = _arr(d["breaks"]).reshape(-1).astype(np.float64)
    C = _mat(d["coefs"])
    dim = int(_scalar(d["dim"])) if "dim" in d else 1
    return br, C, dim


def _ppval(br, C, dim, xs):
    """values at xs (a flat array): each piece's polynomial in x - breaks(i),
    the end pieces extended beyond the breaks; one row per dimension"""
    pieces = br.size - 1
    k = np.searchsorted(br[1:-1], xs, side="right") if pieces > 1 else np.zeros(xs.size, dtype=np.int64)
    t = xs - br[k]
    out = np.zeros((dim, xs.size), dtype=C.dtype)
    for di in range(dim):
        rows = C[k * dim + di]
        v = np.zeros(xs.size, dtype=C.dtype)
        for j in range(C.shape[1]):
            v = v * t + rows[:, j]
        out[di] = v
    out[:, np.isnan(xs)] = np.nan
    return out


def _cubic_coefs(x, y, d):
    """the Hermite cubic of each piece, in x - x(k): [c3 c2 c1 c0]"""
    h = np.diff(x)
    y = np.asarray(y)
    d = np.asarray(d)
    delta = np.diff(y) / h
    c3 = (d[:-1] + d[1:] - 2 * delta) / (h * h)
    c2 = (3 * delta - 2 * d[:-1] - d[1:]) / h
    return np.stack([c3, c2, d[:-1], y[:-1]], axis=1)


def _xy_data(x, y):
    X = _arr(x).reshape(-1).astype(np.float64)
    Y = _mat(y)
    vec = Y.shape[0] == 1 or Y.shape[1] == 1
    if vec:
        Y = Y.reshape((1, -1))
    if np.any(np.diff(X) <= 0):
        order = np.argsort(X, kind="stable")
        X = X[order]
        if Y.shape[1] == X.size:
            Y = Y[:, order]
        if np.any(np.diff(X) == 0):
            raise _err("The data sites should be distinct.")
    return X, Y, vec


# (the most data sites times rows of values spline and pchip set up slopes for, one site at a
# time, and the most n^3 times solves, for n sites, of the spline's dense systems: made only
# when an entry of its tridiagonal system is not finite, or a clamped spline's values are
# complex; otherwise it is solved in its band, _tridiag_solve)
_CUBIC_SETUP_MAX = 1_000_000
# (and for a spline, whose setup and banded solve are slower: 1,000,000 sites took about 40 s
# and 0.9 GB, 200,000 about 7 s)
_SPLINE_SETUP_MAX = 200_000
_SPLINE_SOLVE_WORK = 1_000_000_000


def _tridiag_solve(sub, diag, sup, r):
    """the solution, as a list, of the tridiagonal system whose row k has sub[k], diag[k] and
    sup[k] at columns k - 1, k and k + 1 (sub[0] and sup[-1] unused), right-hand side r: the
    elimination numpy.linalg.solve does on the dense matrix (partial pivoting, the first
    largest pivot, a zero multiplier skipping its row, then the two substitutions), with
    the same operations in the same order on the entries that are not zero, so the same
    values, in time and memory linear in n"""
    n = len(diag)
    # (the rows of U, at columns k, k + 1 and k + 2: a row swapped up brings one more)
    U0, U1, U2 = [0.0] * n, [0.0] * n, [0.0] * n
    z = [0.0] * n
    # (row k as reduced so far, and its right-hand side)
    c0, c1, c2, rk = diag[0], sup[0] if n > 1 else 0.0, 0.0, r[0]
    singular = False
    for k in range(n):
        if k + 1 < n:
            l, d, u, rn = sub[k + 1], diag[k + 1], sup[k + 1] if k + 2 < n else 0.0, r[k + 1]
            if abs(l) > abs(c0):
                c0, c1, c2, rk, l, d, u, rn = l, d, u, rn, c0, c1, c2, rk
        U0[k], U1[k], U2[k], z[k] = c0, c1, c2, rk
        if c0 == 0:
            singular = True
        elif k + 1 < n:
            f = l / c0
            if f != 0:
                d -= f * c1
                u -= f * c2
                rn -= f * rk
        if k + 1 < n:
            c0, c1, c2, rk = d, u, 0.0, rn
    if singular:
        raise np.linalg.LinAlgError("Singular matrix")
    for k in range(n - 1, -1, -1):
        z[k] /= U0[k]
        if k >= 2 and U2[k - 2] != 0:
            z[k - 2] -= U2[k - 2] * z[k]
        if k >= 1 and U1[k - 1] != 0:
            z[k - 1] -= U1[k - 1] * z[k]
    return z


def _cubic_admit(name, n, dim, setups, solves):
    """refuse, before any slopes are set up, a spline or pchip whose setup (setups rows of n
    sites) or dense solves (solves systems of n unknowns) would be too much work"""
    rows = "%d row%s of values" % (dim, "s" * (dim != 1))
    if n * setups > (_SPLINE_SETUP_MAX if name == "spline" else _CUBIC_SETUP_MAX):
        raise _err("%s with %d data sites for %s is not supported in Sagebrush: too much work." % (name, n, rows))
    if solves and n ** 3 * solves > _SPLINE_SOLVE_WORK:
        raise _err("%s with %d data sites for %s is not supported in Sagebrush: its dense solve would be "
                   "too much work." % (name, n, rows))


def _spline_pp(x, y):
    """spline: the not-a-knot cubic spline, or clamped when y has two values
    more than x (the end slopes), as MATLAB documents; with 2 or 3 points,
    as it also documents, linear or quadratic interpolation, each one
    polynomial piece over [x(1), x(end)] (the form Octave's spline gives)"""
    X, Y, vec = _xy_data(x, y)
    n = X.size
    dim = Y.shape[0]
    clamped = Y.shape[1] == n + 2
    if not clamped and Y.shape[1] != n:
        raise _err("The number of sites, %d, is incompatible with the number of values, %d." % (n, Y.shape[1]))
    # (a clamped spline solves once per row, complex or not; a not-a-knot one of more than three
    # sites once per real row, a complex row being two)
    parts = dim * (2 if np.iscomplexobj(Y) else 1)
    _cubic_admit("spline", n, dim, parts, 0)
    # (the dense solve only when the banded one can't be used: its work, admitted then)
    dense = lambda: _cubic_admit("spline", n, dim, 0, dim if clamped else parts)
    rows = []
    order = 4
    for di in range(dim):
        yv = Y[di]
        if clamped:
            s0, s1, yv = yv[0], yv[-1], yv[1:-1]
            d = _clamped_slopes(X, yv, s0, s1, dense)
            rows.append(_cubic_coefs(X, yv, d))
        elif n == 2:
            order = 2
            rows.append(np.array([[(yv[1] - yv[0]) / (X[1] - X[0]), yv[0]]]))
        elif n == 3:
            # (the parabola through the three points by Newton's divided
            # differences, in powers of x - x(1): f123 t^2 + (f12 - f123 (x2 - x1)) t + y1)
            order = 3
            f12 = (yv[1] - yv[0]) / (X[1] - X[0])
            f23 = (yv[2] - yv[1]) / (X[2] - X[1])
            f123 = (f23 - f12) / (X[2] - X[0])
            rows.append(np.array([[f123, f12 - f123 * (X[1] - X[0]), yv[0]]]))
        else:
            d = _m._spline_slopes(list(X), [float(t) for t in yv], dense) if not np.iscomplexobj(yv) else \
                [complex(a, b) for a, b in zip(_m._spline_slopes(list(X), [float(t) for t in yv.real], dense), _m._spline_slopes(list(X), [float(t) for t in yv.imag], dense))]
            rows.append(_cubic_coefs(X, yv, np.array(d)))
    pieces = rows[0].shape[0]
    C = np.zeros((pieces * dim, rows[0].shape[1]), dtype=np.result_type(*[r.dtype for r in rows]))
    for di in range(dim):
        C[di::dim] = rows[di]
    if n == 3 and not clamped:
        X = np.array([X[0], X[-1]])
    return X, C, dim, vec


def _clamped_slopes(X, y, s0, s1, dense=None):
    n = X.size
    h = np.diff(X)
    delta = np.diff(y) / h
    r = np.zeros(n, dtype=np.result_type(y.dtype, np.float64))
    r[0] = s0
    r[n - 1] = s1
    sub, diag, sup = [0.0] * n, [1.0] * n, [0.0] * n
    for k in range(1, n - 1):
        sub[k] = float(h[k])
        diag[k] = float(2 * (h[k - 1] + h[k]))
        sup[k] = float(h[k - 1])
        r[k] = 3 * (h[k] * delta[k - 1] + h[k - 1] * delta[k])
    # (the banded solve, unless an entry is not finite or r is complex: then the dense one,
    # whose results for those are kept)
    if r.dtype.kind != "c" and all(_math.isfinite(v) for band in (sub, diag, sup) for v in band):
        return np.array(_tridiag_solve(sub, diag, sup, [float(v) for v in r]))
    if dense is not None:
        dense()
    A = np.zeros((n, n))
    A[0, 0] = 1.0
    A[n - 1, n - 1] = 1.0
    for k in range(1, n - 1):
        A[k, k - 1], A[k, k], A[k, k + 1] = sub[k], diag[k], sup[k]
    return np.linalg.solve(A, r)


def _pchip_pp(x, y):
    X, Y, vec = _xy_data(x, y)
    if Y.shape[1] != X.size:
        raise _err("The number of sites, %d, is incompatible with the number of values, %d." % (X.size, Y.shape[1]))
    dim = Y.shape[0]
    _cubic_admit("pchip", X.size, dim, dim * (2 if np.iscomplexobj(Y) else 1), 0)

    def slopes(yv):
        # (complex values: the real and imaginary parts' own pchip slopes)
        if np.iscomplexobj(yv):
            return np.array(slopes(yv.real)) + 1j * np.array(slopes(yv.imag))
        return np.array(_m._pchip_slopes(list(X), [float(t) for t in yv]))
    rows = [_cubic_coefs(X, Y[di], slopes(Y[di])) for di in range(dim)]
    pieces = rows[0].shape[0]
    C = np.zeros((pieces * dim, 4), dtype=np.result_type(*[r.dtype for r in rows]))
    for di in range(dim):
        C[di::dim] = rows[di]
    return X, C, dim, vec


def _pp_or_values(builder, x, y, xq):
    X, C, dim, vec = builder(x, y)
    if xq is None:
        return _pp(X, C, X.size - 1, C.shape[1], dim)
    Q = _arr(xq).astype(np.float64)
    vals = _ppval(X, C, dim, Q.reshape(-1))
    if dim == 1:
        return _box(np.array(vals.reshape(Q.shape)))
    # (a value per dimension and query: dim-by-size(xq))
    qd = list(_m._dims(xq))
    if len(qd) == 2 and qd[0] == 1:
        qd = [qd[1]]
    out = vals.reshape([dim] + [int(v) for v in qd])
    return _box(np.array(np.moveaxis(out, 0, -1).reshape(tuple(reversed([dim] + [int(v) for v in qd])))))


@_bs("spline")
def spline_(x, y, xq=None):
    return _pp_or_values(_spline_pp, x, y, xq)


@_bs("pchip")
def pchip_(x, y, xq=None):
    return _pp_or_values(_pchip_pp, x, y, xq)


@_bs("ppval")
def ppval_(pp, xx):
    br, C, dim = _pp_parts(pp)
    Q = _arr(xx).astype(np.float64)
    vals = _ppval(br, C, dim, Q.reshape(-1))
    if dim == 1:
        return _box(np.array(vals.reshape(Q.shape)))
    return _unmat(vals) if Q.size else _unmat(np.zeros((dim, 0)))


@_bs("mkpp")
def mkpp_(breaks, coefs, d=1.0):
    br = _arr(breaks).reshape(-1).astype(np.float64)
    dim = _m._int_arg(d, "dimension")
    C = _mat(coefs)
    pieces = br.size - 1
    if C.size % (pieces * dim):
        raise _err("The number of coefficients does not match the number of pieces and the dimension.")
    order = C.size // (pieces * dim)
    C = C.reshape((pieces * dim, order)) if C.shape != (pieces * dim, order) else C
    return _pp(br, C, pieces, order, dim)


@_bi("unmkpp")
def unmkpp_(nargout, pp):
    br, C, dim = _pp_parts(pp)
    out = [_box(np.array(br.reshape((-1, 1)))), _unmat(C), float(br.size - 1), float(C.shape[1]), float(dim)]
    return out[0] if nargout <= 1 else out[:nargout]


# ------------------------------------------------------------------ interp2

@_bs("interp2")
def interp2_(*args):
    """interp2(X, Y, V, Xq, Yq[, method[, extrapval]]), interp2(V, Xq, Yq), interp2(V[, k]):
    linear (the default), nearest, cubic (Keys's cubic convolution, on a
    uniform grid) or spline (a tensor-product not-a-knot spline, which
    extrapolates unless given extrapval); the grid increasing or decreasing"""
    args = list(args)
    method, extrap = "linear", None
    if args and not _istext(args[-1]) and len(args) >= 2 and _istext(args[-2]):
        extrap = _scalar(args.pop())
    if args and _istext(args[-1]):
        method = _text(args.pop()).lower().lstrip("*")
    if method not in ("linear", "nearest", "cubic", "spline"):
        raise _err("Invalid interpolation method." if method not in ("makima", "pchip") else
                   "interp2: the '%s' method is not supported in Sagebrush." % method)
    if len(args) in (1, 2):
        V = _mat(args[0])
        k = _m._int_arg(args[1]) if len(args) == 2 else 1
        m, n = V.shape
        x = np.arange(1.0, n + 1)
        y = np.arange(1.0, m + 1)
        step = 2.0 ** -k
        Xq, Yq = np.meshgrid(np.arange(1.0, n + step / 2, step), np.arange(1.0, m + step / 2, step))
    elif len(args) == 3:
        V = _mat(args[0])
        m, n = V.shape
        x, y = np.arange(1.0, n + 1), np.arange(1.0, m + 1)
        Xq, Yq = _mat(args[1]), _mat(args[2])
    else:
        Xa, Ya, V, Xq, Yq = _mat(args[0]), _mat(args[1]), _mat(args[2]), _mat(args[3]), _mat(args[4])
        x = Xa[0, :] if Xa.ndim == 2 and Xa.shape[0] > 1 and Xa.shape == V.shape else Xa.reshape(-1)
        y = Ya[:, 0] if Ya.ndim == 2 and Ya.shape[1] > 1 and Ya.shape == V.shape else Ya.reshape(-1)
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    if V.shape != (y.size, x.size):
        raise _err("The lengths of X and Y must match the size of V.")
    # (a decreasing grid: the same data, increasing)
    for axis, g in ((1, x), (0, y)):
        dg = np.diff(g)
        if dg.size and not np.all(dg > 0):
            if not np.all(dg < 0):
                raise _err("The grid vectors must be strictly monotonic.", "MATLAB:griddedInterpolant:NonMonotonicCompVecsErrId")
            V = V[:, ::-1] if axis == 1 else V[::-1, :]
            if axis == 1:
                x = x[::-1]
            else:
                y = y[::-1]
    # (a vector of x queries and one of y queries, of different orientations: their grid)
    if Xq.shape[0] == 1 and Yq.shape[1] == 1 and Xq.size > 1 and Yq.size > 1:
        Xq, Yq = np.meshgrid(Xq.reshape(-1), Yq.reshape(-1))
    shape = Xq.shape
    xq, yq = Xq.reshape(-1).astype(np.float64), Yq.reshape(-1).astype(np.float64)
    out = np.full(xq.size, np.nan, dtype=V.dtype if V.dtype.kind == "c" else np.float64)
    inside = (xq >= x[0]) & (xq <= x[-1]) & (yq >= y[0]) & (yq <= y[-1])
    if method == "spline" and extrap is None:
        # (the spline's own extrapolation, where the query is a number)
        inside = ~(np.isnan(xq) | np.isnan(yq))
    if method == "cubic":
        out[inside] = _cubic_conv2(x, y, V, xq[inside], yq[inside])
    elif method == "spline":
        # (along x for each row, then along y)
        res = np.zeros(xq.size, dtype=out.dtype)
        rowsplines = [_spline_pp(_box(np.array(x.reshape((-1, 1)))), _box(np.array(V[i].reshape((-1, 1)))))[:2] for i in range(y.size)]
        for q in range(xq.size):
            col = np.array([_ppval(br, C, 1, np.array([xq[q]]))[0, 0] for br, C in rowsplines])
            br, C, _, _ = _spline_pp(_box(np.array(y.reshape((-1, 1)))), _box(np.array(col.reshape((-1, 1)))))
            res[q] = _ppval(br, C, 1, np.array([yq[q]]))[0, 0]
        out[inside] = res[inside]
    else:
        i = np.clip(np.searchsorted(x, xq, side="right") - 1, 0, max(x.size - 2, 0))
        j = np.clip(np.searchsorted(y, yq, side="right") - 1, 0, max(y.size - 2, 0))
        if method == "nearest":
            ii = np.where((x.size > 1) & (xq - x[i] >= x[np.minimum(i + 1, x.size - 1)] - xq), np.minimum(i + 1, x.size - 1), i)
            jj = np.where((y.size > 1) & (yq - y[j] >= y[np.minimum(j + 1, y.size - 1)] - yq), np.minimum(j + 1, y.size - 1), j)
            res = V[jj, ii]
        else:
            i1, j1 = np.minimum(i + 1, x.size - 1), np.minimum(j + 1, y.size - 1)
            with np.errstate(invalid="ignore", divide="ignore"):
                tx = np.where(i1 > i, (xq - x[i]) / (x[i1] - x[i]), 0.0)
                ty = np.where(j1 > j, (yq - y[j]) / (y[j1] - y[j]), 0.0)
            res = (V[j, i] * (1 - tx) * (1 - ty) + V[j, i1] * tx * (1 - ty) + V[j1, i] * (1 - tx) * ty + V[j1, i1] * tx * ty)
        out[inside] = res[inside]
    out[~inside] = _math.nan if extrap is None else extrap
    return _unmat(out.reshape(shape))


def _keys(t):
    """Keys's cubic convolution kernel (a = -1/2)"""
    t = np.abs(t)
    return np.where(t <= 1, (1.5 * t - 2.5) * t * t + 1,
                    np.where(t < 2, ((-0.5 * t + 2.5) * t - 4) * t + 2, 0.0))


def _keys_extend(V, axis):
    """V with a point more at each end of an axis, by Keys's boundary
    condition (the cubic through the end values): 3 f0 - 3 f1 + f2"""
    M = np.moveaxis(V, axis, 0)
    lo = 3 * M[0] - 3 * M[1] + M[2]
    hi = 3 * M[-1] - 3 * M[-2] + M[-3]
    return np.moveaxis(np.concatenate([lo[None], M, hi[None]], axis=0), 0, axis)


def _uniform_step(g, what):
    if g.size < 3:
        raise _err("interp2: the 'cubic' method needs at least 3 grid points in each dimension.")
    h = (g[-1] - g[0]) / (g.size - 1)
    # (relative to the step, with a few units in the last place of the
    # coordinates for their rounding: the same answer wherever the grid is)
    tol = 64 * 2.220446049250313e-16 * abs(h) + 4 * 2.220446049250313e-16 * max(abs(g[0]), abs(g[-1]))
    if np.max(np.abs(np.diff(g) - h)) > tol:
        raise _err("interp2: the 'cubic' method needs uniformly spaced %s grid points (Sagebrush has no other cubic)." % what)
    return h


def _cubic_conv2(x, y, V, xq, yq):
    """bicubic convolution: at each query, the 4-by-4 neighbours, each
    weighted by the kernel along x times along y"""
    hx, hy = _uniform_step(x, "x"), _uniform_step(y, "y")
    E = _keys_extend(_keys_extend(V, 1), 0)
    u, w = (xq - x[0]) / hx, (yq - y[0]) / hy
    i = np.clip(np.floor(u).astype(np.int64), 0, x.size - 2)
    j = np.clip(np.floor(w).astype(np.int64), 0, y.size - 2)
    tu, tw = u - i, w - j
    res = np.zeros(xq.size, dtype=E.dtype)
    for a in range(-1, 3):
        wy = _keys(tw - a)
        for b in range(-1, 3):
            res = res + E[j + a + 1, i + b + 1] * (wy * _keys(tu - b))
    return res


# ------------------------------------------------------------------ numgrid, delsq

@_bs("numgrid")
def numgrid_(region, n):
    """numgrid(R, n): the points of an n-by-n grid over -1 <= x <= 1,
    -1 <= y <= 1 that lie in the region R, numbered 1, 2, ... down the
    columns, 0 elsewhere (the boundary is always 0), as MATLAB's
    documentation describes it.  'S' is the whole square; 'L' the L-shaped
    domain, the square without one quarter: with x_i = -1 + 2(i-1)/(n-1),
    the points with x_row >= 0 and x_col <= 0 are left out, which gives the
    published numgrid('L',10) and the published counts 675 (n = 32), 75
    (n = 12) and 2945 (n = 65).  The other regions the documentation names
    ('C', 'D', 'A', 'H', 'B', 'N') are only described in words, which do not
    fix their shapes on the grid, so Sagebrush refuses them"""
    if not _istext(region) or len(_text(region)) != 1:
        raise _err("numgrid: the region must be one character.")
    r = _text(region)
    if r not in ("S", "L"):
        if r in ("C", "D", "A", "H", "B", "N"):
            raise _err("numgrid: the region '%s' is not supported in Sagebrush (only 'S' and 'L')." % r)
        raise _err("numgrid: unknown region '%s'." % r)
    if type(n) is Char or not _m._isnumlike(n) or _m._numel(n) != 1:
        raise _err("numgrid: n must be a positive integer.")
    nn = _scalar(n)
    if nn != _math.floor(nn) or nn < 1:
        raise _err("numgrid: n must be a positive integer.")
    nn = int(nn)
    x = np.array([-1.0 + 2.0 * i / (nn - 1) for i in range(nn)]) if nn > 1 else np.array([0.0])
    inside = np.zeros((nn, nn), dtype=bool)
    inside[1:nn - 1, 1:nn - 1] = True
    if r == "L":
        inside &= ~((x[:, None] >= 0) & (x[None, :] <= 0))
    G = np.zeros((nn, nn))
    k = 0
    for j in range(nn):
        for i in range(nn):
            if inside[i, j]:
                k += 1
                G[i, j] = k
    return _unmat(G)


@_bi("delsq")
def delsq_(nargout, g):
    """delsq(G): the five-point finite difference Laplacian on the grid G
    that numgrid makes, a sparse matrix as MATLAB's documentation describes
    it: for each numbered point p, 4 at (p, p) and -1 at (p, q) for each of
    its four neighbours (up, down, left, right) numbered q; the published
    nnz(delsq(numgrid('S',200))) = 195228 is this stencil's"""
    import _matlab_sparse as _sp
    if type(g) is Char or not _m._isnumlike(g):
        raise _err("delsq: the input must be a numbered grid, as numgrid makes.")
    G = _mat(g)
    if G.ndim != 2:
        raise _err("delsq: the input must be a matrix.")
    G = np.array(G, dtype=float)
    N = int(np.max(G)) if G.size else 0
    rows, cols, vals = [], [], []
    m, n = G.shape
    for i in range(m):
        for j in range(n):
            p = int(G[i, j])
            if p <= 0:
                continue
            rows.append(p - 1)
            cols.append(p - 1)
            vals.append(4.0)
            for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                a, b = i + di, j + dj
                if 0 <= a < m and 0 <= b < n and G[a, b] > 0:
                    rows.append(p - 1)
                    cols.append(int(G[a, b]) - 1)
                    vals.append(-1.0)
    return _sp.make(N, N, rows, cols, vals)

files._matlab_sparse.py:
"""MATLAB's sparse matrices, for lib/_matlab.py (see its Sparse class).

A sparse matrix is stored as MATLAB stores it, in compressed sparse column
form.  An m-by-n matrix has:
- jc: n + 1 column starts;
- ir: each nonzero's row (0-based, increasing within its column);
- pr: the nonzeros (float64, complex128 or bool).
No zero is stored.  (MATLAB's sparse matrices are double, single or
logical: pr float32 or complex64 for single.)  Values are immutable: an operation makes a new one, so a
sparse matrix is never copied.

The operations here work on that storage, so they stay fast on large
matrices: construction, queries, display, indexing, and (see below) the
arithmetic and functions that keep a matrix sparse.  Any other function sees
a sparse matrix as the full matrix it stands for (_matlab's _arr and _farr
expand it), and computes what it computes on a full one.  activate() wraps
the built-in functions for that, the first time a sparse matrix is made, so
that programs without one pay nothing.
"""

import math as _math

import numpy as np

import _matlab as _m
from _matlab import Sparse, COLON, NOVAL, _err

_I = np.int64

# the most elements a sparse matrix is expanded to as a full one (2 GB of doubles)
MAX_FULL = 1 << 28


# ------------------------------------------------------------------ storage

def _new(m, n, jc, ir, pr):
    S = Sparse.__new__(Sparse)
    S.m, S.n, S.jc, S.ir, S.pr = m, n, jc, ir, pr
    S.cap = 0
    activate()
    return S


def _cols(S):
    """each nonzero's column (0-based)"""
    return np.repeat(np.arange(S.n, dtype=_I), np.diff(S.jc))


def _keys(S):
    """each nonzero's column-major position (0-based): increasing"""
    return _cols(S) * S.m + S.ir


def _jc(cols, n):
    jc = np.zeros(n + 1, dtype=_I)
    if cols.size:
        jc[1:] = np.cumsum(np.bincount(cols, minlength=n))
    return jc


def _canon_vals(vals):
    k = vals.dtype.kind
    if k == "b":
        return vals
    single = vals.dtype.itemsize == (8 if k == "c" else 4)
    if k == "c":
        vals = vals.astype(np.complex64 if single else np.complex128)
        return np.array(vals.real) if not np.any(vals.imag) else vals
    return vals.astype(np.float32 if single else np.float64)


def make(m, n, rows, cols, vals, combine="sum"):
    """an m-by-n sparse matrix from coordinates (0-based) and values: values
    at the same place summed (or-ed when logical), or with combine="last" the
    last one kept; zeros dropped"""
    rows = np.asarray(rows, dtype=_I).reshape(-1)
    cols = np.asarray(cols, dtype=_I).reshape(-1)
    vals = _canon_vals(np.asarray(vals).reshape(-1))
    if rows.size:
        key = cols * m + rows
        order = np.argsort(key, kind="stable")
        key = key[order]
        vals = vals[order]
        if key.size > 1 and np.any(key[1:] == key[:-1]):
            if combine == "last":
                last = np.ones(key.size, dtype=bool)
                last[:-1] = key[1:] != key[:-1]
                key, vals = key[last], vals[last]
            else:
                uk, inv = np.unique(key, return_inverse=True)
                if vals.dtype.kind == "b":
                    vals = np.bincount(inv, weights=vals.astype(np.float64), minlength=uk.size) > 0
                elif vals.dtype.kind == "c":
                    vals = _m._cplx(np.bincount(inv, weights=vals.real, minlength=uk.size),
                                    np.bincount(inv, weights=vals.imag, minlength=uk.size))
                else:
                    vals = np.bincount(inv, weights=vals, minlength=uk.size)
                key = uk
        keep = vals != 0
        if not np.all(keep):
            key, vals = key[keep], vals[keep]
        rows, cols = key % m, key // m
    vals = _canon_vals(vals)
    return _new(m, n, _jc(cols, n), np.array(rows, dtype=_I), np.array(vals))


def from_full(v, name="sparse"):
    """a full numeric or logical matrix as a sparse one"""
    if type(v) is Sparse:
        return v
    cls = _m.class_(v)
    if cls not in ("double", "single", "logical") or not _m._isnumlike(v):
        raise _err("Undefined function '%s' for input arguments of type '%s'." % (name, cls), "MATLAB:UndefinedFunction")
    a = _m._arr(v)
    if a.ndim > 2:
        raise _err("N-dimensional sparse arrays are not supported.")
    n, m = a.shape
    if a.dtype.kind == "c" and not np.any(a.imag):
        a = np.array(a.real)
    nz = np.nonzero(a)  # (stored transposed: column by column, each column's rows in order)
    return _new(m, n, _jc(nz[0].astype(_I), n), nz[1].astype(_I), _canon_vals(np.array(a[nz])))


def zeros(m, n, like=None):
    """an all-zero m-by-n sparse matrix, of the class of like (a sparse matrix) or double"""
    dt = like.pr.dtype if type(like) is Sparse else np.float64
    return _new(m, n, np.zeros(n + 1, dtype=_I), np.zeros(0, dtype=_I), np.zeros(0, dtype=dt))


def nzmax(S):
    return max(S.cap, nnz(S), 1)


def isreal(v):
    if type(v) is Sparse:
        return v.pr.dtype.kind != "c"
    return _m._arr(v).dtype.kind != "c"


def nbytes(S):
    """MATLAB's storage of a sparse matrix: its column starts, and a row index and a value for each of nzmax places"""
    return (S.n + 1) * 8 + nzmax(S) * (8 + S.pr.dtype.itemsize)


def _too_big(m, n):
    gb = m * n * 8 / 2.0 ** 30
    return _err("Requested %dx%d (%.1fGB) array exceeds maximum array size preference. Creation of arrays greater "
                "than this limit may take a long time and cause MATLAB to become unresponsive." % (m, n, gb),
                "MATLAB:array:SizeLimitExceeded")


def full_arr(S):
    """the full matrix S stands for, stored as _matlab stores arrays (transposed)"""
    if S.m * S.n > MAX_FULL:
        raise _too_big(S.m, S.n)
    a = np.zeros((S.n, S.m), dtype=S.pr.dtype)
    if S.pr.size:
        a[_cols(S), S.ir] = S.pr
    return a


def full(v):
    """full(S) as a MATLAB value"""
    if type(v) is not Sparse:
        return _m.cp(v)
    return _m._box(full_arr(v))


def islogical(S):
    return S.pr.dtype.kind == "b"


def class_(S):
    return _m._dtclass(S.pr.dtype)


def nnz(S):
    return int(S.pr.size)


def transpose(S, conj=False):
    if not S.pr.size:
        return zeros(S.n, S.m, S)
    vals = S.pr
    if conj and vals.dtype.kind == "c":
        # (a real element's imaginary part stays 0, not -0)
        vals = _m._cplx(vals.real, np.where(vals.imag == 0, 0.0, -vals.imag)).astype(vals.dtype)
    return make(S.n, S.m, _cols(S), S.ir, vals)


# ------------------------------------------------------------------ display

def blocks(S):
    """(header blocks, body blocks) of S's display"""
    d = (S.m, S.n)
    nz = nnz(S)
    kind = class_(S) if S.pr.dtype.kind != "c" else "complex " + class_(S)
    if S.m * S.n == 0:
        return ["  %s empty sparse %s %s" % (_m._dimstr(d), kind, "array" if kind == "logical" else "matrix")], []
    if S.m == 1 and S.n == 1:
        what = "sparse %s scalar" % kind
    else:
        word = _m._shape_word(d)
        what = "%s sparse %s %s" % (_m._dimstr(d), kind, "array" if kind == "logical" and word == "matrix" else word)
    if nz == 0:
        return ["  " + what], ["   All zero"]
    head = ["  " + what if S.m == S.n == 1 else "  %s (%d nonzero%s)" % (what, nz, "" if nz == 1 else "s")]
    # (each value as a full matrix of the nonzeros would show it, after its
    # (row,col): the commas in a column, the indices in fields K wide as a
    # full matrix's integers are (less one), each value ending K + W past the
    # comma, W the width of the full matrix's columns)
    rows = S.ir + 1
    cols = _cols(S) + 1
    K = 5 if max(int(np.max(rows)), int(np.max(cols))) < 1000 else 11
    vals = S.pr
    body = []
    if vals.dtype.kind == "b":
        texts, w = ["1"] * nz, 4
    elif vals.dtype.kind == "c":
        f, scale = _m._fmt_complex_parts(vals.reshape((-1, 1)), nz == 1)
        parts = [(f(z.real + 0.0), "-" if z.imag < 0 else "+", f(abs(z.imag)) if z.imag == z.imag else "NaN")
                 for z in (complex(x) for x in vals)]
        wr = max(9 if _m._format["num"] != "long" else 19, max(len(p[0]) for p in parts) + 2)
        wi = max(max(len(p[2]) for p in parts), len(f(1.0)) + 1)
        texts = ["%s %s%si" % (p[0].rjust(wr), p[1], p[2].rjust(wi)) for p in parts]
        w = wr + wi + 3 - (_m._format["num"] == "long")
        if scale:
            body.append(("%s *" % scale).rjust(12))
    else:
        nf = _m._NumFmt(vals.reshape((-1, 1)), nz == 1, _m._format["num"] == "long")
        texts = [nf.fmt(float(x)) for x in vals]
        w = nf.width
        longest = max(len(t) for t in texts)
        if longest + 2 > w:
            w = longest + 3 if nf.kind == "int" else longest + 2
        if nf.scale is not None:
            body.append(("%s *" % nf.scale_text).rjust(12))
    lines = []
    for k in range(nz):
        r = str(int(rows[k]))
        c = str(int(cols[k]))
        t = texts[k]
        lines.append("%s(%s,%s)%s" % (" " * max(0, K - 1 - len(r)), r, c, t.rjust(max(K + w - len(c) - 1, len(t) + 1))))
    body.append("\n".join(lines))
    return head, body


# ------------------------------------------------------------------ indexing

def _vec_out(dims, idims, count):
    """the dimensions of v(k) for a linear index k (as _matlab's _positions)"""
    src_vec = dims[0] == 1 or dims[1] == 1
    ivec = len(idims) == 2 and (idims[0] == 1 or idims[1] == 1)
    if src_vec and ivec and not (dims[0] == 1 and dims[1] == 1):
        return (1, count) if dims[0] == 1 else (count, 1)
    return tuple(idims)


def index_arg(a):
    """an index that is itself sparse, as the full value it stands for"""
    return full(a) if type(a) is Sparse else a


def index(S, args):
    """S(args): always sparse, as MATLAB's (S(2,2) too)"""
    args = [index_arg(a) for a in args]
    if not args:
        return S
    if len(args) == 1:
        a = args[0]
        total = S.m * S.n
        if a is COLON:
            return reshape(S, total, 1)
        idx, idims, _ = _m._ivec(a, total, -1, False)
        out = _vec_out((S.m, S.n), idims, idx.size)
        if len(out) > 2:
            raise _err("N-dimensional sparse arrays are not supported.")
        key = _keys(S)
        p = np.searchsorted(key, idx)
        pc = np.minimum(p, max(key.size - 1, 0))
        found = (p < key.size) & (key[pc] == idx) if key.size else np.zeros(idx.size, dtype=bool)
        k = np.nonzero(found)[0].astype(_I)
        r0 = out[0]
        return make(out[0], out[1], k % r0 if r0 else k, k // r0 if r0 else k, S.pr[pc[found]])
    for k in range(2, len(args)):
        idx, _, _ = _m._ivec(args[k], 1, k, False)
    I = _m._ivec(args[0], S.m, 0, False)[0] if args[0] is not COLON else None
    J = _m._ivec(args[1], S.n, 1, False)[0]
    return _submatrix(S, I, J)


def _gather(S, J):
    """the nonzeros of the columns J, in order: (their indices in ir/pr, their column's place in J)"""
    starts = S.jc[J]
    counts = S.jc[J + 1] - starts
    total = int(np.sum(counts)) if counts.size else 0
    if total == 0:
        return np.zeros(0, dtype=_I), np.zeros(0, dtype=_I)
    offs = np.cumsum(counts) - counts
    e = np.arange(total, dtype=_I) - np.repeat(offs, counts) + np.repeat(starts, counts)
    return e, np.repeat(np.arange(J.size, dtype=_I), counts)


def _submatrix(S, I, J):
    """S(I, J) for 0-based index vectors (I None: every row)"""
    e, oc = _gather(S, J)
    vals = S.pr[e]
    rows = S.ir[e]
    if I is None:
        return make(S.m, J.size, rows, oc, vals)
    # each nonzero once for every place its row has in I
    order = np.argsort(I, kind="stable")
    Is = I[order]
    lo = np.searchsorted(Is, rows, side="left")
    hi = np.searchsorted(Is, rows, side="right")
    cnt = hi - lo
    tot = int(np.sum(cnt)) if cnt.size else 0
    if tot == 0:
        return zeros(I.size, J.size, S)
    offs = np.cumsum(cnt) - cnt
    place = np.arange(tot, dtype=_I) - np.repeat(offs, cnt) + np.repeat(lo, cnt)
    return make(I.size, J.size, order[place], np.repeat(oc, cnt), np.repeat(vals, cnt))


def reshape(S, m, n):
    if m * n != S.m * S.n:
        raise _err("Number of elements must not change. Use [] as one of the size inputs to automatically calculate the appropriate size for that dimension.", "MATLAB:getReshapeDims:notSameNumel")
    key = _keys(S)
    return make(m, n, key % m if m else key, key // m if m else key, S.pr)


def columns(S):
    """the values a for loop takes over S: its columns, each sparse"""
    J = np.zeros(1, dtype=_I)
    for j in range(S.n):
        J[0] = j
        yield _submatrix(S, None, J)


def truth(S):
    """S as the condition of if or while: nonempty, every element nonzero"""
    if S.m * S.n == 0 or nnz(S) != S.m * S.n:
        return False
    if S.pr.dtype.kind in "fc" and np.any(np.isnan(S.pr)):
        # (a NaN in either part of a complex value)
        raise _err("NaN's cannot be converted to logicals.", "MATLAB:nologicalnan")
    return True


# ------------------------------------------------------------------ assignment and concatenation

def _rhs_values(v, cls):
    """the values assigned into a sparse matrix of class cls, column-major"""
    c = _m.class_(v)
    if c in ("cell", "struct", "string", "function_handle") or not (_m._isnumlike(v) or type(v) is Sparse):
        raise _err("Conversion to %s from %s is not possible." % (cls, c), "MATLAB:invalidConversion")
    a = _m._farr(full(v) if type(v) is Sparse else v).reshape(-1)
    if cls == "logical":
        if a.dtype.kind == "c":
            a = a.real
        if np.any(np.isnan(a)):
            raise _err("NaN's cannot be converted to logicals.", "MATLAB:nologicalnan")
        return a != 0
    return a


def assign(S, args, v):
    """S(args) = v: sparse, its class kept (complex if a complex value goes in)"""
    args = [index_arg(a) for a in args]
    cls = class_(S)
    vals = _rhs_values(v, cls)
    dims = (S.m, S.n)
    try:
        nd = _m._grow_dims(dims, args, _m._dims(v))
    except _m.MatlabError as e:
        if e.identifier == "MATLAB:indexed_matrix_cannot_be_resized":
            raise _err("In an assignment  A(I) = B, a matrix A cannot be resized.", "MATLAB:indexed_matrix_cannot_be_resized")
        raise
    if len(nd) > 2:
        raise _err("N-dimensional sparse arrays are not supported.")
    m, n = nd
    if len(args) == 1:
        a = args[0]
        if a is COLON:
            tk = np.arange(m * n, dtype=_I)
        else:
            tk, _, _ = _m._ivec(a, m * n, -1, True)
    else:
        for k in range(2, len(args)):
            _m._ivec(args[k], 1, k, False)
        I = np.arange(m, dtype=_I) if args[0] is COLON else _m._ivec(args[0], m, 0, True)[0]
        J = np.arange(n, dtype=_I) if args[1] is COLON else _m._ivec(args[1], n, 1, True)[0]
        tk = (J.reshape((-1, 1)) * m + I.reshape((1, -1))).reshape(-1)
    if vals.size != 1 and vals.size != tk.size:
        raise _err("Unable to perform assignment because the indices on the left side are not compatible with the size of the right side.", "MATLAB:subsassigndimmismatch")
    # the old nonzeros, where nothing is assigned, and the assigned values (the last one at a place)
    old = _cols(S) * m + S.ir
    keep = ~np.isin(old, tk) if tk.size else np.ones(old.size, dtype=bool)
    new = np.repeat(vals, tk.size) if vals.size == 1 else vals
    ov = S.pr[keep]
    if ov.dtype.kind != new.dtype.kind or ov.dtype != new.dtype:
        if cls == "logical":
            new = new.astype(bool)
        else:
            dt = np.result_type(ov.dtype if ov.size else np.float64, new.dtype)
            if dt.kind == "b":
                dt = np.float64
            ov, new = ov.astype(dt), new.astype(dt)
    keys = np.concatenate([old[keep], tk])
    allv = np.concatenate([ov, new])
    r = make(m, n, keys % m if m else keys, keys // m if m else keys, allv, combine="last")
    r = _cast(r, cls) if cls != "logical" else r
    r.cap = max(S.cap, nnz(r))  # (spalloc's reservation lasts)
    return r


def delete(S, args):
    """S(args) = []"""
    args = [index_arg(a) for a in args]
    m, n = S.m, S.n
    key = _keys(S)
    if len(args) == 1:
        a = args[0]
        if a is COLON:
            return zeros(0, 0, S)
        R = np.unique(_m._ivec(a, m * n, -1, False)[0])
        keep = ~np.isin(key, R)
        k = key[keep] - np.searchsorted(R, key[keep])
        total = m * n - R.size
        if n == 1 and m != 1:
            return make(total, 1, k, np.zeros(k.size, dtype=_I), S.pr[keep])
        return make(1, total, np.zeros(k.size, dtype=_I), k, S.pr[keep])
    d = [m, n]
    which = [k for k in range(2) if not (args[k] is COLON or _m._covers(args[k], d[k]))]
    for k in range(2, len(args)):
        _m._ivec(args[k], 1, k, False)
    if not which:
        return zeros(0, n, S)
    if len(which) > 1:
        raise _err("A null assignment can have only one non-colon index.", "MATLAB:nullAssignmentNonColonIndex")
    k = which[0]
    R = np.unique(_m._ivec(args[k], d[k], k, False)[0])
    rows, cols = S.ir, _cols(S)
    sub = rows if k == 0 else cols
    keep = ~np.isin(sub, R)
    sub = sub[keep] - np.searchsorted(R, sub[keep])
    if k == 0:
        return make(m - R.size, n, sub, cols[keep], S.pr[keep])
    return make(m, n - R.size, rows[keep], sub, S.pr[keep])


def cat(vals, dim):
    """[...] with a sparse part: sparse; None for cells and other containers"""
    cls = _m._cat_class(vals)
    if cls in ("cell", "struct", "string", "handle"):
        return None
    if dim > 2:
        raise _err("Dimension for sparse matrix concatenation must be <= 2.", "MATLAB:catenate:sparseDimensionBad")
    if cls in _m._INTS or cls == "char":
        raise _err("The following error occurred converting from double to %s:\nAttempt to convert to unimplemented sparse type" % cls, "MATLAB:UnableToConvert")
    parts = [v for v in vals if _m._numel(v) != 0]
    if not parts:
        v = next(v for v in vals if type(v) is Sparse)
        return v
    mats = [_as_sparse(v) for v in parts]
    for A in mats[1:]:
        if (dim == 2 and A.m != mats[0].m) or (dim == 1 and A.n != mats[0].n):
            raise _err("Dimensions of arrays being concatenated are not consistent.", "MATLAB:catenate:dimensionMismatch")
    rows, cols, vs = [], [], []
    off = 0
    for A in mats:
        r, c = A.ir, _cols(A)
        rows.append(r + off if dim == 1 else r)
        cols.append(c + off if dim == 2 else c)
        vs.append(A.pr)
        off += A.m if dim == 1 else A.n
    m = off if dim == 1 else mats[0].m
    n = off if dim == 2 else mats[0].n
    allv = np.concatenate([x.astype(np.float64) if x.dtype.kind == "b" and cls != "logical" else x for x in vs]) if vs else np.zeros(0)
    r = make(m, n, np.concatenate(rows), np.concatenate(cols), allv)
    return _cast(r, cls) if cls != "logical" else r


# ------------------------------------------------------------------ arithmetic

def _is_scalar(x):
    return _m._numel(x) == 1


def _value_class(a, b, name):
    """the class of a ⊕ b with a sparse operand: double, single or logical"""
    for x in (a, b):
        if _m.class_(x) in _m._INTS:
            raise _err("Sparse integer array arithmetic operations are not supported.", "MATLAB:sparseInteger")
    return _m._arith_class(a, b, name)


def _sparse_result(name, a, b):
    """whether MATLAB keeps a ⊕ b sparse"""
    sa, sb = type(a) is Sparse, type(b) is Sparse
    if name in ("plus", "minus", "or", "xor"):
        return sa and sb
    if name == "times":
        return True
    if name in ("rdivide", "power"):
        return sa
    if name == "ldivide":
        return sb
    if name == "mtimes":
        # (with a scalar, as .*)
        return (sa and sb) or _is_scalar(a) or _is_scalar(b)
    if name == "mrdivide":
        return (sa and sb) or (sa and _is_scalar(b))
    if name == "mldivide":
        return (sa and sb) or (sb and _is_scalar(a))
    if name == "mpower":
        return sa
    return True  # comparisons, and


def _as_sparse(x):
    return x if type(x) is Sparse else from_full(x)


def _cast(S, cls):
    """S with its values in class cls (double or single; logical kept)"""
    k = S.pr.dtype.kind
    if k == "b" and cls != "logical":
        return _new(S.m, S.n, S.jc, S.ir, S.pr.astype(np.float32 if cls == "single" else np.float64))
    if cls == "single" and k in "fc" and S.pr.dtype.itemsize == (4 if k == "f" else 8) * 2:
        return _new(S.m, S.n, S.jc, S.ir, S.pr.astype(np.complex64 if k == "c" else np.float32))
    return S


def _fvals(S):
    """S's nonzeros as float64 or complex128"""
    v = S.pr
    if v.dtype.kind == "b":
        return v.astype(np.float64)
    return v.astype(np.complex128) if v.dtype.kind == "c" else v.astype(np.float64)


def _with(S, vals, cls):
    """S's pattern with new values (zeros dropped), in class cls"""
    vals = np.asarray(vals)
    if cls == "logical":
        vals = vals.astype(bool)
    elif cls == "single":
        vals = vals.astype(np.complex64 if vals.dtype.kind == "c" else np.float32)
    keep = vals != 0
    if np.all(keep):
        return _new(S.m, S.n, S.jc, S.ir, _canon_vals(np.array(vals)))
    return make(S.m, S.n, S.ir[keep], _cols(S)[keep], vals[keep])


def _scalar_value(x):
    a = _m._farr(x).reshape(-1)
    v = a[0]
    return complex(v) if a.dtype.kind == "c" else float(v)


def _finite(z):
    return z == z and abs(z) != _math.inf


def _union(A, B):
    """the union of two same-sized sparse matrices' patterns: (keys, A's values there, B's)"""
    ka, kb = _keys(A), _keys(B)
    keys = np.unique(np.concatenate([ka, kb]))
    va = np.zeros(keys.size, dtype=np.complex128 if A.pr.dtype.kind == "c" else np.float64)
    vb = np.zeros(keys.size, dtype=np.complex128 if B.pr.dtype.kind == "c" else np.float64)
    if ka.size:
        va[np.searchsorted(keys, ka)] = _fvals(A)
    if kb.size:
        vb[np.searchsorted(keys, kb)] = _fvals(B)
    return keys, va, vb


def _from_keys(m, n, keys, vals, cls):
    vals = np.asarray(vals)
    if cls == "logical":
        vals = vals.astype(bool)
    elif cls == "single":
        vals = vals.astype(np.complex64 if vals.dtype.kind == "c" else np.float32)
    keep = vals != 0
    keys, vals = keys[keep], vals[keep]
    return make(m, n, keys % m if m else keys, keys // m if m else keys, vals)


_ELEM = {
    "plus": _m._add, "minus": _m._sub, "times": _m._mul, "rdivide": _m._div,
    "ldivide": lambda A, B: _m._div(B, A), "power": _m._pow,
}
_CMP = {
    "eq": lambda x, y: x == y, "ne": lambda x, y: x != y, "lt": lambda x, y: x < y,
    "le": lambda x, y: x <= y, "gt": lambda x, y: x > y, "ge": lambda x, y: x >= y,
}


def _native(name, a, b, cls):
    """a ⊕ b on the sparse storage, when the result is sparse and that is exact; else None"""
    sa, sb = type(a) is Sparse, type(b) is Sparse
    same = _m._dims(a) == _m._dims(b)
    if name in ("plus", "minus") and sa and sb and same:
        rows = np.concatenate([a.ir, b.ir])
        cols = np.concatenate([_cols(a), _cols(b)])
        vb = _fvals(b)
        vals = np.concatenate([_fvals(a).astype(np.complex128) if vb.dtype.kind == "c" else _fvals(a),
                               -vb if name == "minus" else vb])
        r = make(a.m, a.n, rows, cols, vals)
        return _cast(r, cls)
    if name == "times" and (sa != sb) and _is_scalar(b if sa else a) and not (sa and sb):
        S, k = (a, b) if sa else (b, a)
        z = _scalar_value(k)
        if _finite(z):
            return _with(S, _m._mul(_fvals(S), np.array([z])), cls)
        return None
    if name in ("rdivide", "ldivide") and (sa if name == "rdivide" else sb):
        S, k = (a, b) if name == "rdivide" else (b, a)
        if type(k) is not Sparse and _is_scalar(k):
            z = _scalar_value(k)
            if z != 0 and z == z:
                return _with(S, _m._div(_fvals(S), np.array([z])), cls)
        return None
    if name == "times" and same:
        if sa and sb:
            keys, va, vb = _union(a, b)
            return _from_keys(a.m, a.n, keys, _m._mul(va, vb), cls)
        S, F = (a, b) if sa else (b, a)
        f = _m._farr(F).reshape(-1)
        if np.all(np.isfinite(f)):
            return _with(S, _m._mul(_fvals(S), f[_keys(S)]), cls)
        return None
    if name == "power" and sa and type(b) is not Sparse and _is_scalar(b):
        z = _scalar_value(b)
        if type(z) is float and z > 0:
            return _with(a, _m._pow(_fvals(a), np.array([z])), cls)
        return None
    if name in _CMP:
        f = _CMP[name]
        if (sa != sb) and _is_scalar(b if sa else a):
            S, k = (a, b) if sa else (b, a)
            z = _scalar_value(k)
            z = z.real if type(z) is complex and name not in ("eq", "ne") else z
            g = f if sa else (lambda x, y: f(y, x))
            if not g(0.0, z):
                vals = _fvals(S)
                if vals.dtype.kind == "c" and name not in ("eq", "ne"):
                    vals = vals.real
                return _with(S, g(vals, z), "logical")
            return None
        if sa and sb and same and not f(0.0, 0.0):
            keys, va, vb = _union(a, b)
            if name not in ("eq", "ne"):
                va, vb = va.real, vb.real
            return _from_keys(a.m, a.n, keys, f(va, vb), "logical")
        return None
    if name == "and" and same:
        if sa and sb:
            keys, va, vb = _union(a, b)
            return _from_keys(a.m, a.n, keys, (va != 0) & (vb != 0), "logical")
        S, F = (a, b) if sa else (b, a)
        f = _m._logical_arr(F, "and").reshape(-1)
        return _with(S, f[_keys(S)], "logical")
    if name in ("or", "xor") and sa and sb and same:
        keys, va, vb = _union(a, b)
        x, y = va != 0, vb != 0
        return _from_keys(a.m, a.n, keys, (x | y) if name == "or" else (x != y), "logical")
    return None


def _full_pm(name, a, b):
    """S + F, S - F, F - S with a full matrix F the same size: full, as MATLAB
    computes it (F, or -F, with S's nonzeros added: -0 where S is zero in S - F)"""
    S, F = (a, b) if type(a) is Sparse else (b, a)
    out = _m._farr(F).astype(np.complex128 if S.pr.dtype.kind == "c" else _m._farr(F).dtype)
    if S.pr.dtype.kind == "c" and out.dtype.kind != "c":
        out = out.astype(np.complex128)
    flat = np.array(out).reshape(-1)
    k = _keys(S)
    fk = flat[k]
    sv = _fvals(S)
    if name == "plus":
        flat[k] = sv + fk
    elif type(a) is Sparse:  # S - F
        flat = -flat
        flat[k] = sv - fk
    else:  # F - S
        flat[k] = fk - sv
    return _m._box(flat.reshape(out.shape))


def binop(name, a, b):
    """a ⊕ b (an operator) with a sparse operand"""
    cls = _value_class(a, b, name) if name not in _CMP and name not in ("and", "or", "xor") else "logical"
    if name in ("and", "or", "xor"):
        for x in (a, b):
            if _m.class_(x) in ("cell", "struct", "string", "function_handle"):
                raise _err("Operator '%s' is not supported for operands of type '%s'." % (_m._OPSYM.get(name, name), _m.class_(x)))
    elif name in _CMP:
        for x in (a, b):
            if _m.class_(x) in _m._INTS:
                raise _err("Sparse integer array arithmetic operations are not supported.", "MATLAB:sparseInteger")
    keep = _sparse_result(name, a, b)
    if keep:
        r = _native(name, a, b, cls)
        if r is not None:
            return r
    if name in ("mtimes", "mrdivide", "mldivide", "mpower"):
        return _matrix_op(name, a, b, cls, keep)
    if name in ("plus", "minus") and not keep and _m._dims(a) == _m._dims(b) and not (type(a) is Sparse and type(b) is Sparse):
        return _finish(_full_pm(name, a, b), cls)
    r = _dense(name, full(a), full(b))
    return _finish(from_full(r) if keep else r, cls)


def _finish(r, cls):
    if type(r) is Sparse:
        return _cast(r, cls)
    if cls == "single" and _m.class_(r) == "double":
        a = _m._farr(r)
        return _m._canon(a.astype(np.complex64 if a.dtype.kind == "c" else np.float32))
    return r


def _dense(name, a, b):
    if name == "xor":
        return _FULL["xor"](1, a, b)
    return getattr(_m, {"and": "and_", "or": "or_"}.get(name, name))(a, b)


def _matmul(A, B):
    """A * B for 2-D values with a sparse one (neither scalar): sparse if both are"""
    if _m._dims(A)[1] != _m._dims(B)[0]:
        raise _err("Incorrect dimensions for matrix multiplication. Check that the number of columns in the first matrix matches the number of rows in the second matrix. To operate on each element of the matrix individually, use TIMES (.*) for elementwise multiplication.", "MATLAB:innerdim")
    if type(A) is Sparse and type(B) is Sparse:
        # each nonzero B(k,j) times column k of A
        e, oc = _gather(A, B.ir)
        vals = _fvals(A)[e] * _fvals(B)[oc]
        return make(A.m, B.n, A.ir[e], _cols(B)[oc], vals)
    if type(A) is Sparse:
        # (each column of B: sums over A's nonzeros, row by row, in column order)
        Bf = _m._farr(B)  # stored transposed: Bf[j] is column j
        av = _fvals(A)
        ac = _cols(A)
        cplx = av.dtype.kind == "c" or Bf.dtype.kind == "c"
        out = np.zeros((Bf.shape[0], A.m), dtype=np.complex128 if cplx else np.float64)
        for j in range(Bf.shape[0]):
            prod = av * Bf[j][ac]
            if cplx:
                out[j] = _m._cplx(np.bincount(A.ir, weights=prod.real, minlength=A.m), np.bincount(A.ir, weights=prod.imag, minlength=A.m))
            else:
                out[j] = np.bincount(A.ir, weights=prod, minlength=A.m)
        return _m._box(out)
    # full * sparse: each column of B a sum over its nonzeros
    Af = _m._farr(A)  # (n, m) stored: Af[:, i] is row i of A... (stored transposed)
    M = Af.T  # m-by-k, MATLAB orientation
    bv = _fvals(B)
    bc = _cols(B)
    cplx = bv.dtype.kind == "c" or M.dtype.kind == "c"
    out = np.zeros((B.n, M.shape[0]), dtype=np.complex128 if cplx else np.float64)
    for i in range(M.shape[0]):
        prod = M[i][B.ir] * bv
        if cplx:
            out[:, i] = _m._cplx(np.bincount(bc, weights=prod.real, minlength=B.n), np.bincount(bc, weights=prod.imag, minlength=B.n))
        else:
            out[:, i] = np.bincount(bc, weights=prod, minlength=B.n)
    return _m._box(out)


def _matrix_op(name, a, b, cls, keep):
    if name == "mtimes":
        if _is_scalar(a) or _is_scalar(b):
            r = binop("times", a, b)
            return r if keep or type(r) is not Sparse else full(r)
        return _finish(_matmul(a, b), cls)
    if name == "mrdivide" and _is_scalar(b):
        return binop("rdivide", a, b)
    if name == "mldivide" and _is_scalar(a):
        return binop("ldivide", a, b)
    if name == "mldivide" and type(a) is Sparse:
        return _finish(mldivide(a, b), cls)
    if name == "mpower" and _is_scalar(b) and not _is_scalar(a):
        p = _m._scalar(b)
        if p == _math.floor(p) and p >= 0:
            if a.m != a.n:
                raise _err("Incorrect dimensions for raising a matrix to a power. Check that the matrix is square and the power is a scalar. To operate on each element of the matrix individually, use POWER (.^) for elementwise power.")
            # (by squaring from A itself, so that A^1 is A; each product is refused for Inf or
            # NaN as mtimes's is, so an Inf in A or from an overflowing square stops it)
            R = None
            A = a
            p = int(p)
            while p:
                if p & 1:
                    if R is None:
                        R = A
                    else:
                        _m._matprod_finite(R, A)
                        R = _matmul(R, A)
                p >>= 1
                if p:
                    _m._matprod_finite(A, A)
                    A = _matmul(A, A)
            if R is None:
                k = np.arange(a.n, dtype=_I)
                R = make(a.n, a.n, k, k, np.ones(a.n))
            return _cast(R, cls)
    r = getattr(_m, name)(full(a), full(b))
    return _finish(from_full(r) if keep and _m._isnumlike(r) else r, cls)


def unop(name, a):
    """-S, +S, ~S"""
    if name == "uminus":
        if islogical(a):
            return _with(a, -_fvals(a), "double")
        return _new(a.m, a.n, a.jc, a.ir, -a.pr)
    if name == "uplus":
        return _cast(a, "double") if islogical(a) else a
    # not: true where S is zero
    vals = a.pr.real if a.pr.dtype.kind == "c" else a.pr
    if vals.dtype.kind == "f" and np.any(np.isnan(vals)):
        raise _err("NaN's cannot be converted to logicals.", "MATLAB:nologicalnan")
    return from_full(np.logical_not(full_arr(a) != 0))


# ------------------------------------------------------------------ elementwise functions

# f(0) = 0: applied to the nonzeros alone
_ZERO_KEEPING = set("""abs sqrt sign round floor ceil fix real imag conj angle sin tan asin atan sinh tanh asinh
atanh expm1 log1p deg2rad rad2deg isnan isinf nthroot cbrt""".split())
# kept sparse, though most of their values are nonzero: computed on the full matrix
_SPARSE_FULL = set("""exp cos log log2 log10 cosh acos acosh sec csc cot asec acsc acot sech csch coth asech acsch
acoth gamma mod rem atan2 double logical single""".split())


def _elementwise_fn(name):
    f = _FULL[name]

    def g(nargout, *args):
        if not _has_sparse(args):
            return f(nargout, *args)
        x = args[0]
        if name in _ZERO_KEEPING and len(args) == 1 and type(x) is Sparse:
            col = _m._box(np.array(x.pr.reshape((1, -1))))
            r = f(1, col)
            vals = _m._arr(r).reshape(-1)
            if vals.dtype.kind == "c":
                # (a zero imaginary part is 0, not -0)
                vals = _m._cplx(vals.real, np.where(vals.imag == 0, 0.0, vals.imag)).astype(vals.dtype)
            out = make(x.m, x.n, x.ir, _cols(x), vals) if vals.size == x.pr.size else from_full(r)
            return out
        r = f(nargout, *[full(a) if type(a) is Sparse else a for a in args])
        if type(x) is Sparse and _m._isnumlike(r) and _m.class_(r) in ("double", "single", "logical") and len(_m._dims(r)) == 2:
            return from_full(r)
        return r
    return g


# ------------------------------------------------------------------ reductions and shape

def _dim_arg(S, args):
    """sum(S), sum(S, dim), sum(S, 'all'): 1, 2, 3+ (S itself), "all"; None for other options"""
    if not args:
        return 2 if S.m == 1 else 1
    if len(args) > 1:
        return None
    a = args[0]
    if type(a) is _m.Char or type(a) is _m.Str:
        return "all" if _m._text(a).lower() == "all" else None
    if not _is_scalar(a):
        return None
    d = _m._scalar(a)
    if d != _math.floor(d) or d < 1:
        return None
    return int(d)


def _group_sum(groups, vals, n):
    if vals.dtype.kind == "c":
        return _m._cplx(np.bincount(groups, weights=vals.real, minlength=n), np.bincount(groups, weights=vals.imag, minlength=n))
    return np.bincount(groups, weights=vals, minlength=n)


def _reduced(S, d, vals):
    """a sum along dimension d (1, 2 or "all") as a sparse matrix"""
    k = np.arange(S.n if d == 1 else S.m if d == 2 else 1, dtype=_I)
    z = np.zeros(k.size, dtype=_I)
    if d == 1:
        return make(1, S.n, z, k, vals)
    if d == 2:
        return make(S.m, 1, k, z, vals)
    return make(1, 1, z, z, vals)


def sum_(S, d):
    v = _fvals(S)
    if d == "all":
        r = _reduced(S, d, np.array([_group_sum(np.zeros(v.size, dtype=_I), v, 1)[0]]))
    else:
        r = _reduced(S, d, _group_sum(_cols(S) if d == 1 else S.ir, v, S.n if d == 1 else S.m))
    return _cast(r, "single" if class_(S) == "single" else "double")


def anyall(S, d, is_all):
    v = S.pr.real if S.pr.dtype.kind == "c" else S.pr
    if is_all:
        nz = np.ones(v.size, dtype=bool)
    else:
        nz = ~np.isnan(v) if v.dtype.kind == "f" else np.ones(v.size, dtype=bool)
    if d == "all":
        g, size, full_n = np.zeros(v.size, dtype=_I), 1, S.m * S.n
    elif d == 1:
        g, size, full_n = _cols(S), S.n, S.m
    else:
        g, size, full_n = S.ir, S.m, S.n
    cnt = np.bincount(g[nz], minlength=size) if g.size else np.zeros(size, dtype=_I)
    vals = (cnt == full_n) if is_all else (cnt > 0)
    return _reduced(S, d, vals)


def diag_(S, k=0):
    k = int(k)
    if S.m == 1 or S.n == 1:
        # a vector: the matrix with it on diagonal k
        n = S.m * S.n + abs(k)
        p = _keys(S)
        return make(n, n, p + max(-k, 0), p + max(k, 0), S.pr)
    rows, cols = S.ir, _cols(S)
    on = (cols - rows) == k
    length = max(0, min(S.m + min(k, 0), S.n - max(k, 0)))
    r = rows[on] - max(-k, 0)
    return make(length, 1, r, np.zeros(r.size, dtype=_I), S.pr[on])


def tri(S, k, lower):
    rows, cols = S.ir, _cols(S)
    keep = (cols - rows <= k) if lower else (cols - rows >= k)
    return make(S.m, S.n, rows[keep], cols[keep], S.pr[keep])


def kron_(A, B):
    A, B = _as_sparse(A), _as_sparse(B)
    na, nb = A.pr.size, B.pr.size
    ra, ca = np.repeat(A.ir, nb), np.repeat(_cols(A), nb)
    rb, cb = np.tile(B.ir, na), np.tile(_cols(B), na)
    vals = np.repeat(_fvals(A), nb) * np.tile(_fvals(B), na)
    r = make(A.m * B.m, A.n * B.n, ra * B.m + rb, ca * B.n + cb, vals)
    return r if not (islogical(A) and islogical(B)) else r


def repmat_(S, r, c):
    if r == 0 or c == 0 or not S.pr.size:
        return zeros(S.m * r, S.n * c, S)
    rows, cols = S.ir, _cols(S)
    k = S.pr.size
    br = np.repeat(np.arange(r, dtype=_I), k)
    allr = np.tile(rows, r) + br * S.m
    allc = np.tile(cols, r)
    vals = np.tile(S.pr, r)
    bc = np.repeat(np.arange(c, dtype=_I), allr.size)
    return make(S.m * r, S.n * c, np.tile(allr, c), np.tile(allc, c) + bc * S.n, np.tile(vals, c))


def flip(S, lr):
    rows, cols = S.ir, _cols(S)
    if lr:
        return make(S.m, S.n, rows, S.n - 1 - cols, S.pr)
    return make(S.m, S.n, S.m - 1 - rows, cols, S.pr)


def _size_list(args):
    """reshape's sizes: (m, n), one of them [] for 'whatever fits'"""
    if len(args) == 1:
        d = [float(x) for x in _m._arr(args[0]).reshape(-1)]
        return d
    out = []
    for a in args:
        out.append(None if _m._numel(a) == 0 else float(_m._scalar(a)))
    return out


def _reshape_b(nargout, S, *args):
    if type(S) is not Sparse:
        return _SPARSE_OUT_FN["reshape"](nargout, S, *args)
    d = _size_list(args)
    if len(d) > 2:
        if all(x == 1 for x in d[2:] if x is not None) and None not in d[2:]:
            d = d[:2]
        else:
            raise _err("N-D sparse arrays are not supported.", "MATLAB:reshape:sparseNDmatrix")
    total = S.m * S.n
    if None in d:
        known = [x for x in d if x is not None]
        other = int(known[0]) if known else 1
        d = [total // other if x is None else int(x) for x in d]
    return reshape(S, int(d[0]), int(d[1]))


def _sum_b(nargout, x, *args):
    if type(x) is Sparse:
        d = _dim_arg(x, args)
        if d is not None:
            return x if d not in (1, 2, "all") else sum_(x, d)
    return _SPARSE_OUT_FN["sum"](nargout, x, *args)


def _anyall_b(is_all):
    name = "all" if is_all else "any"

    def g(nargout, x, *args):
        if type(x) is Sparse:
            d = _dim_arg(x, args)
            if d is not None:
                if d not in (1, 2, "all"):
                    return _with(x, x.pr != 0, "logical") if not islogical(x) else x
                return anyall(x, d, is_all)
        return _SPARSE_OUT_FN[name](nargout, x, *args)
    return g


def _mean_b(nargout, x, *args):
    if type(x) is Sparse and x.m * x.n:
        d = _dim_arg(x, args)
        if d in (1, 2, "all"):
            n = x.m if d == 1 else x.n if d == 2 else x.m * x.n
            return binop("rdivide", sum_(x, d), float(n))
    return _SPARSE_OUT_FN["mean"](nargout, x, *args)


def _diag_b(nargout, x, k=0.0):
    if type(x) is Sparse:
        return diag_(x, _m._scalar(k))
    return _SPARSE_OUT_FN["diag"](nargout, x, k)


def _tri_b(lower):
    name = "tril" if lower else "triu"

    def g(nargout, x, k=0.0):
        if type(x) is Sparse:
            return tri(x, int(_m._scalar(k)), lower)
        return _SPARSE_OUT_FN[name](nargout, x, k)
    return g


def _kron_b(nargout, a, b):
    if type(a) is Sparse or type(b) is Sparse:
        for x in (a, b):
            if _m.class_(x) in _m._INTS:
                raise _err("Sparse integer array arithmetic operations are not supported.", "MATLAB:sparseInteger")
        r = kron_(a, b)
        return _cast(r, _m._arith_class(a, b, "times")) if not (islogical(r) and False) else r
    return _FULL["kron"](nargout, a, b)


def _repmat_b(nargout, x, *args):
    if type(x) is Sparse:
        if len(args) == 1:
            d = [int(float(v)) for v in _m._arr(args[0]).reshape(-1)]
            d = d * 2 if len(d) == 1 else d
        else:
            d = [int(_m._scalar(a)) for a in args]
        if len(d) == 2 or all(v == 1 for v in d[2:]):
            return repmat_(x, max(d[0], 0), max(d[1], 0))
    return _SPARSE_OUT_FN["repmat"](nargout, x, *args)


def _flip_b(lr):
    name = "fliplr" if lr else "flipud"

    def g(nargout, x):
        if type(x) is Sparse:
            return flip(x, lr)
        return _FULL[name](nargout, x)
    return g


# built-ins MATLAB keeps sparse, computed on the full matrix: which of their
# outputs are sparse (the others, such as max's indices, full)
_SPARSE_OUT = {
    "prod": (0,), "cumsum": (0,), "cumprod": (0,), "max": (0,), "min": (0,), "median": (0,), "std": (0,),
    "var": (0,), "dot": (0,), "circshift": (0,), "rot90": (0,), "permute": (0,), "squeeze": (0,),
    "blkdiag": (0,), "sort": (0,), "unique": (0,), "sum": (0,), "any": (0,), "all": (0,), "mean": (0,),
    "diag": (0,), "tril": (0,), "triu": (0,), "repmat": (0,), "reshape": (0,),
    "inv": (0,), "lu": (0, 1, 2), "chol": (0,), "qr": (0, 1),
}
_SPARSE_OUT_FN = {}


def _sparse_out(name):
    f = _FULL[name]
    which = _SPARSE_OUT[name]

    def g(nargout, *args):
        if not _has_sparse(args):
            return f(nargout, *args)
        r = f(nargout, *[full(a) if type(a) is Sparse else a for a in args])
        keep = which
        if name == "lu" and any(_m._istext(a) and _m._text(a).lower() == "vector" for a in args):
            keep = (0, 1)  # (a permutation vector is full)
        elif name == "qr" and len(args) > 1 and type(args[1]) is not Sparse and not _m._istext(args[1]) \
                and not _m._qr_econ_flag(args[1]):
            keep = (1,)  # ([C, R] = qr(S, B): C = Q'*B is full for a full B)
        multi = type(r) is list
        outs = r if multi else [r]
        outs = [from_full(o) if k in keep and _m._isnumlike(o) and _m.class_(o) in ("double", "single", "logical")
                and len(_m._dims(o)) == 2 else o for k, o in enumerate(outs)]
        return outs if multi else outs[0]
    return g


def blkdiag_b(nargout, *args):
    """blkdiag(A, B, ...): the matrices along the diagonal; sparse if one is"""
    if not args:
        return np.zeros((0, 0))
    mats = []
    for a in args:
        if not (_m._isnumlike(a) or type(a) is Sparse) or len(_m._dims(a)) > 2:
            raise _err("Inputs must be 2-D numeric or logical arrays.")
        mats.append(_as_sparse(a) if _m.class_(a) in ("double", "single", "logical") else from_full(_m._farr(a)))
    rows, cols, vals = [], [], []
    m = n = 0
    for A in mats:
        rows.append(A.ir + m)
        cols.append(_cols(A) + n)
        vals.append(_fvals(A))
        m += A.m
        n += A.n
    r = make(m, n, np.concatenate(rows), np.concatenate(cols), np.concatenate(vals))
    cls = "single" if any(_m.class_(a) == "single" for a in args) else "double"
    r = _cast(r, cls)
    return r if _has_sparse(args) else full(r)


def _fft_sizes_first(name):
    """fft2, ifft2, fftn and ifftn of a sparse X: the full transform, every argument after X
    checked as sizes before X is made full (only the inverses' text flags, such as
    'symmetric', are left to the full function), so a bad size of any class is refused at once"""
    f = _FULL[name]

    def g(nargout, *args):
        if _has_sparse(args):
            rest = list(args[1:])
            for a in rest:
                if type(a) is Sparse and a.m * a.n > 64:
                    raise _err("%s: a sparse size argument with %d elements is not supported." % (name, a.m * a.n))
            # (the whole signature, as the full function checks it: count, sizes, flag)
            _m._fft_parse(name, [full(a) if type(a) is Sparse else a for a in rest])
            args = [full(a) if type(a) is Sparse else a for a in args]
        return f(nargout, *args)
    return g


_SPECIAL = {
    "sum": _sum_b, "any": _anyall_b(False), "all": _anyall_b(True), "mean": _mean_b, "diag": _diag_b,
    "tril": _tri_b(True), "triu": _tri_b(False), "kron": _kron_b, "repmat": _repmat_b, "reshape": _reshape_b,
    "fliplr": _flip_b(True), "flipud": _flip_b(False),
}


# ------------------------------------------------------------------ linear algebra

# the largest square matrix solved through its full form (beyond, a banded one)
MAX_DENSE_SOLVE = 4000


def bandwidths(S):
    """(lower, upper) bandwidths"""
    if not S.pr.size:
        return 0, 0
    d = _cols(S) - S.ir
    return int(max(0, -int(np.min(d)))), int(max(0, int(np.max(d))))


def _band_solve(S, B):
    """S \\ B for a square sparse S of small bandwidth: LU with partial pivoting
    in LAPACK's band storage (gbtrf, then the two triangular solves); B a
    MATLAB-oriented full matrix"""
    n = S.n
    kl, ku = bandwidths(S)
    ldab = 2 * kl + ku + 1
    cplx = S.pr.dtype.kind == "c" or B.dtype.kind == "c"
    dt = np.complex128 if cplx else np.float64
    AB = np.zeros((ldab, n), dtype=dt)
    rows, cols = S.ir, _cols(S)
    AB[kl + ku + rows - cols, cols] = _fvals(S)
    X = np.array(B, dtype=dt)
    piv = np.zeros(n, dtype=_I)
    singular = False
    for k in range(n):
        last = min(n - 1, k + kl)
        col = AB[kl + ku: kl + ku + last - k + 1, k]
        p = int(np.argmax(np.abs(col))) + k
        piv[k] = p
        if AB[kl + ku + p - k, k] == 0:
            singular = True
            continue
        hi = min(n - 1, k + kl + ku)
        cs = np.arange(k, hi + 1, dtype=_I)
        if p != k:
            a = AB[kl + ku + k - cs, cs].copy()
            AB[kl + ku + k - cs, cs] = AB[kl + ku + p - cs, cs]
            AB[kl + ku + p - cs, cs] = a
            X[[k, p]] = X[[p, k]]
        if last > k:
            rs = np.arange(k + 1, last + 1, dtype=_I)
            l = AB[kl + ku + rs - k, k] / AB[kl + ku, k]
            AB[kl + ku + rs - k, k] = l
            if hi > k:
                c2 = cs[1:]
                urow = AB[kl + ku + k - c2, c2]
                AB[kl + ku + rs.reshape((-1, 1)) - c2.reshape((1, -1)), c2.reshape((1, -1))] -= l.reshape((-1, 1)) * urow.reshape((1, -1))
            X[k + 1:last + 1] -= l.reshape((-1, 1)) * X[k].reshape((1, -1))
    if singular:
        _m.warning_("Matrix is singular to working precision.")
    with np.errstate(divide="ignore", invalid="ignore"):
        for k in range(n - 1, -1, -1):
            hi = min(n - 1, k + kl + ku)
            if hi > k:
                c2 = np.arange(k + 1, hi + 1, dtype=_I)
                X[k] -= (AB[kl + ku + k - c2, c2].reshape((-1, 1)) * X[k + 1:hi + 1]).sum(axis=0)
            X[k] /= AB[kl + ku, k]
    return X


# the most multiply-adds a band solve may take (beyond, the sparse LU)
MAX_BAND_WORK = 1 << 29

# the most a sparse LU factorization may hold (nonzeros of L and U together)
# and do (multiply-adds); a matrix whose factors fill in beyond is refused
MAX_LU_FILL = 1 << 22
MAX_LU_WORK = 1 << 24


class _LU:
    """P*A = L*U for a square sparse A, by columns: at step k row prow[k] of A is
    the pivot, L's column k (unit diagonal) is lrow[k] (A's rows; lstep[k], the
    steps they are pivoted at) with values lval[k], and U's column j is
    ustep[j] (steps before j) with values uval[j] over the diagonal udiag[j]"""

    def solve(self, B, trans=False):
        """A \\ B, or A' \\ B (the conjugate transpose); B an n-by-k full matrix"""
        n = self.n
        dt = np.complex128 if self.udiag.dtype.kind == "c" or B.dtype.kind == "c" else np.float64
        b = np.array(B, dtype=dt).reshape((n, -1))
        with np.errstate(divide="ignore", invalid="ignore", over="ignore"):
            if not trans:
                # (L y = P b, then U x = y)
                y = np.zeros_like(b)
                for k in range(n):
                    y[k] = b[self.prow[k]]
                    if self.lrow[k].size:
                        b[self.lrow[k]] -= self.lval[k].reshape((-1, 1)) * y[k].reshape((1, -1))
                for j in range(n - 1, -1, -1):
                    y[j] /= self.udiag[j]
                    if self.ustep[j].size:
                        y[self.ustep[j]] -= self.uval[j].reshape((-1, 1)) * y[j].reshape((1, -1))
                return y
            # (A' = U' L' P: U' w = b, then L' v = w, then x = P' v)
            w = b
            for j in range(n):
                if self.ustep[j].size:
                    w[j] -= (np.conj(self.uval[j]).reshape((-1, 1)) * w[self.ustep[j]]).sum(axis=0)
                w[j] /= np.conj(self.udiag[j])
            for k in range(n - 1, -1, -1):
                if self.lstep[k].size:
                    w[k] -= (np.conj(self.lval[k]).reshape((-1, 1)) * w[self.lstep[k]]).sum(axis=0)
            x = np.zeros_like(w)
            x[self.prow] = w
            return x


def _too_much_fill(n):
    return _err("Out of memory: the LU factors of this %dx%d sparse matrix fill in too far to solve with it (Sagebrush orders no columns to reduce fill)." % (n, n), "MATLAB:nomem")


def _sparse_lu(S):
    """the LU factorization of a square sparse S, never its full form:
    left-looking, each column by a sparse triangular solve over the steps it
    reaches (as Gilbert and Peierls's; a row in L's column k is pivoted after
    step k, so the steps in increasing order are a topological one), with
    partial pivoting that keeps the diagonal while it is within a factor of 10
    of the largest candidate.  A zero pivot is kept (the solves then give Inf
    or NaN, as MATLAB's do, with its warning)"""
    n = S.n
    dt = np.complex128 if S.pr.dtype.kind == "c" else np.float64
    vals = _fvals(S).astype(dt)
    jc, ir = S.jc, S.ir
    pinv = np.full(n, -1, dtype=_I)
    reached = np.zeros(n, dtype=bool)
    prow = [0] * n
    lrow, lval = [None] * n, [None] * n
    ustep, uval = [None] * n, [None] * n
    udiag = np.zeros(n, dtype=dt)
    x = np.zeros(n, dtype=dt)
    free = 0  # (no row before it is unpivoted)
    fill = work = 0
    for j in range(n):
        a0, a1 = int(jc[j]), int(jc[j + 1])
        rows = ir[a0:a1]
        x[rows] = vals[a0:a1]
        # (the steps this column reaches through L, level by level)
        levels = []
        f = pinv[rows]
        f = f[f >= 0]
        while f.size:
            f = np.unique(f[~reached[f]])
            if not f.size:
                break
            reached[f] = True
            levels.append(f)
            nxt = [lrow[k] for k in f.tolist() if lrow[k].size]
            if not nxt:
                break
            f = pinv[np.concatenate(nxt)]
            f = f[f >= 0]
        order = np.sort(np.concatenate(levels)).tolist() if levels else []
        if levels:
            reached[order] = False
        touched = [rows]
        uv = np.zeros(len(order), dtype=dt)
        for t, k in enumerate(order):
            xk = x[prow[k]]
            uv[t] = xk
            if xk != 0 and lrow[k].size:
                x[lrow[k]] -= lval[k] * xk
            touched.append(lrow[k])
            work += lrow[k].size
        if work > MAX_LU_WORK:
            raise _too_much_fill(n)
        ustep[j] = np.array(order, dtype=_I)
        uval[j] = uv
        allr = np.unique(np.concatenate(touched)) if len(touched) > 1 else np.unique(rows)
        cand = allr[pinv[allr] < 0]
        cv = x[cand]
        amax = float(np.max(np.abs(cv))) if cand.size else 0.0
        if amax > 0:
            if pinv[j] < 0 and abs(x[j]) >= 0.1 * amax:
                p = j
            else:
                p = int(cand[int(np.argmax(np.abs(cv)))])
        else:
            while pinv[free] >= 0:
                free += 1
            p = j if pinv[j] < 0 else int(free)
        pinv[p] = j
        prow[j] = p
        udiag[j] = x[p]
        keep = (cand != p) & (cv != 0)
        lrow[j] = cand[keep]
        lval[j] = cv[keep] / x[p] if amax > 0 else cv[keep]
        x[allr] = 0
        fill += lrow[j].size + len(order) + 1
        if fill > MAX_LU_FILL:
            raise _too_much_fill(n)
    F = _LU()
    F.n = n
    F.prow = np.array(prow, dtype=_I)
    F.lrow, F.lval, F.ustep, F.uval, F.udiag = lrow, lval, ustep, uval, udiag
    F.lstep = [pinv[r] for r in lrow]
    F.singular = bool(np.any(udiag == 0))
    return F


def mldivide(a, b):
    """a \\ b with a sparse a (not scalar): through the full matrix when small;
    beyond, by its diagonal, its band, or its sparse LU factorization"""
    A = a
    if A.m != _m._dims(b)[0]:
        raise _err("Matrix dimensions must agree.", "MATLAB:dimagree")
    if A.m == A.n and A.n > MAX_DENSE_SOLVE and bandwidths(A) == (0, 0):
        # (diagonal: each row divided by its element)
        dvals = np.zeros(A.n, dtype=np.complex128 if A.pr.dtype.kind == "c" else np.float64)
        dvals[A.ir] = _fvals(A)
        if np.any(dvals == 0):
            _m.warning_("Matrix is singular to working precision.")
        Bm = _m._mat(full(b) if type(b) is Sparse else b)
        with np.errstate(divide="ignore", invalid="ignore"):
            X = Bm / dvals.reshape((-1, 1))
        r = _m._unmat(X)
        return from_full(r) if type(b) is Sparse else r
    if A.m == A.n and A.n > MAX_DENSE_SOLVE:
        kl, ku = bandwidths(A)
        Bm = _m._mat(full(b) if type(b) is Sparse else b)
        if (2 * kl + ku + 1) * A.n <= MAX_FULL and A.n * (kl + 1) * (kl + ku + 1) <= MAX_BAND_WORK:
            X = _band_solve(A, Bm)
        else:
            F = _sparse_lu(A)
            if F.singular:
                _m.warning_("Matrix is singular to working precision.")
            X = F.solve(Bm)
        r = _m._unmat(X)
        return from_full(r) if type(b) is Sparse else r
    r = _m.mldivide(full(a), full(b))
    return from_full(r) if type(b) is Sparse and _m._isnumlike(r) else r


def _eig_b(nargout, x, *args):
    if type(x) is Sparse:
        if x.pr.dtype.kind == "c" or x.m != x.n or nnz(binop("ne", x, transpose(x))) != 0:
            raise _err("Input matrix must be real and symmetric when matrix is sparse. Use eigs to compute a subset of eigenvectors and eigenvalues of a sparse matrix.", "MATLAB:eig:useEigsForSparseStandard")
    return _FULL["eig"](nargout, *[full(a) if type(a) is Sparse else a for a in (x,) + args])


def _svd_b(nargout, x, *args):
    if type(x) is Sparse:
        raise _err("SVD does not support sparse matrices. Use SVDS to compute a subset of the singular values and vectors of a sparse matrix.", "MATLAB:svd:noSVDsparse")
    return _FULL["svd"](nargout, x, *args)


def _norm_b(nargout, x, p=None):
    if type(x) is Sparse:
        vec = x.m == 1 or x.n == 1
        two = p is None or (not _m._istext(p) and _m._scalar(p) == 2)
        if two and not vec:
            raise _err("Sparse norm(S,2) is not available.", "MATLAB:norm:spNorm2notAvailable")
        if not vec and p is not None and not _m._istext(p) and _m._scalar(p) in (1.0, _math.inf):
            # (on the nonzeros: column or row sums of magnitudes)
            d = 1 if _m._scalar(p) == 1 else 2
            v = np.abs(_fvals(x))
            sums = _group_sum(_cols(x) if d == 1 else x.ir, v, x.n if d == 1 else x.m)
            return float(np.max(sums)) if sums.size else 0.0
        if not vec and p is not None and _m._istext(p) and _m._text(p) == "fro":
            v = np.abs(_fvals(x))
            sc = float(np.max(v)) if v.size else 0.0
            return 0.0 if sc == 0 else float(sc * np.sqrt(np.sum((v / sc) ** 2)))
    args = [full(x)] + ([] if p is None else [full(p)])
    return _FULL["norm"](nargout, *args)


def _normest_b(nargout, S, tol=None):
    """[nrm, count] = normest(S, tol): the 2-norm by the power method for
    the p-norm (Higham, "Accuracy and Stability of Numerical Algorithms",
    2nd ed., section 15.2, with p = 2): for a unit vector x, the estimate is
    gamma = ||S x||, and the next x is S'(S x) normalized.  The stopping
    rule is the one MATLAB documents rather than Higham's: the iteration
    ends when two successive estimates agree to within the relative
    tolerance tol (1e-6), the first being compared with 0.  The start is
    the unit vector along ones (or, should S annihilate that, along the
    column of S with the largest norm); MATLAB documents no start, so the
    count can differ from MATLAB's"""
    tol = 1e-6 if tol is None else float(_m._scalar(tol))
    d = _m._dims(S)
    n = d[1] if len(d) == 2 else int(np.prod(d[1:]))
    if n == 0 or (type(S) is Sparse and not S.pr.size):
        return [0.0, 0.0] if nargout > 1 else 0.0
    St = _m.ctranspose(S)

    def mul(M, v):
        r = np.asarray(_m._mat(_m.mtimes(M, _m._unmat(v))))
        return r if r.dtype.kind == "c" else r.astype(np.float64)

    def norm2(v):
        a = np.abs(v)
        top = float(np.max(a)) if a.size else 0.0
        return 0.0 if top == 0 else top * float(np.sqrt(np.sum((a / top) ** 2)))
    x = np.ones((n, 1))
    if norm2(mul(S, x)) == 0:
        cn = (_group_sum(_cols(S), np.abs(_fvals(S)) ** 2, S.n) if type(S) is Sparse
              else np.sum(np.abs(_m._mat(S)) ** 2, axis=0))
        x = np.zeros((n, 1))
        x[int(np.argmax(np.asarray(cn).reshape(-1)))] = 1.0
    x = x / norm2(x)
    previous, count = 0.0, 0
    while True:
        y = mul(S, x)
        gamma = norm2(y)
        count += 1
        if abs(gamma - previous) <= tol * gamma or gamma == 0:
            break
        previous = gamma
        z = mul(St, y)
        nz = norm2(z)
        if nz == 0:
            break
        x = z / nz
        if count >= 1000:
            _m.warning_("normest: no convergence within 1000 iterations to the tolerance %g." % tol)
            break
    return [gamma, float(count)] if nargout > 1 else gamma


def _condest_b(nargout, A, *args):
    """the 1-norm condition number, estimated: norm(A, 1) times Hager's estimate
    of norm(inv(A), 1), which takes a few solves with A and A' (never inv(A);
    a large sparse A by its sparse LU factorization)"""
    d = _m._dims(A)
    if len(d) != 2 or d[0] != d[1]:
        raise _err("Matrix must be square.")
    n = d[0]
    if n == 0:
        return 0.0
    At = _m.ctranspose(A)
    if type(A) is Sparse:
        norm1 = float(np.max(_group_sum(_cols(A), np.abs(_fvals(A)), A.n))) if A.pr.size else 0.0
    else:
        norm1 = float(np.max(np.sum(np.abs(_m._mat(A)), axis=0)))

    if type(A) is Sparse and n > MAX_DENSE_SOLVE:
        # (one factorization, for the solves with A and with A')
        F = _sparse_lu(A)

        def solve(M, v):
            return F.solve(v.reshape((-1, 1)), trans=M is At).reshape(-1)
    else:
        def solve(M, v):
            with np.errstate(all="ignore"):
                r = _m.mldivide(M, _m._unmat(v.reshape((-1, 1))))
            return _m._mat(full(r) if type(r) is Sparse else r).reshape(-1)
    warn = _m.warning_
    _m.warning_ = lambda *a, **k: None  # (the solves' own warnings: the estimate says it)
    try:
        x = np.full(n, 1.0 / n)
        est = 0.0
        for k in range(5):
            y = solve(A, x)
            new = float(np.sum(np.abs(y)))
            if not np.isfinite(new):
                return _math.inf
            if k > 0 and new <= est:
                break
            est = new
            xi = np.where(np.real(y) < 0, -1.0, 1.0)
            z = np.abs(solve(At, xi))
            j = int(np.argmax(z))
            if k > 0 and z[j] <= float(np.real(np.dot(z, x))):
                break
            x = np.zeros(n)
            x[j] = 1.0
    finally:
        _m.warning_ = warn
    return norm1 * est


# ------------------------------------------------------------------ the sparse functions

def _spfun_b(nargout, f, S):
    S = _as_sparse(S)
    r = _m._call(f, [_m._box(np.array(_fvals(S).reshape((1, -1))))])
    vals = _m._arr(r).reshape(-1)
    if vals.size != S.pr.size:
        raise _err("SPFUN: the function must return as many values as it is given.")
    return make(S.m, S.n, S.ir, _cols(S), vals)


def _diag_index(m, n, d):
    """the rows and columns of diagonal d, and each one's row of spdiags's B
    (B's rows go with A's columns when m >= n, else with its rows)"""
    i0, j0 = max(0, -d), max(0, d)
    length = max(0, min(m - i0, n - j0))
    i = np.arange(i0, i0 + length, dtype=_I)
    j = np.arange(j0, j0 + length, dtype=_I)
    return i, j, (j if m >= n else i)


def _spdiags_b(nargout, *args):
    if len(args) <= 2:
        # B = spdiags(A), [B, d] = spdiags(A), B = spdiags(A, d)
        A = _as_sparse(args[0])
        m, n = A.m, A.n
        if len(args) == 2:
            ds = [int(float(x)) for x in _m._arr(args[1]).reshape(-1)]
        else:
            ds = sorted(set(int(x) for x in (_cols(A) - A.ir)[_fvals(A) != 0]))
        k = min(m, n)
        single = class_(A) == "single"
        cplx = A.pr.dtype.kind == "c"
        out = np.zeros((len(ds), k), dtype=(np.complex64 if single else np.complex128) if cplx else (np.float32 if single else np.float64))
        key = _keys(A)
        vals = _fvals(A)
        for c, d in enumerate(ds):
            i, j, b = _diag_index(m, n, d)
            p = j * m + i
            pos = np.searchsorted(key, p)
            pc = np.minimum(pos, max(key.size - 1, 0))
            found = (pos < key.size) & (key[pc] == p) if key.size else np.zeros(p.size, dtype=bool)
            out[c, b[found]] = vals[pc[found]]
        B = _m._box(out) if not single else _m._canon(out)
        if nargout >= 2:
            return [B, _m._box(np.array([[float(d) for d in ds]]))]
        return B
    B = _m._mat(full(args[0]) if type(args[0]) is Sparse else args[0])
    ds = [int(float(x)) for x in _m._arr(args[1]).reshape(-1)]
    if len(args) == 3:
        # S = spdiags(B, d, A): A with diagonals d replaced
        A = _as_sparse(args[2])
        m, n = A.m, A.n
        drop = np.isin(_cols(A) - A.ir, np.array(ds, dtype=_I))
        rows, cols, vals = [A.ir[~drop]], [_cols(A)[~drop]], [_fvals(A)[~drop]]
    else:
        m, n = int(_m._scalar(args[2])), int(_m._scalar(args[3]))
        rows, cols, vals = [], [], []
    if B.ndim == 1:
        B = B.reshape((-1, len(ds)))
    if B.shape[0] == 1 and B.shape[1] in (1, len(ds)):
        # (a scalar or a row, one element per diagonal: each diagonal constant, as spdiags's page
        # allows Bin to be a scalar or vector, only a column or matrix needing min(m, n) rows)
        B = np.repeat(B, max(m, n), axis=0)
    for c, d in enumerate(ds):
        i, j, b = _diag_index(m, n, d)
        ok = b < B.shape[0]
        rows.append(i[ok])
        cols.append(j[ok])
        vals.append(B[b[ok], c if B.shape[1] > 1 else 0])
    return make(m, n, np.concatenate(rows) if rows else np.zeros(0, dtype=_I), np.concatenate(cols) if cols else np.zeros(0, dtype=_I),
                np.concatenate(vals) if vals else np.zeros(0))


def _rand_values(name, k):
    return _m._arr(_m._B[name].f(1, float(k), 1.0)).reshape(-1)


def _sprand(name, args):
    if len(args) == 1:
        S = _as_sparse(args[0])
        return make(S.m, S.n, S.ir, _cols(S), _rand_values(name, S.pr.size) if S.pr.size else np.zeros(0))
    m, n = int(_m._scalar(args[0])), int(_m._scalar(args[1]))
    density = _density(args[2])
    want = int(round(m * n * density)) if m * n else 0
    if want == 0:
        return zeros(m, n)
    # (places drawn with replacement, a repeated one kept once, then their
    # values: consistent with the documented "approximately density*m*n
    # uniformly distributed nonzero entries" and "significantly fewer ... if
    # m*n is small or density is large", and with the published
    # nnz(sprand(500, 1000, 0.1)) of 47663.  The exact places and values are
    # not claimed to be MATLAB's)
    i = _m._arr(_m._B["randi"].f(1, float(m), float(want), 1.0)).reshape(-1).astype(_I) - 1
    j = _m._arr(_m._B["randi"].f(1, float(n), float(want), 1.0)).reshape(-1).astype(_I) - 1
    key = np.unique(i * n + j)
    vals = _rand_values(name, key.size)
    return make(m, n, key // n, key % n, vals)


def _density(d):
    v = _m._scalar(d)
    if not (0.0 <= v <= 1.0):
        raise _err("Density must be between 0 and 1.")
    return v


def _sprand_b(nargout, *args):
    return _sprand("rand", args)


def _sprandn_b(nargout, *args):
    return _sprand("randn", args)


def _sprandsym_b(nargout, n, density=None, *rest):
    if density is None:
        S = _as_sparse(n)
        L = tri(S, 0, True)
        R = make(S.m, S.n, L.ir, _cols(L), _rand_values("randn", L.pr.size))
    else:
        # (distinct places on and below the diagonal, until the matrix and its
        # mirror image have density * n^2 nonzeros)
        n = int(_m._scalar(n))
        want = int(round(_density(density) * n * n))
        keys = np.zeros(0, dtype=_I)
        count = 0
        places = n * (n + 1) // 2
        while count < want:
            if 2 * keys.size >= places:
                # (most places taken: the rest from the ones still free, in a
                # random order, rather than sampling until they turn up)
                free = np.setdiff1d(_lower_keys(n), keys, assume_unique=True)
                order = _m._arr(_m._B["randperm"].f(1, float(free.size))).reshape(-1).astype(_I) - 1
                keys = np.concatenate([keys, free[order]])
                weight = np.where(keys // n == keys % n, 1, 2)
                keys = keys[:int(np.searchsorted(np.cumsum(weight), want)) + 1]
                break
            k = max(16, want - count)
            i = _m._arr(_m._B["randi"].f(1, float(n), float(k), 1.0)).reshape(-1).astype(_I) - 1
            j = _m._arr(_m._B["randi"].f(1, float(n), float(k), 1.0)).reshape(-1).astype(_I) - 1
            lo, hi = np.minimum(i, j), np.maximum(i, j)
            new = hi * n + lo  # (row hi, column lo: on or below the diagonal)
            allk = np.concatenate([keys, new])
            _, first = np.unique(allk, return_index=True)
            keys = allk[np.sort(first)]
            weight = np.where(keys // n == keys % n, 1, 2)
            total = np.cumsum(weight)
            if total.size and total[-1] >= want:
                keys = keys[:int(np.searchsorted(total, want)) + 1]
            count = int(np.sum(np.where(keys // n == keys % n, 1, 2))) if keys.size else 0
            if keys.size >= n * (n + 1) // 2:
                break
        keys = np.sort(keys)
        R = make(n, n, keys // n, keys % n, _rand_values("randn", keys.size) if keys.size else np.zeros(0))
    return binop("plus", R, transpose(tri(R, -1, True)))


def _lower_keys(n):
    """row * n + column of each place on or below the diagonal of an n-by-n matrix"""
    k = np.arange(n * n, dtype=_I)  # (already in order)
    return k[k // n >= k % n]


def _like_proto(args):
    if len(args) >= 2 and _m._istext(args[-2]) and _m._text(args[-2]).lower() == "like":
        return args[-1]
    return None


def _like_fn(name, ok):
    f = _FULL[name]

    def g(nargout, *args):
        proto = _like_proto(args)
        if type(proto) is Sparse:
            if not ok:
                raise _err('Sparse input following "like" is not supported.', "MATLAB:%s:sparsePrototype" % name)
            if name in ("true", "false"):
                # (a logical result, from a logical prototype only, as the pages say: never
                # the prototype's class or complexity)
                if class_(proto) != "logical":
                    raise _err("%s: the prototype following \"like\" must be logical." % name)
                return from_full(f(nargout, *args[:-2]))
            # (the prototype's class and complexity, from its storage)
            r = from_full(f(nargout, *(args[:-2] + (_m.Char(class_(proto)),))))
            if proto.pr.dtype.kind == "c":
                r = _new(r.m, r.n, r.jc, r.ir, r.pr.astype(np.complex64 if class_(proto) == "single" else np.complex128))
            return r
        return f(nargout, *args)
    return g


def _cast_b(nargout, x, *args):
    """cast(x, class), cast(x, 'like', p): p's class, sparsity and complexity"""
    if len(args) == 2 and _m._istext(args[0]) and _m._text(args[0]).lower() == "like":
        p = args[1]
        cls = _m.class_(p)
        pc = (p.pr.dtype.kind == "c") if type(p) is Sparse else (_m._isnumlike(p) and _m._arr(p).dtype.kind == "c")
        if type(x) is Sparse and (type(p) is Sparse or cls in ("double", "single", "logical")):
            # (on the stored values: neither matrix expanded)
            v = x.pr
            if cls == "logical":
                if v.dtype.kind in "fc" and np.any(np.isnan(v)):
                    raise _err("NaN's cannot be converted to logicals.", "MATLAB:nologicalnan")
                v = v != 0
            else:
                single = cls == "single"
                if pc or v.dtype.kind == "c":
                    v = v.astype(np.complex64 if single else np.complex128)
                else:
                    v = v.astype(np.float32 if single else np.float64)
            r = make(x.m, x.n, x.ir, _cols(x), v)
            if pc and r.pr.dtype.kind != "c":
                r = _new(r.m, r.n, r.jc, r.ir, r.pr.astype(np.complex64 if cls == "single" else np.complex128))
            return r if type(p) is Sparse else full(r)
        r = _m._B[cls].f(1, full(x) if type(x) is Sparse else x) if cls in _m._B else x
        if type(p) is Sparse:
            r = from_full(r)
        if pc:
            if type(r) is Sparse:
                r = _new(r.m, r.n, r.jc, r.ir, r.pr.astype(np.complex64 if cls == "single" else np.complex128))
            else:
                a = _m._arr(r)
                r = _m._canon(a.astype(np.complex64 if cls == "single" else np.complex128))
        return r
    if len(args) != 1 or not _m._istext(args[0]):
        raise _err("Unsupported data type for conversion.")
    cls = _m._text(args[0])
    if cls not in _m._B:
        raise _err("Unsupported data type for conversion: '%s'." % cls)
    return _m._B[cls].f(1, x)


def _accumarray_b(nargout, *args):
    sparse_ = len(args) >= 6 and _m._numel(args[5]) == 1 and _m.cond(args[5])
    r = _FULL["accumarray"](nargout, *[full(a) if type(a) is Sparse else a for a in args])
    return from_full(r) if sparse_ else r


# matrix structure: for full matrices too
def _structure(S):
    S = _as_sparse(S)
    return S, S.ir, _cols(S)


def _skew_arg(args, name):
    """issymmetric's and ishermitian's mode: 'nonskew' (the default) or 'skew'"""
    if not args:
        return False
    mode = _m._text(args[0]).lower() if _m._istext(args[0]) else None
    if mode not in ("skew", "nonskew"):
        raise _err("Second input must be 'skew' or 'nonskew'.")
    return mode == "skew"


def _issymmetric_b(nargout, x, *args):
    if not (_m._isnumlike(x) or type(x) is Sparse) or len(_m._dims(x)) > 2:
        return False
    S = _as_sparse(x)
    if S.m != S.n:
        return False
    skew = _skew_arg(args, "issymmetric")
    T = transpose(S)
    return nnz(binop("ne", S, unop("uminus", T) if skew else T)) == 0


def _ishermitian_b(nargout, x, *args):
    if not (_m._isnumlike(x) or type(x) is Sparse) or len(_m._dims(x)) > 2:
        return False
    S = _as_sparse(x)
    if S.m != S.n:
        return False
    skew = _skew_arg(args, "ishermitian")
    T = transpose(S, conj=True)
    return nnz(binop("ne", S, unop("uminus", T) if skew else T)) == 0


def _bandwidth_b(nargout, x, which=None):
    kl, ku = bandwidths(_as_sparse(x))
    if which is not None:
        w = _m._text(which).lower()
        return float(kl if w == "lower" else ku)
    return [float(kl), float(ku)] if nargout > 1 else float(kl)


def _isbanded_b(nargout, x, lower, upper):
    kl, ku = bandwidths(_as_sparse(x))
    return kl <= _m._scalar(lower) and ku <= _m._scalar(upper)


def _istril_b(nargout, x):
    return bandwidths(_as_sparse(x))[1] == 0


def _istriu_b(nargout, x):
    return bandwidths(_as_sparse(x))[0] == 0


def _isdiag_b(nargout, x):
    return bandwidths(_as_sparse(x)) == (0, 0)


# ------------------------------------------------------------------ built-in functions

def _int(x, what="Sparse matrix sizes", clip=False):
    v = _m._scalar(x)
