    def shaped(a):
        a = np.array(a, dtype=np.float64)
        return _m._box(a.reshape((a.size, 1)) if row else a.reshape((1, a.size)))
    if nargout <= 1:
        return shaped(key + 1)
    out = [shaped(key % S.m + 1 if S.m else key), shaped(key // S.m + 1 if S.m else key)]
