    return _FULL["isreal"](nargout, x)


_NATIVE = {
    "sparse": sparse_, "full": full_b, "speye": speye_, "spalloc": spalloc_, "spones": spones_,
    "issparse": issparse_, "nnz": nnz_, "nzmax": nzmax_, "nonzeros": nonzeros_, "find": find_,
    "isreal": isreal_,
