    return g


def activate():
    """(once) make the built-ins take sparse matrices"""
    if _active[0]:
        return
    _active[0] = True
    for name, b in list(_m._B.items()):
        if name in _NATIVE or name in _PASS:
            continue
        _FULL[name] = b.f
        b.f = _expanding(b)


