    _m._B["blkdiag"] = _m.Builtin(blkdiag_b, "blkdiag")
    for name, f in (("spfun", _spfun_b), ("spdiags", _spdiags_b), ("sprand", _sprand_b), ("sprandn", _sprandn_b),
