        norm = _m._text(args[2]).lower()
    A, cls = _values("legendre", args[1])
    if A.dtype.kind == "c" or (A.size and (np.any(~(A >= -1)) or np.any(~(A <= 1)))):
        raise _err("legendre: X must be real and in the range -1 <= X <= 1.")
