    # numpy shape is MATLAB's (n+1)-by-numel; otherwise [n+1, size(X)])
    vector = A.ndim <= 2 and min(A.shape) <= 1
    if not vector:
        R = R.reshape(A.shape + (n + 1,))
    return _m._finish(R, cls)

