    # misses: summing pi cot(pi (t/h - d)) f(t) round the nodes gives
    # w(z) = (i h/pi) sum_j e^(-t_j^2)/(z - t_j) + 2 e^(-z^2)/(1 - e^(-2 pi i (z/h - d))),
