def _temme_gamma12(mu):
    """Temme's Gamma_1(mu) = (1/Gamma(1 - mu) - 1/Gamma(1 + mu)) / (2 mu) and
    Gamma_2(mu) = (1/Gamma(1 - mu) + 1/Gamma(1 + mu)) / 2 for |mu| <= 1/2,
    from the series of 1/Gamma (DLMF 5.7.1): 1/Gamma(1 + mu) = sum_j
    c_(j+1) mu^j, so Gamma_1 = -(c_2 + c_4 mu^2 + ...) and Gamma_2 = c_1 +
    c_3 mu^2 + ..., without the cancellation of the closed form at mu = 0;
    also 1/Gamma(1 + mu) and 1/Gamma(1 - mu)"""
    m2 = mu * mu
    g1 = g2 = 0.0
    for j in range(len(_RGAMMA_C) - 1, -1, -1):
        if j % 2:
            g1 = g1 * m2 + _RGAMMA_C[j]  # (c_(j+1), j odd: c_2, c_4, ...)
        else:
            g2 = g2 * m2 + _RGAMMA_C[j]
    g1 = -g1
    return g1, g2, g2 - mu * g1, g2 + mu * g1


def _bessely_temme(mu, x):
    """(Y_mu(x), Y_(mu+1)(x)) as (m, e) pairs, |mu| <= 1/2, 0 < x <= 2, by
    Temme's series (N. M. Temme, J. Comput. Phys. 21 (1976) 343-350):
    Y_mu = -sum_k c_k g_k, Y_(mu+1) = -(2/x) sum_k c_k h_k, c_k =
    (-x^2/4)^k / k!, g_k = f_k + (2/mu) sin^2(mu pi/2) q_k, h_k = p_k - k g_k,
    p_k = p_(k-1)/(k - mu), q_k = q_(k-1)/(k + mu), f_k = (k f_(k-1) +
    p_(k-1) + q_(k-1)) / (k^2 - mu^2), from p_0 = (x/2)^-mu Gamma(1 + mu)/pi,
    q_0 = (x/2)^mu Gamma(1 - mu)/pi and f_0 = (2/pi) (mu pi / sin(mu pi))
    (cosh(sigma) Gamma_1 + (sinh(sigma)/sigma) log(2/x) Gamma_2), sigma = mu
    log(2/x).  log(2/x) is log 2 - log x, so that the least subnormal x is
    safe; |sigma| <= 373 keeps e^sigma a double; 2/x goes into the exponent.
    NotCovered if the series does not reach eps by 100 terms (it needs at
    most 14 for x <= 2)"""
    l2x = _math.log(2.0) - _math.log(x)
    sigma = mu * l2x
    g1, g2, rgp, rgm = _temme_gamma12(mu)
    # ((x/2)^-mu = e^sigma as x^-mu 2^mu, each power rounded once: e^sigma of
    # the rounded sigma lost |sigma| eps, 5.5e-14 at x = 2.4e-261, and x/2
    # underflows for the least subnormal; for |sigma| >= 1 cosh and sinh from
    # it, below 1 directly, where |sigma| eps is small, with sinh's series
    # where sinh(sigma)/sigma would cancel)
    es = 1.0 if mu == 0 else (x ** -mu) * (2.0 ** mu)
    if abs(sigma) < 1:
        ch = _math.cosh(sigma)
        shc = 1.0 + sigma * sigma / 6.0 if abs(sigma) < 1e-4 else _math.sinh(sigma) / sigma
        t2 = shc * l2x * g2
    else:
        ch = 0.5 * (es + 1.0 / es)
        t2 = 0.5 * (es - 1.0 / es) / mu * g2  # (sinh(sigma)/sigma log(2/x) = sinh(sigma)/mu)
    p = es / (_PI * rgp)
    q = 1.0 / (es * _PI * rgm)
    # (mu pi / sin(mu pi), 1 at mu = 0)
    fac = 1.0 if mu == 0 else mu * _PI / _sinpi(mu)
    f = (2.0 / _PI) * fac * (ch * g1 + t2)
    if mu == 0:
        r = 0.0
    else:
        sh = _sinpi(0.5 * mu)
        r = 2.0 * sh * sh / mu
    c = 1.0
    d = -0.25 * x * x
    g = f + r * q
    sg = g
    sh_ = p
    for k in range(1, 101):
        c *= d / k
        f = (k * f + p + q) / (k * k - mu * mu)
        p /= k - mu
        q /= k + mu
        g = f + r * q
        h = p - k * g
        sg += c * g
        sh_ += c * h
        if abs(c * g) <= 1e-17 * abs(sg) and abs(c * h) <= 1e-17 * abs(sh_):
            break
    else:
        raise NotCovered("bessely: Temme's series did not converge at mu = %r, x = %r" % (mu, x))
    xm, xe = _math.frexp(x)
    return (-sg, 0), (-sh_ * (2.0 / xm), -xe)


def _lentz_tiny(v):
    return v if v != 0 else 1e-300


def _bessely_steed(mu, x):
    """(Y_mu(x), Y_(mu+1)(x)) for 0 <= mu < 1 and x > 2 by Steed's method
    (A. R. Barnett, D. H. Feng, J. W. Steed and L. J. B. Goldfarb, Comput.
    Phys. Commun. 8 (1974) 377-395; I. J. Thompson and A. R. Barnett,
    J. Comput. Phys. 64 (1986) 490-509), both logarithmic derivatives at
    order mu:
    CF1, f = J'_mu/J_mu = mu/x - J_(mu+1)/J_mu, the ratio by the continued
    fraction 1/(b_1 - 1/(b_2 - ...)), b_k = 2 (mu + k)/x (DLMF 10.10.1 and
    10.6.2), at most ceil(x) + 200 terms;
    CF2, p + iq = H'_mu/H_mu = -1/(2x) + i + (i/x) a_1/(b_1 + a_2/(b_2 + ...)),
    a_k = (k - 1/2)^2 - mu^2, b_k = 2 (x + k i), at most 1000 terms;
    both by the modified Lentz method to |delta - 1| <= 2^-60, NotCovered if
    not met.  The Wronskian 2/(pi x) (DLMF 10.5.2) gives |J_mu| =
    sqrt(W/(q + gamma (p - f))) with gamma = (p - f)/q, Y_mu = gamma J_mu,
    Y'_mu = p Y_mu + q J_mu (from H' = (p + iq) H: no division by Y_mu,
    astra's correction), Y_(mu+1) = (mu/x) Y_mu - Y'_mu (DLMF 10.6.2).  The
    sign of J_mu, which CF1 does not give, comes from besselj's J_mu, or
    near its zeros from the sign of J'_mu = (mu/x) J_mu - J_(mu+1); the two
    J_mu must agree to 1e-13 of sqrt(2/(pi x)), or NotCovered"""
    eps = 2.0 ** -60
    # (CF1: K = b_1 - 1/(b_2 - 1/(b_3 - ...)), the ratio J_(mu+1)/J_mu = 1/K)
    b = 2.0 * (mu + 1) / x
    fk = _lentz_tiny(b)
    cc = fk
    dd = 0.0
    k1 = int(_math.ceil(x)) + 200
    for k in range(2, k1 + 1):
        b = 2.0 * (mu + k) / x
        dd = 1.0 / _lentz_tiny(b - dd)
        cc = _lentz_tiny(b - 1.0 / cc)
        delta = cc * dd
        fk *= delta
        if abs(delta - 1.0) <= eps:
            break
    else:
        raise NotCovered("bessely: the continued fraction CF1 did not converge at mu = %r, x = %r" % (mu, x))
    f = mu / x - 1.0 / fk
    # (CF2: T = a_1 / (b_1 + a_2/(b_2 + ...)); at mu = 1/2, a_1 = 0 and H is elementary)
    a1 = 0.25 - mu * mu
    if a1 == 0:
        t = 0j
    else:
        bk = complex(2.0 * x, 2.0)
        fk2 = bk
        cc2 = bk
        dd2 = 0j
        for k in range(2, 1001):
            ak = (k - 0.5) ** 2 - mu * mu
            bk = complex(2.0 * x, 2.0 * k)
            dd2 = bk + ak * dd2
            dd2 = 1.0 / (dd2 if dd2 != 0 else 1e-300)
            cc2 = bk + ak / cc2
            if cc2 == 0:
                cc2 = 1e-300
            delta = cc2 * dd2
            fk2 *= delta
            if abs(delta - 1.0) <= eps:
                break
        else:
            raise NotCovered("bessely: the continued fraction CF2 did not converge at mu = %r, x = %r" % (mu, x))
        t = a1 / fk2
    pq = complex(-0.5 / x, 1.0) + complex(0.0, 1.0 / x) * t
    p, q = pq.real, pq.imag
    w = 2.0 / (_PI * x)
    gam = (p - f) / q
    jm = _math.sqrt(w / (q + gam * (p - f)))
    nrm = _math.sqrt(w)
    jb = _besselj_pos(mu, x)
    if abs(jb) >= 0.1 * nrm:
        s = 1.0 if jb > 0 else -1.0
    else:
        jpb = (mu / x) * jb - _besselj_pos(mu + 1, x)
        s = (1.0 if jpb > 0 else -1.0) * (1.0 if f > 0 else -1.0)
    jm *= s
    if not abs(jm - jb) <= 1e-13 * nrm:
        raise NotCovered("bessely: Steed's J_mu and besselj's disagree at mu = %r, x = %r" % (mu, x))
    ym = gam * jm
    ypm = p * ym + q * jm
    return (ym, 0), ((mu / x) * ym - ypm, 0)


def _bessely_hankel(nu, x):
    """Y_nu(x) by Hankel's expansion, DLMF 10.17.4: sqrt(2/(pi x)) (sin w P +
    cos w Q), with besselj's P, Q, phase and prefactor; None if its
    omitted-term check fails"""
    pq = _hankel_pq(nu, x)
    if pq is None:
        return None
    p, qv = pq
    cw, sw = _hankel_phase(nu, x)
    return _SQRT_2_PI / _math.sqrt(x) * (sw * p + cw * qv)


def _bessely_up(mu, n, x, y0, y1, coef):
    """Y_(mu+n)(x) as an (m, e) pair from Y_mu = y0 and Y_(mu+1) = y1 ((m, e)
    pairs) by the recurrence DLMF 10.6.1 upward, Y is dominant there, in
    double-double arithmetic (_bessel_dd_step) with the exponent carried.
    For x < 1 the recurrence runs with x' = x 2^s in [1, 2) (exact): Y_(k+1) =
    2^s ((2 (mu+k)/x') Y_k - 2^-s Y_(k-1)), each step's 2^s going into the
    exponent, so that 2 (mu+k)/x never overflows (it was inf at x = 5e-324)
    and the earlier term, negligible there, may underflow; the mantissas are
    renormalized by an exact 2^-500 past 2^500.  At most _BESSEL_MAX_N steps
    (NotCovered beyond), unless a bound proves the final value beyond the
    doubles first: past the turning point (order > x) with |Y_(k+1)| >=
    |Y_k| of one sign, |Y| only grows from there, so once coef |Y| >= 2^1030
    (coef the least nonzero modulus of the coefficients that will multiply
    Y_nu afterwards) the result is (+-inf, 0), the sign of the mantissa"""
    if n == 0:
        return y0
    if n == 1:
        return y1
    a = _me_norm(*y0)
    bb = _me_norm(*y1)
    e = max(a[1], bb[1])
    ah, al = _ldexp(a[0], a[1] - e), 0.0
    bh, bl = _ldexp(bb[0], bb[1] - e), 0.0
    sh = 0
    xs = x
    if x < 1:
        sh = 1 - _math.frexp(x)[1]
        xs = _ldexp(x, sh)
    C = 134217729.0
    t = C * xs
    xh = t - (t - xs)
    xl = xs - xh
    lc = _math.log2(coef) if coef > 0 else 0.0
    for k in range(1, n):
        if k > _BESSEL_MAX_N:
            raise NotCovered("bessely: Sagebrush covers orders for which the recurrence needs at most %d steps (here %d)" % (_BESSEL_MAX_N, n))
        if sh:
            gh, gl = _ldexp(ah, -sh), _ldexp(al, -sh)
            ah, al = _ldexp(bh, -sh), _ldexp(bl, -sh)
            bh, bl = _bessel_dd_step(mu, k, xs, xh, xl, bh, bl, gh, gl)
            e += sh
        else:
            (ah, al), (bh, bl) = (bh, bl), _bessel_dd_step(mu, k, xs, xh, xl, bh, bl, ah, al)
        if abs(bh) > 2.0 ** 500:
            ah, al, bh, bl = (_math.ldexp(v, -500) for v in (ah, al, bh, bl))
            e += 500
        if mu + k + 1 > x and bh * ah > 0 and abs(bh) >= abs(ah) and _math.log2(abs(bh)) + e + lc >= 1030:
            return (_math.copysign(_math.inf, bh), 0)
    return (bh + bl, e)


def _bessely_pos_me(nu, x, coef=1.0):
    """Y_nu(x) for nu >= 0 and x > 0 as an (m, e) pair; coef as for
    _bessely_up.  Hankel's expansion at nu for x >= max(25, nu^2); otherwise
    Y_mu and Y_(mu+1) by the elementary forms (half-integer nu, DLMF
    10.16.1), Temme's series (x <= 2, |mu| <= 1/2), Steed's method (2 < x <
    25, 0 <= mu < 1) or Hankel's expansion (x >= 25), then upward"""
    if x >= 25 and nu <= _math.sqrt(x):
        v = _bessely_hankel(nu, x)
        if v is not None:
            return (v, 0)
    if nu - _math.floor(nu) == 0.5:
        # (DLMF 10.16.1: Y_(1/2) = -sqrt(2/(pi x)) cos x, and Y_(3/2) =
        # (1/2)/x Y_(1/2) - Y'_(1/2) = Y_(1/2)/x - sqrt(2/(pi x)) sin x, 10.6.2)
        n = int(_math.floor(nu))
        nrm = _SQRT_2_PI / _math.sqrt(x)
        y0 = -nrm * _math.cos(x)
        # (y0 / x as an (m, e) pair: it is beyond the doubles for x below 2.7e-206)
        fx, ex = _math.frexp(x)
        y1 = _me_add((y0 / fx, -ex), (-nrm * _math.sin(x), 0))
        return _bessely_up(0.5, n, x, (y0, 0), y1, coef)
    if x <= 2:
        # (n and mu = nu - n, |mu| <= 1/2, both exact: floor(nu + 0.5) rounded
        # 0.5 - 2^-54 up to n = 1, and nu - 1 then to -1/2, the order 1/2
        # instead (astra's CORR-F00-3); nu - floor(nu) and f - 1 are exact)
        n = int(_math.floor(nu))
        mu = nu - n
        if mu > 0.5:
            n += 1
            mu -= 1.0
        y0, y1 = _bessely_temme(mu, x)
        return _bessely_up(mu, n, x, y0, y1, coef)
    n = int(_math.floor(nu))
    mu = nu - n
    if x >= 25:
        a = _bessely_hankel(mu, x)
        b = _bessely_hankel(mu + 1, x)
        if a is not None and b is not None:
            return _bessely_up(mu, n, x, (a, 0), (b, 0), coef)
        if x > 1e4:
            raise NotCovered("bessely: Hankel's expansion did not reach eps at mu = %r, x = %r" % (mu, x))
    y0, y1 = _bessely_steed(mu, x)
    return _bessely_up(mu, n, x, y0, y1, coef)


def _bessel_base(nu):
    """J_nu and Y_nu as alpha J_b + beta Y_b, b = |nu|: ((alpha, beta) of J,
    (alpha, beta) of Y).  nu >= 0 itself; integer nu = -n by DLMF 10.4.1,
    (-1)^n; other nu = -a by Y_-a = sin(a pi) J_a + cos(a pi) Y_a (from
    10.4.5) and J_-a = cos(a pi) J_a - sin(a pi) Y_a (10.4.3 with 10.4.6),
    the exactly reduced sin and cos"""
    if nu >= 0:
        return (1.0, 0.0), (0.0, 1.0)
    a = -nu
    if a == _math.floor(a):
        sg = -1.0 if int(a) % 2 else 1.0
        return (sg, 0.0), (0.0, sg)
    sa, ca = _sinpi(a), _cospi(a)
    return (ca, -sa), (sa, ca)


def _bessel_parts(nu, t, comps, x):
    """the doubles alpha J_b(t) + beta Y_b(t), b = |nu|, t > 0, for each
    (alpha, beta) in comps: the final real and imaginary parts of J_nu or
    Y_nu at x = +-t, every connection (_bessel_base) and continuation
    coefficient already multiplied in, so that each part has one Y_b term
    and is +-inf only where it is itself beyond the doubles (daybreak's and
    astra's CORR-F00-1: Y_b became inf before a small coefficient brought a
    part back, or two infinities made a NaN).  Y_b is an (m, e) pair, its
    overflow bound (_bessely_up) taken at the least nonzero |beta|; J_b is
    not computed where no alpha needs it, Y_b where no beta does.

    J_b as a double suffices.  Beyond the turning point it is within its
    absolute accuracy, a fraction of the envelope, even next to its zeros.
    Below the turning point it can fall below the normal doubles only for b >
    0.95, as (x/2)^b / Gamma(b + 1) > 2^-1022 for b <= 0.95 at any x >= 2^-1074;
    there |J_b Y_b| is near 1/(pi b) (DLMF 10.19.1), so |Y_b| > 2^1021 / b.  A
    beta that is not 0 is a product of at most two of the reduced sin(b pi) and
    cos(b pi), with a factor 2 (cos^2(b pi) in the imaginary part of Y_-b(-x)),
    and each of those is either 0 (dropped), 1 in modulus, or at least 2^-52
    for a double b >= 0.95 (its distance to the nearest integer or
    half-integer is at least an ulp, 2^-53): so |beta| >= 2^-104, |alpha| <= 2,
    and the J term is below 2^-1800 of the Y term (astra's note on 97a12fc:
    the bound is not 2^-51 for products and squares; the overflow bound uses
    the actual least |beta|).  A part is refused (NotCovered) where its two
    terms cancel: where 5e-15 (|alpha J| + |beta Y|), 5e-15 a bound on J_b's
    and Y_b's measured errors (3.1e-15 at most), exceeds 1e-12 of max(|the
    part|, max(|alpha|, |beta|) sqrt(2/(pi t)) for t > b)"""
    b = abs(nu)
    jb = _besselj_pos(b, t) if any(al != 0 for al, _ in comps) else 0.0
    coefs = [abs(be) for _, be in comps if be != 0]
    yb = _bessely_pos_me(b, t, min(coefs)) if coefs else (0.0, 0)
    nrm = _SQRT_2_PI / _math.sqrt(t) if t > b else 0.0
    out = []
    for al, be in comps:
        if be == 0:
            out.append(al * jb)
            continue
        u2 = (be * yb[0], yb[1])
        if al == 0 or jb == 0:
            out.append(_me_val(u2))
            continue
        u1 = (al * jb, 0)
        r = _me_add(u1, u2)
        if _math.isfinite(r[0]):
            lsum = _me_log2(_me_add((abs(u1[0]), 0), (abs(u2[0]), u2[1])))
            lr = _me_log2(r)
            floor = _math.log2(max(abs(al), abs(be)) * nrm) if nrm else -_math.inf
            if _math.log2(5e-15) + lsum > _math.log2(1e-12) + max(lr, floor):
                raise NotCovered("bessely, besselj: the connection formula for order %r cancels at x = %r" % (nu, x))
        out.append(_me_val(r))
    return out


def _bessely1(nu, x):
    if isinstance(nu, complex) or isinstance(x, complex):
        raise NotCovered("bessely: Sagebrush covers real orders and arguments")
    if _isnan(nu) or _isnan(x):
        return _math.nan
    if _math.isinf(nu):
        raise NotCovered("bessely: Sagebrush covers finite orders")
    if _math.isinf(x):
        return 0.0
    if x == 0:
        return _bessely_at0(nu)
    jc, yc = _bessel_base(nu)
    if x > 0:
        return _bessel_parts(nu, x, [yc], x)[0]
    # (DLMF 10.11.2 with m = 1, the value above the cut: Y_nu(-x) =
    # e^(-nu pi i) Y_nu(x) + 2i cos(nu pi) J_nu(x), real part cos(nu pi)
    # Y_nu(x), imaginary part -sin(nu pi) Y_nu(x) + 2 cos(nu pi) J_nu(x); for
    # integer orders (-1)^n (Y_n(x) + 2i J_n(x)))
    c, s = _cospi(nu), _sinpi(nu)
    re = (c * yc[0], c * yc[1])
    im = (-s * yc[0] + 2 * c * jc[0], -s * yc[1] + 2 * c * jc[1])
    if c == 0:
        return complex(0.0, _bessel_parts(nu, -x, [im], x)[0])
    r, i = _bessel_parts(nu, -x, [re, im], x)
    return complex(r + 0.0, i)


def _bessely_at0(nu):
    """Y_nu(0): -inf for nu >= 0; for integer nu = -n, (-1)^n (-inf); for
    other nu < 0 the limit of cos(nu pi) Y_(-nu) (the J term is 0 at 0):
    -sign(cos(nu pi)) inf, and 0 at half-integers, where Y_-(n+1/2) =
    (-1)^n J_(n+1/2) (Octave 11 agrees at each)"""
    if nu >= 0:
        return -_math.inf
    a = -nu
    if a == _math.floor(a):
        return _math.inf if int(a) % 2 else -_math.inf
    c = _cospi(a)
    if c == 0:
        return 0.0
    return -_math.inf if c > 0 else _math.inf


def bessely(nu, x):
    """the Bessel function of the second kind Y_nu(x) (DLMF 10.2.3), real
    order nu and real x.  For x > 0, nu >= 0: Hankel's expansion 10.17.4
    for x >= max(25, nu^2), with its omitted-term check; otherwise Y_mu and
    Y_(mu+1) at the low orders, by the elementary forms 10.16.1 (half-integer
    nu), Temme's series for x <= 2 (J. Comput. Phys. 21, 1976), Steed's
    method for 2 < x < 25 (Barnett et al. 1974, Thompson and Barnett 1986)
    or Hankel's expansion for x >= 25, then the recurrence 10.6.1 upward in
    double-double arithmetic, the exponent carried so that nothing
    overflows on the way; -inf where Y_nu is beyond the doubles.  Negative
    orders by 10.4.1 (integers) and the connection formula from 10.4.5,
    refused where its terms cancel; negative x by 10.11.2 (the value above
    the cut: complex).  Y_nu(0) = -inf for nu >= 0, with the parity sign for
    negative integers (Y_-1(0) = +inf), and the limit for other negative
    orders; Y_nu(+-inf) = 0.  NotCovered for complex arguments, infinite
    orders, continued fractions not converging, and recurrences beyond
    500000 steps where the value could still be a double.  Largest error
    found against mpmath, in some 76000 random points across the regions
    (orders to 1500, x from 1e-300 to 3000, negative orders and x), as a
    fraction of max(|Y|, sqrt(2/(pi |x|))) for |x| > |nu| (the envelope of
    the oscillations: an absolute accuracy next to the zeros) and of |Y|
    below: 3.1e-15; at negative non-integer orders where the connection
    formula's terms cancel, up to 200-fold before the refusal, 8.4e-16 times
    (|t1| + |t2|)/|t1 + t2|"""
    return _elementwise(_bessely1, nu, x)


# ------------------------------------------------------------------ Legendre functions

def _legendre_p1(n, x):
    if isinstance(n, complex) or n != _math.floor(n) or n < 0:
        raise NotCovered("legendre_p: Sagebrush covers integer degrees n >= 0")
    n = int(n)
    # (DLMF 14.10.3 with mu = 0, the polynomials' three-term recurrence:
    # (k + 1) P_(k+1) = (2k + 1) x P_k - k P_(k-1))
    p0, p1 = 1.0, x
    if n == 0:
        return 1.0 if not isinstance(x, complex) else 1 + 0j
    for k in range(1, n):
        p0, p1 = p1, ((2 * k + 1) * x * p1 - k * p0) / (k + 1)
    return p1


def legendre_p(n, x):
    """the Legendre polynomial P_n(x) (DLMF 14.7.1, 18.3), integer n >= 0,
    real or complex x, by the recurrence DLMF 14.10.3.  Largest error found
    against mpmath: 1e-15 of max(1, |P_n(x)|) for n <= 1000, |x| <= 1"""
    return _elementwise(_legendre_p1, n, x)


def _legendre_column(n, x):
    """the Ferrers functions P_n^m(x), m = 0..n, each as (y, E) with
    P = y 2^E: the degree recurrence DLMF 14.10.3, (k - m + 1) P_(k+1)^m =
    (2k + 1) x P_k^m - (k + m) P_(k-1)^m, whose coefficients are exact,
    from the diagonal P_m^m = (-1)^m (2m - 1)!! (1 - x^2)^(m/2) (DLMF
    14.7.8); the power of 2 kept apart, and rescaling only by powers of 2,
    so that nothing overflows or underflows on the way"""
    s = _math.sqrt(max(0.0, (1 - x) * (1 + x)))
    out = []
    d, E = 1.0, 0  # (|P_m^m| = d 2^E)
    for m in range(n + 1):
        if m:
            if s == 0:
                out.extend([(0.0, 0)] * (n + 1 - m))
                break
            d, e = _math.frexp(d * (2 * m - 1) * s)
            E += e
        y0, y1, F = 0.0, (-d if m % 2 else d), E
        for k in range(m, n):
            y0, y1 = y1, ((2 * k + 1) * x * y1 - (k + m) * y0) / (k - m + 1)
            # (on both: at x = 0 every other value is an exact 0)
            if max(abs(y0), abs(y1)) > 2.0 ** 600:
                y0, y1, F = _ldexp(y0, -600), _ldexp(y1, -600), F + 600
        out.append((y1, F))
    return out


def _legendre_column_near_1(n, x):
    """the same as _legendre_column, for n^2 (1 - |x|)/2 <= 1: next to +-1
    the recurrence's rounding grows like the second solution Q_n, and
    there the terminating hypergeometric form converges in a few terms:
    P_n^-m(x) = ((1-x)/(1+x))^(m/2) 2F1(-n, n+1; 1+m; t)/m!, t = (1-x)/2
    (DLMF 14.3.1 with mu = -m), P_n^m = (-1)^m (n+m)!/(n-m)! P_n^-m (DLMF
    14.9.3), and P_n^m(-x) = (-1)^(n-m) P_n^m(x) (DLMF 14.7.17)"""
    flip = x < 0
    t = (1 + x) / 2 if flip else (1 - x) / 2
    q = _math.sqrt(t / (1 - t))
    out = []
    qm, Eq = 1.0, 0  # (q^m = qm 2^Eq)
    for m in range(n + 1):
        if m:
            if q == 0:
                out.extend([(0.0, 0)] * (n + 1 - m))
                break
            qm, e = _math.frexp(qm * q)
            Eq += e
        S, term = 1.0, 1.0
        for k in range(n):
            term *= (k - n) * (n + 1 + k) / ((m + 1 + k) * (k + 1)) * t
            S += term
            if abs(term) <= 1e-17 * abs(S):
                break
        G = _math.perm(n + m, 2 * m) // _math.factorial(m)  # (n+m)!/((n-m)! m!), exact
        sh = max(0, G.bit_length() - 60)
        y = float(G >> sh) * qm * S
        if m % 2:
            y = -y
        if flip and (n - m) % 2:
            y = -y
        out.append((y, Eq + sh))
    return out


def _sqrt_ratio(num, den):
    """sqrt(num/den) for positive integers or floats of any size, as (f, e)
    with the value f 2^e"""
    def split(v):
        if isinstance(v, int):
            sh = max(0, v.bit_length() - 60)
            return float(v >> sh), sh
        return v, 0
    a, ea = split(num)
    b, eb = split(den)
    e = ea - eb
    q = a / b
    if e % 2:
        q *= 2
        e -= 1
    return _math.sqrt(q), e // 2


_LEGENDRE_NORMS = ("unnorm", "sch", "norm")


def legendre_all(n, x, normalization="unnorm"):
    """the associated Legendre functions of degree n and orders m = 0..n at
    a real x in [-1, 1], as a list, in the three normalizations MATLAB's
    legendre names (lib/_matlab_special.py):
    - "unnorm": the Ferrers functions P_n^m(x) = (-1)^m (1 - x^2)^(m/2)
      d^m P_n/dx^m (DLMF 14.7.8), with the Condon-Shortley phase (-1)^m;
    - "sch": Schmidt's seminormalized S_n^m = (-1)^m sqrt(2 (n-m)!/(n+m)!)
      P_n^m for m > 0, S_n^0 = P_n: without the phase;
    - "norm": N_n^m = (-1)^m sqrt((n + 1/2)(n-m)!/(n+m)!) P_n^m, whose
      squares integrate to 1 over [-1, 1]: without the phase.
    By the degree recurrence DLMF 14.10.3 (stable upward on [-1, 1]) from
    the diagonal (DLMF 14.7.8), and where n^2 (1 - |x|)/2 <= 1 by the
    terminating hypergeometric series DLMF 14.3.1 (with 14.9.3 and
    14.7.17), with the scale kept as an exact power of 2
    and the factorial ratios exact integers, so that a value is finite and
    nonzero whenever it is representable; the unnormalized values overflow
    to +-Inf for large n.  Largest error found against mpmath: 1e-14 of the
    largest |value| of the column for n <= 200"""
    if isinstance(n, complex) or n != _math.floor(n) or n < 0:
        raise NotCovered("legendre_all: Sagebrush covers integer degrees n >= 0")
    if normalization not in _LEGENDRE_NORMS:
        raise ValueError("legendre_all: normalization must be one of %s" % ", ".join(_LEGENDRE_NORMS))
    x = _scalar(x)
    if not isinstance(x, complex) and x != x:
        return [_math.nan] * (int(n) + 1)
    if isinstance(x, complex) or not -1 <= x <= 1:
        raise NotCovered("legendre_all: Sagebrush covers real x in [-1, 1]")
    n = int(n)
    res = []
    near = n * n * (1 - abs(x)) / 2 <= 1
    col = _legendre_column_near_1(n, x) if near else _legendre_column(n, x)
    for m, (y, E) in enumerate(col):
        if normalization == "unnorm" or y == 0:
            try:
                res.append(_ldexp(y, E))
            except OverflowError:
                res.append(_math.copysign(_math.inf, y))
            continue
        R = _math.perm(n + m, 2 * m)  # (n + m)!/(n - m)!, exact
        if normalization == "norm":
            f, e = _sqrt_ratio(n + 0.5, R)
        elif m == 0:
            f, e = 1.0, 0
        else:
            f, e = _sqrt_ratio(2, R)
        v = (-1) ** m * y * f
        try:
            res.append(_ldexp(v, E + e))
        except OverflowError:
            res.append(_math.copysign(_math.inf, v))
    return res


def _assoc_legendre_p1(n, m, x):
    if any(isinstance(v, complex) for v in (n, m)) or n != _math.floor(n) or m != _math.floor(m) or n < 0:
        raise NotCovered("assoc_legendre_p: Sagebrush covers integers n >= 0 and m")
    if not isinstance(x, complex) and _scalar(x) != _scalar(x):
        return _math.nan
    n, m = int(n), int(m)
    if abs(m) > n:
        return 0.0  # (DLMF 14.7.16)
    if m >= 0:
        return legendre_all(n, x)[m]
    x = _scalar(x)
    if isinstance(x, complex) or not -1 <= x <= 1:
        raise NotCovered("assoc_legendre_p: Sagebrush covers real x in [-1, 1]")
    k = -m
    col = _legendre_column_near_1(n, x) if n * n * (1 - abs(x)) / 2 <= 1 else _legendre_column(n, x)
    y, E = col[k]
    # (DLMF 14.9.3: P_n^(-k) = (-1)^k (n-k)!/(n+k)! P_n^k, from the
    # column's y 2^E and the exact integer ratio, rounded once, so that
    # values beyond P_n^k's range, and subnormal ones, are kept)
    if y == 0:
        return 0.0
    num, den = abs(y).as_integer_ratio()
    r = _round_ratio(num, den * _math.perm(n + k, 2 * k), E)
    if (y < 0) != (k % 2 == 1):
        r = -r
    return r


def _round_ratio(N, D, e):
    """N/D 2^e for positive integers N and D, rounded once to the nearest
    double (ties to even), subnormals and overflow included"""
    s = 64 + D.bit_length() - N.bit_length()
    q, rem = divmod(N << s, D) if s >= 0 else divmod(N, D << -s)
    exp = e - s  # (N/D 2^e = (q + rem/D') 2^exp)
    nb = q.bit_length()
    top = nb + exp
    if top > 1024:
        return _math.inf
    prec = 53 if top >= -1021 else 53 - (-1021 - top)
    drop = nb - prec
    if drop <= 0:
        return _ldexp(float(q), exp)
    keep = q >> drop
    low = q - (keep << drop)
    half = 1 << (drop - 1)
    if low > half or (low == half and (rem or keep & 1)):
        keep += 1
    return _ldexp(float(keep), exp + drop)


def assoc_legendre_p(n, m, x):
    """the Ferrers function (associated Legendre function on the cut)
    P_n^m(x) = (-1)^m (1 - x^2)^(m/2) d^m P_n/dx^m, DLMF 14.7.8, with the
    Condon-Shortley phase (-1)^m, for integers n >= 0 and m (0 for
    |m| > n; negative m by DLMF 14.9.3) and real x in [-1, 1]; from
    legendre_all"""
    return _elementwise(_assoc_legendre_p1, n, m, x)

files._tzrules.py:
"""Time zones from TZif data (RFC 8536) and POSIX TZ strings, for time's
localtime and mktime as CPython on glibc gives them.

The format is RFC 8536's and POSIX's. What glibc does around it (which zone
a TZ value names, the years a TZ string's rules cover, mktime's choice in a
skipped or repeated hour and for an isdst the time does not have) was found
by comparison with CPython 3.14 on glibc 2.39: no glibc source was read.
Anything outside what was compared raises ZoneUnsupported, naming it.

This module runs under CPython too (the comparison harness imports it).
zoneinfo is not built on it: CPython's zoneinfo reads TZif files and TZ
strings by rules of its own, not glibc's (lib/_zoneinfo.py); it shares only
the bounds below.
"""

# ------------------------------------------------------------------ errors


class ZoneUnsupported(Exception):
    """A zone (file or TZ string) that is not read here: why."""


# ------------------------------------------------------------------ calendar


def _days(y, m, d):
    """Days since 1970-01-01 of a proleptic Gregorian date."""
    y -= m <= 2
    era = y // 400
    yoe = y - era * 400
    doy = (153 * (m + (-3 if m > 2 else 9)) + 2) // 5 + d - 1
    return era * 146097 + yoe * 365 + yoe // 4 - yoe // 100 + doy - 719468


def _year_of(days):
    z = days + 719468
    era = z // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    return yoe + era * 400 + (mp >= 10)


def _leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


_MONTH_DAYS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)

# ------------------------------------------------------------------ TZif

# (bounds checked from the header, before anything is allocated: real zone
# files have at most a few thousand transitions, a dozen types and a few
# dozen abbreviation bytes)
MAX_FILE = 1 << 20
MAX_TIMES = 1 << 16
MAX_TYPES = 256
MAX_CHARS = 1 << 10
MAX_FOOTER = 1 << 10


def _u32(b, i):
    return (b[i] << 24) | (b[i + 1] << 16) | (b[i + 2] << 8) | b[i + 3]


def _s32(b, i):
    v = _u32(b, i)
    return v - (1 << 32) if v >= 1 << 31 else v


def _s64(b, i):
    v = (_u32(b, i) << 32) | _u32(b, i + 4)
    return v - (1 << 64) if v >= 1 << 63 else v


def _header(data, at):
    if len(data) < at + 44 or bytes(data[at:at + 4]) != b"TZif":
        raise ZoneUnsupported("not a TZif file")
    version = data[at + 4]
    if version not in (0, 0x32, 0x33, 0x34):
        raise ZoneUnsupported("a TZif version %r not read here" % chr(version))
    isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt = (_u32(data, at + 20 + 4 * k) for k in range(6))
    if timecnt > MAX_TIMES or typecnt > MAX_TYPES or charcnt > MAX_CHARS:
        raise ZoneUnsupported("a TZif file with more transitions, types or abbreviation bytes than any zone has")
    if typecnt == 0 or charcnt == 0:
        raise ZoneUnsupported("a TZif file with no time types")
    if leapcnt:
        raise ZoneUnsupported("a TZif file with leap seconds (a right/ zone)")
    if isutcnt not in (0, typecnt) or isstdcnt not in (0, typecnt):
        raise ZoneUnsupported("a malformed TZif file (its indicator counts)")
    return version, isutcnt, isstdcnt, timecnt, typecnt, charcnt


def parse_tzif(data):
    """A Zone from the bytes of a TZif file (RFC 8536, versions 1 to 4): the
    64-bit data and footer of version 2 and later, else version 1's."""
    if len(data) > MAX_FILE:
        raise ZoneUnsupported("a TZif file larger than any zone's")
    version, isutcnt, isstdcnt, timecnt, typecnt, charcnt = _header(data, 0)
    size1 = 44 + timecnt * 5 + typecnt * 6 + charcnt + isstdcnt + isutcnt
    at, tsize = 44, 4
    if version >= 0x32:
        if len(data) < size1:
            raise ZoneUnsupported("a truncated TZif file")
        version, isutcnt, isstdcnt, timecnt, typecnt, charcnt = _header(data, size1)
        at, tsize = size1 + 44, 8
    end = at + timecnt * (tsize + 1) + typecnt * 6 + charcnt + isstdcnt + isutcnt
    if len(data) < end:
        raise ZoneUnsupported("a truncated TZif file")
    read = _s64 if tsize == 8 else _s32
    times = [read(data, at + tsize * k) for k in range(timecnt)]
    at += tsize * timecnt
    index = list(data[at:at + timecnt])
    at += timecnt
    raw = []
    for k in range(typecnt):
        raw.append((_s32(data, at), data[at + 4], data[at + 5]))
        at += 6
    chars = bytes(data[at:at + charcnt])
    for k in range(1, timecnt):
        if times[k] <= times[k - 1]:
            raise ZoneUnsupported("a malformed TZif file (its transitions are not in order)")
    if any(i >= typecnt for i in index):
        raise ZoneUnsupported("a malformed TZif file (a transition's type)")
    types = []
    for utoff, isdst, ai in raw:
        if isdst > 1 or ai >= charcnt or utoff == -(1 << 31):
            raise ZoneUnsupported("a malformed TZif file (a time type)")
        z = chars.find(b"\0", ai)
        if z < 0:
            raise ZoneUnsupported("a malformed TZif file (an abbreviation)")
        try:
            abbr = chars[ai:z].decode("ascii")
        except UnicodeDecodeError:
            raise ZoneUnsupported("a TZif file with a non-ASCII abbreviation") from None
        types.append((utoff, isdst, abbr))
    rule = None
    if version >= 0x32:
        at = end
        if len(data) < at + 2 or data[at] != 0x0A:
            raise ZoneUnsupported("a malformed TZif file (its footer)")
        nl = bytes(data[at + 1:at + 2 + MAX_FOOTER]).find(b"\n")
        if nl < 0:
            raise ZoneUnsupported("a malformed TZif file (its footer)")
        footer = bytes(data[at + 1:at + 1 + nl])
        if footer:
            try:
                text = footer.decode("ascii")
            except UnicodeDecodeError:
                raise ZoneUnsupported("a malformed TZif file (its footer)") from None
            rule = parse_posix(text)
    return Zone(times, index, types, rule, from_1970=False)


# ------------------------------------------------------------------ POSIX TZ strings


def _name(s, i):
    """A std or dst name at s[i:]: (name, next index), or None."""
    if i < len(s) and s[i] == "<":
        j = s.find(">", i + 1)
        if j < 0:
            return None
        name = s[i + 1:j]
        # (ASCII letters and digits, "+" and "-" only, as glibc takes them)
        if len(name) < 3 or not all("A" <= c <= "Z" or "a" <= c <= "z" or "0" <= c <= "9" or c in "+-" for c in name):
            return None
        return name, j + 1
    j = i
    while j < len(s) and ("A" <= s[j] <= "Z" or "a" <= s[j] <= "z"):
        j += 1
    if j - i < 3:
        return None
    return s[i:j], j


def _number(s, i):
    """The digits at s[i:] (any number of them: a TZ value is at most
    MAX_PATH characters) as an int, and the next index; None if none."""
    j = i
    while j < len(s) and "0" <= s[j] <= "9":
        j += 1
    if j == i:
        return None
    return int(s[i:j]), j


def _hms(s, i, hours_max, clamp):
    """[+-]hh[:mm[:ss]] at s[i:]: (signed seconds, next index), or None.
    With clamp (an offset), each part as glibc reads it (as seen): its
    digits' value, at most 2**64 - 1, then kept to 16 bits (65541 is 5),
    then cut to 24, 59 and 59. Else (a rule's time) a part past
    hours_max, 59 or 59 is refused."""
    sign = 1
    if i < len(s) and s[i] in "+-":
        sign = -1 if s[i] == "-" else 1
        i += 1
    r = _number(s, i)
    if r is None:
        return None
    h, i = r
    m = sec = 0
    if i < len(s) and s[i] == ":":
        r = _number(s, i + 1)
        if r is None:
            return None
        m, i = r
        if i < len(s) and s[i] == ":":
            r = _number(s, i + 1)
            if r is None:
                return None
            sec, i = r
    if clamp:
        h, m, sec = (min(v, 2**64 - 1) % 65536 for v in (h, m, sec))
        h, m, sec = min(h, 24), min(m, 59), min(sec, 59)
    elif h > hours_max or m > 59 or sec > 59:
        raise ZoneUnsupported("a TZ rule time out of range")
    return sign * (h * 3600 + m * 60 + sec), i


def _date_rule(s, i):
    """Jn, n or Mm.w.d with an optional /time, at s[i:]."""
    if i < len(s) and s[i] == "J":
        r = _number(s, i + 1)
        if r is None or not 1 <= r[0] <= 365:
            raise ZoneUnsupported("a TZ rule's Julian day out of range or missing")
        rule, i = ("J", r[0]), r[1]
    elif i < len(s) and s[i] == "M":
        parts = []
        j = i + 1
        for k in range(3):
            r = _number(s, j)
            if r is None:
                raise ZoneUnsupported("a TZ rule's Mm.w.d incomplete")
            parts.append(r[0])
            j = r[1]
            if k < 2:
                if j >= len(s) or s[j] != ".":
                    raise ZoneUnsupported("a TZ rule's Mm.w.d incomplete")
                j += 1
        m, w, d = parts
        if not (1 <= m <= 12 and 1 <= w <= 5 and 0 <= d <= 6):
            raise ZoneUnsupported("a TZ rule's Mm.w.d out of range")
        rule, i = ("M", m, w, d), j
    else:
        r = _number(s, i)
        if r is None or not 0 <= r[0] <= 365:
            raise ZoneUnsupported("a TZ rule's day out of range or missing")
        rule, i = ("n", r[0]), r[1]
    t = 7200
    if i < len(s) and s[i] == "/":
        r = _hms(s, i + 1, 167, False)
        if r is None:
            raise ZoneUnsupported("a TZ rule's time missing")
        t, i = r
    return rule + (t,), i


def parse_posix(s):
    """The rule of a POSIX TZ string (a TZif footer, or a TZ value naming no
    file): std offset [dst [offset] ,start[/time],end[/time]]. A DST name
    without both rules (glibc's default rules come from a posixrules file)
    and anything malformed raise ZoneUnsupported."""
    r = _name(s, 0)
    if r is None:
        raise ZoneUnsupported("not a TZ rule (its standard time name)")
    std, i = r
    r = _hms(s, i, 24, True)
    if r is None:
        raise ZoneUnsupported("not a TZ rule (its standard time offset)")
    off, i = r
    if i == len(s):
        return Rule(std, -off, None, None, None, None)
    r = _name(s, i)
    if r is None:
        raise ZoneUnsupported("a malformed TZ rule (after its standard time)")
    dst, i = r
    doff = off - 3600
    if i < len(s) and s[i] != ",":
        r = _hms(s, i, 24, True)
        if r is None:
            raise ZoneUnsupported("a malformed TZ rule (its daylight-saving offset)")
        doff, i = r
    if i == len(s) or s[i] != ",":
        raise ZoneUnsupported("a TZ rule with daylight saving but without both of its rules")
    start, i = _date_rule(s, i + 1)
    if i == len(s) or s[i] != ",":
        raise ZoneUnsupported("a TZ rule with daylight saving but without both of its rules")
    end, i = _date_rule(s, i + 1)
    if i != len(s):
        raise ZoneUnsupported("a malformed TZ rule (text after its rules)")
    return Rule(std, -off, dst, -doff, start, end)


# (the years a TZ rule is evaluated for: matched against glibc from -5,000,000
# to 5,880,000, where its day count overflows)
RULE_YEARS = 5_000_000


def _rule_day(rule, y):
    """Days since 1970-01-01 of a rule's date in year y."""
    if rule[0] == "J":
        n = rule[1]
        return _days(y, 1, 1) + n - 1 + (1 if _leap(y) and n >= 60 else 0)
    if rule[0] == "n":
        return _days(y, 1, 1) + rule[1]
    _, m, w, d = rule[:4]
    first = _days(y, m, 1)
    day = (d - (first + 4)) % 7  # (1970-01-01 was a Thursday, weekday 4)
    day += 7 * (w - 1)
    dim = _MONTH_DAYS[m - 1] + (1 if m == 2 and _leap(y) else 0)
    while day >= dim:
        day -= 7
    return first + day


class Rule:
    """A POSIX TZ rule: standard time, and daylight saving between two
    yearly changes (each at a local time: the start in standard time, the
    end in daylight-saving time)."""

    def __init__(self, std, std_off, dst, dst_off, start, end):
        self.std, self.std_off, self.dst, self.dst_off, self.start, self.end = std, std_off, dst, dst_off, start, end

    def changes(self, y):
        """(start, end) in UTC seconds in year y."""
        s = _rule_day(self.start, y) * 86400 + self.start[-1] - self.std_off
        e = _rule_day(self.end, y) * 86400 + self.end[-1] - self.dst_off
        return s, e

    def find(self, t):
        """(utoff, isdst, abbr) at UTC second t: by the two changes of t's
        UTC year alone (a change the rules put in the year before or after
        does not count), as glibc decides (as seen). Before 1970 glibc puts
        t before both changes: daylight saving all year where the year's
        end comes before its start, none where it comes after."""
        if self.dst is None:
            return self.std_off, 0, self.std
        y = _year_of(t // 86400)
        if not -RULE_YEARS <= y <= RULE_YEARS:
            # (glibc's changes past about year 5,880,000 are not the rules'
            # (its day count overflows, as seen): not matched here)
            raise ZoneUnsupported("a TZ rule's daylight saving in year %d, past the years matched here (%d to %d)"
                                  % (y, -RULE_YEARS, RULE_YEARS))
        s, e = self.changes(y)
        if s == e:
            raise ZoneUnsupported("a TZ rule whose daylight saving starts and ends at the same instant")
        if t < 0:
            dst = s > e
        elif s < e:
            dst = s <= t < e
        else:
            dst = not e <= t < s
        if dst:
            return self.dst_off, 1, self.dst
        return self.std_off, 0, self.std


# ------------------------------------------------------------------ zones


class Zone:
    """A zone: transitions (UTC seconds, in order), each to a time type
    (utoff, isdst, abbr); before the first one, type 0 (RFC 8536); after the
    last, the footer's rule if there is one. A zone made from a TZ string
    alone has only the rule; glibc applies it from 1970 on, an earlier
    instant getting 1970-01-01's state (as seen)."""

    def __init__(self, times, index, types, rule, from_1970, names=None):
        self.times, self.index, self.types, self.rule, self.from_1970 = times, index, types, rule, from_1970
        # (glibc's tzname for a zone made from a TZ value alone: constant)
        self.names = names

    @classmethod
    def from_rule(cls, rule):
        names = [rule.std, rule.dst if rule.dst is not None else rule.std]
        return cls([], [], [], rule, True, names)

    def names_after(self, t, state):
        """glibc's tzname (the names strftime's %Z gives a time tuple with no
        zone: [isdst 0, isdst 1]) after a local time computed at UTC second
        t, from state, the names before (as seen): the found type's name for
        its isdst, and for the other isdst the next later transition's type
        of that isdst (before the first transition: the type array's first
        of that isdst), else the found type's own; after the last
        transition, the footer's [std, dst] ([std, std] without daylight
        saving)."""
        if self.names is not None:
            return list(self.names)
        if state is None:
            state = [None, None]
        times = self.times
        if times and t >= times[-1] and self.rule is not None:
            r = self.rule
            return [r.std, r.dst if r.dst is not None else r.std]
        if not times and self.rule is not None:
            r = self.rule
            return [r.std, r.dst if r.dst is not None else r.std]
        if not times or t < times[0]:
            typ, i = self.types[0], -1
        else:
            lo, hi = 0, len(times)
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if times[mid] <= t:
                    lo = mid
                else:
                    hi = mid
            i = lo
            typ = self.types[self.index[i]]
        new = list(state)
        new[typ[1]] = typ[2]
        other = 1 - typ[1]
        found = None
        if i < 0:
            for tt in self.types:
                if tt[1] == other:
                    found = tt[2]
                    break
        else:
            for j in range(i + 1, len(times)):
                tt = self.types[self.index[j]]
                if tt[1] == other:
                    found = tt[2]
                    break
        new[other] = typ[2] if found is None else found
        return new

    def find(self, t):
        """(utoff, isdst, abbr) at UTC second t."""
        times = self.times
        if times and t >= times[0]:
            lo, hi = 0, len(times)
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if times[mid] <= t:
                    lo = mid
                else:
                    hi = mid
            if lo == len(times) - 1 and self.rule is not None:
                return self.rule.find(t)
            return self.types[self.index[lo]]
        if times or self.rule is None:
            return self.types[0]
        return self.rule.find(t)


# ------------------------------------------------------------------ mktime

# (mktime's search for a time with the asked isdst, as seen: from the
# time found, 601200 s (a week less an hour) at a time, earlier first, then
# later, up to 381 steps each way)
PROBE_STEP = 601200
PROBE_STEPS = 381


def mktime(zone, w, isdst, last):
    """(t, offset) for the wall clock w (local fields as if UTC seconds) and
    the asked isdst, as mktime gives them on glibc (as seen); last is the
    offset the previous call used (0 at first), which decides a repeated
    hour asked with isdst -1, and the offset returned is the next call's."""
    want = -1 if isdst < 0 else (1 if isdst > 0 else 0)
    t = w - last
    seen = []
    while True:
        off = zone.find(t)[0]
        t2 = w - off
        if t2 == t:
            break
        if t2 in seen:
            # (a skipped hour: the offsets on either side each send w to the
            # other side, and the steps go round between two points. Sides
            # of different isdst: -1 takes the isdst 0 side's offset, 0 and 1
            # the side asked for. Sides of the same isdst s: asking for s is
            # an error (EOVERFLOW, OverflowError in CPython); anything else
            # takes the first point the steps came back to, as seen)
            a, b = zone.find(t), zone.find(t2)
            if a[1] != b[1]:
                pick = a if a[1] == (0 if want < 0 else want) else b
                return w - pick[0], pick[0]
            if want == a[1]:
                raise OverflowError("mktime argument out of range")
            return t2, w - t2
        if len(seen) > 8:
            raise ZoneUnsupported("mktime found no consistent offset")
        seen.append(t)
        t = t2
    found = zone.find(t)
    if want < 0 or found[1] == want:
        return t, found[0]
    for k in range(1, PROBE_STEPS + 1):
        for p in (t - k * PROBE_STEP, t + k * PROBE_STEP):
            other = zone.find(p)
            if other[1] == want:
                return w - other[0], other[0]
    off = found[0] + (3600 if want else -3600)
    return w - off, off


# ------------------------------------------------------------------ TZ values

DEFAULT_TZDIR = "/usr/share/zoneinfo"
DEFAULT_ZONE = "/etc/localtime"
MAX_PATH = 4096


def utc_zone(abbr="UTC"):
    return Zone([], [], [(0, 0, abbr)], None, False, [abbr, abbr])


def _fallback(name):
    """glibc's reading of a TZ value that names no zone file (as seen): a
    standard time name of 3 or more letters (else ""), its offset (else
    0, and nothing after it read), and anything after the offset as a TZ
    rule (refused if malformed)."""
    r = _name(name, 0)
    if r is None:
        return utc_zone("")
    std, i = r
    r = _hms(name, i, 24, True)
    if r is None:
        # (a name alone: glibc's tzname then has no daylight-saving name)
        return Zone([], [], [(0, 0, std)], None, False, [std, ""])
    if r[1] == len(name):
        return Zone([], [], [(-r[0], 0, std)], None, False, [std, std])
    return Zone.from_rule(parse_posix(name))


def resolve(tz, tzdir, read):
    """The zone glibc uses for the TZ value tz (None: unset) and TZDIR
    tzdir (None or "": the default), reading files with read(path), which
    returns the bytes, or None where the file cannot be read (missing, not
    permitted, a directory), and raises where reading is refused outright
    (a sandbox): glibc's fallback is for the former only."""
    if tz is None:
        data = read(DEFAULT_ZONE)
        if data is None:
            raise ZoneUnsupported("no zone: TZ is not set and %s cannot be read" % DEFAULT_ZONE)
        if bytes(data[:4]) != b"TZif":
            raise ZoneUnsupported("%s is not a TZif file" % DEFAULT_ZONE)
        return parse_tzif(data)
    name = tz[1:] if tz.startswith(":") else tz
    if name == "":
        return utc_zone()
    path = name if name.startswith("/") else (tzdir or DEFAULT_TZDIR) + "/" + name
    if len(path) > MAX_PATH or "\0" in path:
        raise ZoneUnsupported("a TZ value too long, or with a NUL character")
    data = read(path)
    if data is not None and bytes(data[:4]) == b"TZif":
        return parse_tzif(data)
    return _fallback(name)
